/// Deep-merge `over` INTO `base`: for objects, recurse key-by-key; a NULL in `over` means "leave the
/// base default" (never overwrite a real default with null); any non-object leaf in `over` replaces base.
fn merge_json(base: &mut serde_json::Value, over: serde_json::Value) {
    match (base, over) {
        (serde_json::Value::Object(b), serde_json::Value::Object(o)) => {
            for (k, v) in o {
                if v.is_null() {
                    continue;
                }
                merge_json(b.entry(k).or_insert(serde_json::Value::Null), v);
            }
        }
        (b, o) => *b = o,
    }
}

/// Load the swarm config with the STRUCT DEFAULT as the base, so a key OMITTED from config.yaml keeps the
/// intended default rather than serde's TYPE default (None/false).
///
/// `get_param::<SwarmConfig>()` deserializes the `swarm:` block directly, and serde fills a missing key with
/// the FIELD TYPE's default (None/false), NOT the `Default for SwarmConfig` value — so every non-type
/// default (e.g. `sink_max_turns: Some(120)`, the whole baked golden formula) was silently reverted whenever
/// a swarm block existed, which is always. Merging the raw config OVER `SwarmConfig::default()` fixes the
/// entire class at once, and makes the resolvers correct too (a `cfg.unwrap_or(false)` now sees the merged
/// `Some(golden)`). Falls back to the old typed read on any serialization hiccup, so it can only be safer.
fn load_config() -> SwarmConfig {
    let cfg = Config::global();
    let Ok(mut base) = serde_json::to_value(SwarmConfig::default()) else {
        return cfg
            .get_param::<SwarmConfig>(SWARM_CONFIG_KEY)
            .unwrap_or_default();
    };
    if let Ok(raw) = cfg.get(SWARM_CONFIG_KEY, false) {
        merge_json(&mut base, raw);
    }
    serde_json::from_value(base).unwrap_or_else(|_| {
        cfg.get_param::<SwarmConfig>(SWARM_CONFIG_KEY)
            .unwrap_or_default()
    })
}

fn save_config(cfg: &SwarmConfig) -> Result<()> {
    Config::global()
        .set_param(SWARM_CONFIG_KEY, cfg)
        .map_err(|e| anyhow!("failed to save swarm config: {e}"))
}

// ---------------------------------------------------------------------------------------------
// CLI surface
// ---------------------------------------------------------------------------------------------

#[derive(clap::Subcommand, Debug)]
pub enum SwarmCommand {
    /// Export the engine's authoritative control manifest without starting or probing a fleet.
    Controls {
        /// Pretty-print the JSON manifest.
        #[arg(long)]
        pretty: bool,
    },
    /// Plan a task and run it across the swarm device pool.
    Run {
        /// The task to plan and run.
        prompt: String,
        /// Final report format: `text` (default) or `json` (the enriched RunReport to stdout).
        #[arg(long = "output-format", default_value = "text")]
        output_format: String,
        /// Path for the structured JSONL event log (default: <cwd>/.swarm/run-<id>.jsonl).
        #[arg(long = "log-file")]
        log_file: Option<PathBuf>,
        /// Disable the JSONL event log.
        #[arg(long = "no-log")]
        no_log: bool,
        /// Override per-worker max turns (default: the pool's worker_max_turns).
        #[arg(long = "max-turns")]
        max_turns: Option<u32>,
        /// Enable an MCP worker extension for this run (repeatable): context7 | web-search | doc-processor.
        #[arg(long = "mcp")]
        mcp: Vec<String>,
        /// Force the research-planning phase on/off for this run (overrides the configured mode).
        #[arg(long = "research")]
        research: Option<bool>,
        /// Force dynamic replanning on/off for this run (overrides the configured setting).
        #[arg(long = "dynamic-replan")]
        dynamic_replan: Option<bool>,
        /// Draft N plan skeletons in parallel and pick the best (overrides config; 1 = off).
        #[arg(long = "best-of-n")]
        best_of_n: Option<usize>,
    },
    /// View and manage the swarm device pool (interactive menu when no subcommand is given).
    Pool {
        #[command(subcommand)]
        command: Option<PoolCommand>,
    },
    /// Amazon Bedrock cloud nodes (alias for `cloud bedrock`).
    Bedrock {
        #[command(subcommand)]
        command: Option<CloudCommand>,
    },
    /// Cloud swarm nodes from any supported provider: validate/store an API key, auto-populate
    /// the usable model ids, and add per-model swarm devices (mix cloud models into the fleet).
    /// Providers: bedrock, zai (GLM), google (Gemini), deepseek.
    Cloud {
        /// One of: bedrock | zai | google | deepseek.
        provider: String,
        #[command(subcommand)]
        command: Option<CloudCommand>,
    },
    /// REPLAY the delivery gate against an existing build tree — the spec-contract check (advertised
    /// entry boots, every advertised invocation boots, advertised endpoints answer) without a run.
    ///
    /// A gate or boot fix used to be testable only by launching a multi-hour build. This makes it a
    /// minutes-long command against a tree that already exists, which is the difference between
    /// proving a fix and hoping for one.
    #[command(
        about = "Replay the delivery gate (spec-contract + boot probes) against a built tree"
    )]
    Gate {
        /// The build tree to check (contains app/, tests/, …).
        tree: PathBuf,
        /// Spec file. Default: the prompt recorded in the tree's own run log.
        #[arg(long)]
        spec: Option<PathBuf>,
    },
    /// Serve the swarm as an MCP extension over stdio, so an interactive `goose session` can offload work
    /// to the local worker fleet. Scaffold: a read-only `swarm_status` tool (async dispatch/collect later).
    #[command(
        about = "Serve the swarm as an MCP extension over stdio (goose session --with-extension)"
    )]
    Serve,
}

/// Options for a `goose swarm run`.
pub struct RunOpts {
    pub prompt: String,
    pub output_format: String,
    pub log_file: Option<PathBuf>,
    pub no_log: bool,
    pub max_turns: Option<u32>,
    pub mcp: Vec<String>,
    pub research: Option<bool>,
    pub dynamic_replan: Option<bool>,
    pub best_of_n: Option<usize>,
}

#[derive(clap::Subcommand, Debug)]
pub enum PoolCommand {
    /// Print the current pool.
    Show,
    /// Add a device.
    Add {
        id: String,
        model_id: String,
        #[arg(default_value_t = 1)]
        weight: u32,
        #[arg(default_value_t = 1)]
        instances: u32,
    },
    /// Remove a device by id.
    Rm { id: String },
    /// Set a device's weight.
    Weight { id: String, weight: u32 },
    /// Enable a device.
    Enable { id: String },
    /// Disable a device.
    Disable { id: String },
    /// Probe the live fleet (lms ps + the endpoint's model ids).
    Probe,
    /// Import every model loaded across the fleet (parses `lms ps`) as pool entries.
    Import {
        #[arg(long, default_value_t = 1)]
        weight: u32,
        #[arg(long)]
        disabled: bool,
    },
}

#[derive(clap::Subcommand, Debug)]
pub enum CloudCommand {
    /// Validate a Bedrock API key against the region, store it (AWS_BEARER_TOKEN_BEDROCK secret +
    /// AWS_REGION) ONLY if it is good, then print the auto-populated model roster.
    Key {
        key: String,
        /// AWS region the key targets (default: the stored/env AWS_REGION, else us-east-1).
        #[arg(long)]
        region: Option<String>,
        /// Machine-readable output: {"region","models":[...]} on stdout (for the desktop app).
        #[arg(long)]
        json: bool,
    },
    /// Re-validate the stored/env key and print the usable model ids (the auto-populated roster).
    Models {
        /// Machine-readable output: {"region","models":[...],"devices":[...]} on stdout.
        #[arg(long)]
        json: bool,
    },
    /// Add a Bedrock model as a swarm device (checked against the live roster first).
    Add {
        model_id: String,
        /// Concurrent tasks this cloud node may run at once.
        #[arg(long, default_value_t = 2)]
        weight: u32,
    },
    /// Remove a Bedrock swarm device by model id.
    Rm { model_id: String },
}

/// The cloud providers the swarm can add nodes from. `name` is what `SwarmDevice.provider`
/// stores and what the CLI/desktop present; `registry` is the goose provider factory's EXACT
/// key (the two differ — storing "bedrock" while the registry says "aws_bedrock" was a live
/// dispatch bug the provider-recon audit caught before any run hit it).
struct CloudDef {
    name: &'static str,
    registry: &'static str,
    secret_key: &'static str,
    needs_region: bool,
    label: &'static str,
}

const CLOUD_DEFS: &[CloudDef] = &[
    CloudDef {
        name: "bedrock",
        registry: "aws_bedrock",
        secret_key: "AWS_BEARER_TOKEN_BEDROCK",
        needs_region: true,
        label: "Amazon Bedrock",
    },
    CloudDef {
        name: "zai",
        registry: "zai",
        secret_key: "ZHIPU_API_KEY",
        needs_region: false,
        label: "Z.ai",
    },
    CloudDef {
        name: "google",
        registry: "google",
        secret_key: "GOOGLE_API_KEY",
        needs_region: false,
        label: "Google Gemini",
    },
    CloudDef {
        name: "deepseek",
        registry: "custom_deepseek",
        secret_key: "DEEPSEEK_API_KEY",
        needs_region: false,
        label: "DeepSeek",
    },
];

fn cloud_def(name: &str) -> Option<&'static CloudDef> {
    let lower = name.to_lowercase();
    CLOUD_DEFS.iter().find(|d| d.name == lower)
}

/// goose provider-registry key for a swarm cloud provider name; identity for anything unmapped
/// (the local "lmstudio" and forward-compat names pass through).
fn cloud_registry_name(name: &str) -> &str {
    cloud_def(name).map(|d| d.registry).unwrap_or(name)
}

/// The stored/ambient key for a cloud provider: env first (a harness override), then the goose
/// secret store — the same precedence the provider's own from_env uses, so a key that validates
/// here is exactly the key the dispatcher's provider will read.
fn cloud_stored_key(def: &CloudDef) -> Option<String> {
    std::env::var(def.secret_key)
        .ok()
        .filter(|s| !s.trim().is_empty())
        .or_else(|| {
            goose::config::Config::global()
                .get_secret::<String>(def.secret_key)
                .ok()
        })
}

/// The provider's usable model ids, fetched with ONLY the API key — the shared
/// validate-by-listing seam. A rejection is a bad key; a listing is both proof and roster.
async fn cloud_roster(provider: &str, key: &str, region: &str) -> Result<Vec<String>> {
    match provider {
        "bedrock" => bedrock_roster(key, region).await,
        // OpenAI-shaped /models listings (Authorization: Bearer).
        "zai" => openai_style_roster("https://api.z.ai/api/paas/v4/models", key, "Z.ai").await,
        "deepseek" => openai_style_roster("https://api.deepseek.com/models", key, "DeepSeek").await,
        "google" => google_roster(key).await,
        other => anyhow::bail!(
            "unknown cloud provider '{other}' — one of: bedrock, zai, google, deepseek"
        ),
    }
}

/// GET an OpenAI-shaped model listing (`{"data":[{"id":…}]}`) with a bearer key. Pure transport;
/// 401/403 = the key is bad, anything non-2xx is reported verbatim.
async fn openai_style_roster(url: &str, key: &str, label: &str) -> Result<Vec<String>> {
    let resp = reqwest::Client::new()
        .get(url)
        .bearer_auth(key)
        .timeout(std::time::Duration::from_secs(20))
        .send()
        .await
        .map_err(|e| anyhow!("cannot reach {label}: {e}"))?;
    let status = resp.status();
    if status.as_u16() == 401 || status.as_u16() == 403 {
        anyhow::bail!("{label} REJECTED the API key (HTTP {status}) — bad, expired, or revoked");
    }
    if !status.is_success() {
        anyhow::bail!("{label} answered HTTP {status} listing models");
    }
    let v: serde_json::Value = resp
        .json()
        .await
        .map_err(|e| anyhow!("{label} model listing was not JSON: {e}"))?;
    let mut ids: Vec<String> = v["data"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|m| m["id"].as_str().map(str::to_string))
        .collect();
    ids.sort();
    ids.dedup();
    if ids.is_empty() {
        anyhow::bail!("{label} accepted the key but returned no model ids");
    }
    Ok(ids)
}

/// Gemini's model listing with the provider's own auth scheme (x-goog-api-key), paginated —
/// the in-repo provider never paginates and the catalog exceeds one page. Only models that can
/// generateContent are runnable as swarm nodes. Google answers a BAD key with HTTP 400
/// (API_KEY_INVALID), not 401 — treated as rejection.
async fn google_roster(key: &str) -> Result<Vec<String>> {
    let client = reqwest::Client::new();
    let mut ids: Vec<String> = Vec::new();
    let mut token: Option<String> = None;
    loop {
        let url = match &token {
            Some(t) => format!(
                "https://generativelanguage.googleapis.com/v1beta/models?pageSize=1000&pageToken={t}"
            ),
            None => {
                "https://generativelanguage.googleapis.com/v1beta/models?pageSize=1000".to_string()
            }
        };
        let resp = client
            .get(&url)
            .header("x-goog-api-key", key)
            .timeout(std::time::Duration::from_secs(20))
            .send()
            .await
            .map_err(|e| anyhow!("cannot reach Google Gemini: {e}"))?;
        let status = resp.status();
        if matches!(status.as_u16(), 400 | 401 | 403) {
            anyhow::bail!(
                "Google Gemini REJECTED the API key (HTTP {status}) — bad, expired, or restricted"
            );
        }
        if !status.is_success() {
            anyhow::bail!("Google Gemini answered HTTP {status} listing models");
        }
        let v: serde_json::Value = resp
            .json()
            .await
            .map_err(|e| anyhow!("Gemini model listing was not JSON: {e}"))?;
        ids.extend(google_ids_from_models(&v));
        token = v["nextPageToken"].as_str().map(str::to_string);
        if token.is_none() {
            break;
        }
    }
    ids.sort();
    ids.dedup();
    if ids.is_empty() {
        anyhow::bail!("the key authenticates but no generateContent-capable models came back");
    }
    Ok(ids)
}

/// generateContent-capable model ids from a Gemini ListModels page ("models/x" -> "x").
/// Pure/testable.
fn google_ids_from_models(v: &serde_json::Value) -> Vec<String> {
    v["models"]
        .as_array()
        .into_iter()
        .flatten()
        .filter(|m| {
            m["supportedGenerationMethods"]
                .as_array()
                .is_some_and(|a| a.iter().any(|x| x.as_str() == Some("generateContent")))
        })
        .filter_map(|m| {
            m["name"]
                .as_str()
                .map(|s| s.strip_prefix("models/").unwrap_or(s).to_string())
        })
        .collect()
}

fn bedrock_stored_region() -> Option<String> {
    std::env::var("AWS_REGION")
        .ok()
        .filter(|s| !s.trim().is_empty())
        .or_else(|| {
            goose::config::Config::global()
                .get_param::<String>("AWS_REGION")
                .ok()
        })
}

/// Validate the key by LISTING what it can use: the region's system-defined inference profiles
/// (the ids cross-region models must be invoked by) plus on-demand streaming text models. A 200
/// proves the key; 401/403 is a bad/expired/mis-region key, reported as such. Sorted, deduped.
async fn bedrock_roster(key: &str, region: &str) -> Result<Vec<String>> {
    let client = reqwest::Client::new();
    let base = format!("https://bedrock.{region}.amazonaws.com");
    let fetch = |path: String| {
        let client = client.clone();
        let base = base.clone();
        let key = key.to_string();
        async move {
            let resp = client
                .get(format!("{base}{path}"))
                .bearer_auth(&key)
                .timeout(std::time::Duration::from_secs(20))
                .send()
                .await
                .map_err(|e| anyhow!("cannot reach Bedrock in {region}: {e}"))?;
            let status = resp.status();
            if status.as_u16() == 401 || status.as_u16() == 403 {
                anyhow::bail!(
                    "Bedrock in {region} REJECTED the API key (HTTP {status}) — bad, expired, or \
                     issued for a different region"
                );
            }
            if !status.is_success() {
                anyhow::bail!("Bedrock {region}{path} answered HTTP {status}");
            }
            resp.json::<serde_json::Value>()
                .await
                .map_err(|e| anyhow!("Bedrock {path} answer was not JSON: {e}"))
        }
    };
    let mut ids: Vec<String> = Vec::new();
    // Cross-region inference profiles: what modern Anthropic/Meta models must be called by.
    let mut token: Option<String> = None;
    loop {
        let q = match &token {
            Some(t) => format!(
                "/inference-profiles?maxResults=1000&typeEquals=SYSTEM_DEFINED&nextToken={t}"
            ),
            None => "/inference-profiles?maxResults=1000&typeEquals=SYSTEM_DEFINED".to_string(),
        };
        let v = fetch(q).await?;
        ids.extend(bedrock_ids_from_profiles(&v));
        token = v["nextToken"].as_str().map(str::to_string);
        if token.is_none() {
            break;
        }
    }
    // On-demand streaming text models (older/regional ids callable directly).
    let v = fetch("/foundation-models".to_string()).await?;
    ids.extend(bedrock_ids_from_models(&v));
    ids.sort();
    ids.dedup();
    if ids.is_empty() {
        anyhow::bail!(
            "the key authenticates in {region} but no usable (streaming text) model ids came back — \
             the key's policy may not grant model access in this region"
        );
    }
    Ok(ids)
}

/// ACTIVE system-defined inference profile ids from a ListInferenceProfiles page. Pure/testable.
fn bedrock_ids_from_profiles(v: &serde_json::Value) -> Vec<String> {
    v["inferenceProfileSummaries"]
        .as_array()
        .into_iter()
        .flatten()
        .filter(|p| p["status"].as_str() == Some("ACTIVE"))
        .filter_map(|p| p["inferenceProfileId"].as_str().map(str::to_string))
        .collect()
}

/// On-demand STREAMING TEXT model ids from a ListFoundationModels answer — what an agent can
/// actually run on. Image/embedding models and provisioned-only ids are excluded. Pure/testable.
fn bedrock_ids_from_models(v: &serde_json::Value) -> Vec<String> {
    v["modelSummaries"]
        .as_array()
        .into_iter()
        .flatten()
        .filter(|m| {
            let has = |field: &str, want: &str| {
                m[field]
                    .as_array()
                    .is_some_and(|a| a.iter().any(|x| x.as_str() == Some(want)))
            };
            has("outputModalities", "TEXT")
                && has("inferenceTypesSupported", "ON_DEMAND")
                && m["responseStreamingSupported"].as_bool().unwrap_or(false)
        })
        .filter_map(|m| m["modelId"].as_str().map(str::to_string))
        .collect()
}

/// The spec a tree was built from: an explicit file, else the `run_started.prompt` recorded in the
/// tree's own run log (searched recursively — the bench harness nests its log path).
fn spec_for_tree(tree: &Path, spec: Option<PathBuf>) -> Result<String> {
    if let Some(p) = spec {
        return std::fs::read_to_string(&p).map_err(|e| anyhow!("reading {}: {e}", p.display()));
    }
    let mut logs: Vec<PathBuf> = Vec::new();
    fn walk(dir: &Path, out: &mut Vec<PathBuf>, depth: usize) {
        if depth > 4 {
            return;
        }
        let Ok(rd) = std::fs::read_dir(dir) else {
            return;
        };
        for e in rd.flatten() {
            let p = e.path();
            if p.is_dir() && !p.ends_with(".swarm") {
                walk(&p, out, depth + 1);
            } else if p.file_name().is_some_and(|n| n == "run.jsonl") {
                out.push(p);
            }
        }
    }
    walk(tree, &mut logs, 0);
    for log in logs {
        let Ok(text) = std::fs::read_to_string(&log) else {
            continue;
        };
        for line in text.lines() {
            let Ok(v) = serde_json::from_str::<serde_json::Value>(line) else {
                continue;
            };
            if v.get("event").and_then(|e| e.as_str()) == Some("run_started") {
                if let Some(p) = v.get("prompt").and_then(|p| p.as_str()) {
                    return Ok(p.to_string());
                }
            }
        }
    }
    Err(anyhow!(
        "no spec: pass --spec <file>, or build the tree with a run log carrying run_started.prompt"
    ))
}

async fn handle_gate(tree: PathBuf, spec: Option<PathBuf>) -> Result<()> {
    if !tree.is_dir() {
        anyhow::bail!("{} is not a directory", tree.display());
    }
    let spec_text = spec_for_tree(&tree, spec)?;
    let existing = existing_files_manifest(&tree);
    let lang = detect_language(&spec_text, &existing);
    eprintln!(
        "gate replay: {} | spec {} chars | lang {:?} | {} existing file(s)",
        tree.display(),
        spec_text.len(),
        lang,
        existing.len()
    );
    let r = run_spec_contract(&tree, &spec_text, lang).await;
    println!(
        "{}",
        serde_json::json!({
            "tree": tree.display().to_string(),
            "verified": r.verified,
            "findings": r.findings,
            "inconclusive": r.inconclusive,
        })
    );
    if r.findings.is_empty() && r.verified > 0 {
        eprintln!(
            "gate replay: PASS — {} advertised check(s) verified",
            r.verified
        );
    } else if r.findings.is_empty() {
        eprintln!("gate replay: INCONCLUSIVE — nothing was affirmatively verified");
    } else {
        eprintln!("gate replay: {} FINDING(S)", r.findings.len());
        for f in &r.findings {
            eprintln!("  · {f}");
        }
    }
    Ok(())
}

async fn handle_cloud(def: &'static CloudDef, cmd: Option<CloudCommand>) -> Result<()> {
    let label = def.label;
    let name = def.name;
    let need_key =
        || {
            cloud_stored_key(def).ok_or_else(|| {
                anyhow!(
                "no {label} API key stored — set one with `goose swarm cloud {name} key <KEY>{}` \
                 (or export {})",
                if def.needs_region { " --region <REGION>" } else { "" },
                def.secret_key
            )
            })
        };
    let region_now = || {
        if def.needs_region {
            bedrock_stored_region().unwrap_or_else(|| "us-east-1".to_string())
        } else {
            String::new()
        }
    };
    let print_roster = |region: &str, roster: &[String]| {
        println!(
            "{label} key is GOOD{} — {} usable model id(s):",
            if region.is_empty() {
                String::new()
            } else {
                format!(" in {region}")
            },
            roster.len()
        );
        for id in roster {
            println!("  {id}");
        }
        println!(
            "\nAdd one as a swarm node:  goose swarm cloud {name} add <model-id> [--weight N]"
        );
    };
    match cmd {
        Some(CloudCommand::Key { key, region, json }) => {
            let region = if def.needs_region {
                region.unwrap_or_else(region_now)
            } else {
                String::new()
            };
            let roster = cloud_roster(name, &key, &region).await?;
            let config = goose::config::Config::global();
            config.set_secret(def.secret_key, &serde_json::json!(key))?;
            if def.needs_region {
                config.set_param("AWS_REGION", serde_json::json!(region.clone()))?;
            }
            if json {
                println!(
                    "{}",
                    serde_json::json!({ "provider": name, "region": region, "models": roster })
                );
            } else {
                println!("key validated and stored.");
                print_roster(&region, &roster);
            }
            Ok(())
        }
        None | Some(CloudCommand::Models { json: false }) => {
            let key = need_key()?;
            let region = region_now();
            let roster = cloud_roster(name, &key, &region).await?;
            print_roster(&region, &roster);
            let cfg = load_config();
            let mine: Vec<&SwarmDevice> = cfg
                .devices
                .iter()
                .filter(|d| d.provider_name() == name)
                .collect();
            if !mine.is_empty() {
                println!("\nConfigured {label} swarm nodes:");
                for d in mine {
                    println!(
                        "  {} → {} (weight {}{})",
                        d.id,
                        d.model_id,
                        d.weight,
                        if d.enabled { "" } else { ", DISABLED" }
                    );
                }
            }
            Ok(())
        }
        Some(CloudCommand::Models { json: true }) => {
            let key = need_key()?;
            let region = region_now();
            let roster = cloud_roster(name, &key, &region).await?;
            let cfg = load_config();
            let devices: Vec<serde_json::Value> = cfg
                .devices
                .iter()
                .filter(|d| d.provider_name() == name)
                .map(|d| {
                    serde_json::json!({
                        "id": d.id, "model_id": d.model_id, "weight": d.weight,
                        "enabled": d.enabled,
                    })
                })
                .collect();
            println!(
                "{}",
                serde_json::json!({
                    "provider": name, "region": region, "models": roster, "devices": devices
                })
            );
            Ok(())
        }
        Some(CloudCommand::Add { model_id, weight }) => {
            let key = need_key()?;
            let region = region_now();
            let roster = cloud_roster(name, &key, &region).await?;
            if !roster.contains(&model_id) {
                let near: Vec<&String> = roster
                    .iter()
                    .filter(|r| {
                        let m = model_id.to_lowercase();
                        r.to_lowercase().contains(&m)
                            || m.split(['-', '.'])
                                .filter(|t| t.len() > 3)
                                .any(|t| r.to_lowercase().contains(t))
                    })
                    .take(8)
                    .collect();
                anyhow::bail!(
                    "'{model_id}' is not in the key's usable {label} roster.{}",
                    if near.is_empty() {
                        format!(" Run `goose swarm cloud {name} models` for the full list.")
                    } else {
                        format!(
                            " Closest usable ids:\n  {}",
                            near.iter()
                                .map(|s| s.as_str())
                                .collect::<Vec<_>>()
                                .join("\n  ")
                        )
                    }
                );
            }
            let mut cfg = load_config();
            if cfg
                .devices
                .iter()
                .any(|d| d.provider_name() == name && d.model_id == model_id)
            {
                println!("'{model_id}' is already a configured {label} node.");
                return Ok(());
            }
            let id = format!("{name}-{}", model_id.replace([':', '.', '/'], "-"));
            cfg.devices.push(SwarmDevice {
                id: id.clone(),
                model_id: model_id.clone(),
                weight,
                enabled: true,
                instances: 1,
                host: Some(name.to_string()),
                provider: Some(name.to_string()),
                physical: None,
            });
            save_config(&cfg)?;
            println!(
                "added cloud node '{id}' → {model_id} (weight {weight}) — the swarm dispatches to \
                 it on the next run"
            );
            Ok(())
        }
        Some(CloudCommand::Rm { model_id }) => {
            let mut cfg = load_config();
            let before = cfg.devices.len();
            cfg.devices
                .retain(|d| !(d.provider_name() == name && d.model_id == model_id));
            if cfg.devices.len() == before {
                anyhow::bail!("no configured {label} node has model id '{model_id}'");
            }
            save_config(&cfg)?;
            println!("removed the {label} node for {model_id}");
            Ok(())
        }
    }
}

pub async fn handle_swarm(cmd: SwarmCommand) -> Result<()> {
    match cmd {
        SwarmCommand::Controls { pretty } => {
            let manifest = control_registry_export();
            if pretty {
                println!("{}", serde_json::to_string_pretty(&manifest)?);
            } else {
                println!("{}", serde_json::to_string(&manifest)?);
            }
            Ok(())
        }
        SwarmCommand::Run {
            prompt,
            output_format,
            log_file,
            no_log,
            max_turns,
            mcp,
            research,
            dynamic_replan,
            best_of_n,
        } => {
            run_swarm(RunOpts {
                prompt,
                output_format,
                log_file,
                no_log,
                max_turns,
                mcp,
                research,
                dynamic_replan,
                best_of_n,
            })
            .await
        }
        SwarmCommand::Pool { command } => match command {
            None => pool_menu(),
            Some(pc) => pool_op(pc),
        },
        SwarmCommand::Bedrock { command } => {
            handle_cloud(
                cloud_def("bedrock").expect("bedrock is in CLOUD_DEFS"),
                command,
            )
            .await
        }
        SwarmCommand::Gate { tree, spec } => handle_gate(tree, spec).await,
        SwarmCommand::Cloud { provider, command } => match cloud_def(&provider) {
            Some(def) => handle_cloud(def, command).await,
            None => Err(anyhow!(
                "unknown cloud provider '{provider}' — one of: bedrock, zai, google, deepseek"
            )),
        },
        SwarmCommand::Serve => crate::commands::swarm_serve::run().await,
    }
}

