    #[test]
    fn source_quotes_require_exact_bytes_locator_and_assigned_extension() {
        let document_url = "https://docs.example.test/reference";
        let source_id = format!("document:{document_url}");
        let question = ResearchQuestion {
            id: "question-reference".to_string(),
            semantic_gap_id: "gap-reference".to_string(),
            question: "Which response field is required?".to_string(),
            kind: "web".to_string(),
            requirement_ids: vec!["target-reference".to_string()],
            evidence_needed: "The exact required response field.".to_string(),
            applicable_source_ids: vec![source_id.clone()],
        };
        let receipt = ResearchSourceReceipt {
            source_id: source_id.clone(),
            tool_name: "engine__document-prefetch".to_string(),
            resolved_locator: document_url.to_string(),
            request_text: serde_json::json!({"requested_url": document_url}).to_string(),
            result_text: "The response must include field alpha_id.".to_string(),
        };
        let packet = |quote_source: &str, locator: &str| {
            serde_json::json!({
                "question_id": question.id,
                "complete": true,
                "disposition": "found",
                "findings": "The required response field is established by the assigned source.",
                "source_quotes": [{
                    "source_id": quote_source,
                    "locator": locator,
                    "quote": "must include field alpha_id"
                }]
            })
            .to_string()
        };
        let compiled = compile_research_evidence_worker(
            &packet(&source_id, document_url),
            &question,
            std::slice::from_ref(&receipt),
            Path::new("."),
        )
        .unwrap();
        assert_eq!(compiled.verified_quotes.len(), 1);
        assert!(
            compile_research_evidence_worker(
                &packet(&source_id, "https://other.example.test/reference"),
                &question,
                &[receipt],
                Path::new("."),
            )
            .is_err(),
            "authentic bytes from the wrong URL are not assigned-source proof"
        );

        let extension_question = ResearchQuestion {
            id: "question-library".to_string(),
            semantic_gap_id: "gap-library".to_string(),
            question: "Which library symbol is current?".to_string(),
            kind: "library_docs".to_string(),
            requirement_ids: vec!["target-library".to_string()],
            evidence_needed: "The current library symbol.".to_string(),
            applicable_source_ids: vec!["extension:context7".to_string()],
        };
        let context7_receipt = ResearchSourceReceipt {
            source_id: "extension:context7".to_string(),
            tool_name: "context7__query-docs".to_string(),
            resolved_locator: "library-alpha".to_string(),
            request_text: "library-alpha current symbol".to_string(),
            result_text: "library-alpha exports alpha_symbol".to_string(),
        };
        let cross_extension = serde_json::json!({
            "question_id": extension_question.id,
            "complete": true,
            "disposition": "found",
            "findings": "A symbol was returned, but the quote names the wrong source.",
            "source_quotes": [{
                "source_id": "extension:web-search",
                "locator": "library-alpha",
                "quote": "exports alpha_symbol"
            }]
        })
        .to_string();
        assert!(
            compile_research_evidence_worker(
                &cross_extension,
                &extension_question,
                &[context7_receipt],
                Path::new("."),
            )
            .is_err(),
            "a quote from another extension cannot satisfy the assigned source"
        );
    }

    #[tokio::test]
    async fn bound_document_gap_prefetches_the_exact_assigned_source() {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let document_url = format!("http://{address}/v3/docs");
        let source_id = format!("document:{document_url}");
        let body = "The v3 webhook registration symbol is register_webhook_v3(callback_url).";
        let server = tokio::spawn(async move {
            let (mut socket, _) = listener.accept().await.unwrap();
            let mut request = vec![0u8; 4096];
            let read = socket.read(&mut request).await.unwrap();
            let request = String::from_utf8_lossy(&request[..read]).to_string();
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nContent-Type: text/plain\r\nConnection: close\r\n\r\n{}",
                body.len(),
                body
            );
            socket.write_all(response.as_bytes()).await.unwrap();
            request
        });
        let question = ResearchQuestion {
            id: "question-v3-webhook-registration".to_string(),
            semantic_gap_id: "gap-v3-webhook-registration".to_string(),
            question: "Which exact v3 webhook registration symbol is exposed?".to_string(),
            kind: "library_docs".to_string(),
            requirement_ids: vec!["REQ-v3-webhook-registration".to_string()],
            evidence_needed: "The exact v3 symbol and callback signature.".to_string(),
            applicable_source_ids: vec![source_id.clone()],
        };
        let receipts = tokio::time::timeout(
            std::time::Duration::from_secs(5),
            prefetch_assigned_engine_sources(&question, Path::new(".")),
        )
        .await
        .expect("the assigned document fetch did not return")
        .expect("the engine-owned assigned document fetch failed");
        assert_eq!(receipts.len(), 1);
        assert_eq!(receipts[0].source_id, source_id);
        assert_eq!(receipts[0].tool_name, "engine__document-prefetch");
        assert_eq!(receipts[0].resolved_locator, document_url);
        assert_eq!(receipts[0].result_text, body);
        let request = server.await.unwrap();
        assert!(request.starts_with("GET /v3/docs HTTP/1.1\r\n"));
        let compiled = compile_research_evidence_worker(
            &serde_json::json!({
                "question_id": question.id,
                "complete": true,
                "disposition": "found",
                "findings": "The assigned v3 document supplies the exact webhook symbol.",
                "source_quotes": [{
                    "source_id": source_id,
                    "locator": document_url,
                    "quote": "register_webhook_v3(callback_url)"
                }]
            })
            .to_string(),
            &question,
            &receipts,
            Path::new("."),
        )
        .expect("the fetched exact quote must compile as Found authority evidence");
        assert_eq!(compiled.verified_quotes.len(), 1);
    }

    #[test]
    fn relax_contracted_deps_flattens_chain_keeps_sink_and_tests() {
        fn deps(plan: &serde_json::Value, id: &str) -> String {
            plan["subtasks"]
                .as_array()
                .unwrap()
                .iter()
                .find(|s| s["id"] == id)
                .unwrap()["depends_on"]
                .as_array()
                .unwrap()
                .iter()
                .filter_map(|d| d.as_str())
                .collect::<Vec<_>>()
                .join(",")
        }
        // The measured nf-hexohm serial chain (core-types owns Cargo.toml) plus a per-module test that
        // genuinely runs against its module.
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"core-types","depends_on":[],"files":["Cargo.toml","core/src/lib.rs","core/src/board.rs"]},
                {"id":"core-eval","depends_on":["core-types"],"files":["core/src/resistance.rs","core/src/eval.rs"]},
                {"id":"core-search","depends_on":["core-eval"],"files":["core/src/search.rs","core/src/solve.rs"]},
                {"id":"cli","depends_on":["core-search"],"files":["src/main.rs"]},
                {"id":"test-core-eval","depends_on":["core-eval"],"files":["core/src/eval_test.rs"]},
                {"id":"integrate-verify","depends_on":["core-types","core-eval","core-search","cli","test-core-eval"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let n = relax_contracted_module_deps(&mut plan, TargetLang::Rust);
        // every code module is now a root — the fleet can build all of them at once (no Cargo.toml ordering:
        // the per-worker gate no-ops without it and the sink owns the only real compile)
        assert_eq!(deps(&plan, "core-types"), "");
        assert_eq!(deps(&plan, "core-eval"), "");
        assert_eq!(deps(&plan, "core-search"), "");
        assert_eq!(deps(&plan, "cli"), "");
        // the per-module test is UNTOUCHED (signature-only contract cannot let it RUN against the module)
        assert_eq!(deps(&plan, "test-core-eval"), "core-eval");
        // the join still waits on everyone — compile/verify happens here, correctness preserved
        assert_eq!(
            deps(&plan, "integrate-verify"),
            "core-types,core-eval,core-search,cli,test-core-eval"
        );
        // dropped exactly: core-eval<-core-types, core-search<-core-eval, cli<-core-search
        assert_eq!(n, 3);
    }

    #[test]
    fn relax_contracted_deps_noop_on_flat_fan() {
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["a.py"]},
                {"id":"b","depends_on":[],"files":["b.py"]},
                {"id":"integrate-verify","depends_on":["a","b"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let before = plan.clone();
        let n = relax_contracted_module_deps(&mut plan, TargetLang::Python);
        assert_eq!(n, 0, "already a fan -> nothing to relax");
        assert_eq!(plan, before, "flat-fan plan left byte-identical");
    }

    // ---- SINK DECOMPOSITION (fan-verify) ---------------------------------------------------
    fn fv_deps(plan: &serde_json::Value, id: &str) -> String {
        plan["subtasks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|s| s["id"] == id)
            .unwrap()["depends_on"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|d| d.as_str())
            .collect::<Vec<_>>()
            .join(",")
    }
    fn fv_task<'a>(plan: &'a serde_json::Value, id: &str) -> Option<&'a serde_json::Value> {
        plan["subtasks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|s| s["id"] == id)
    }

    #[test]
    fn fan_verify_split_skips_docs_only_modules() {
        // A `readme` module owning only markdown got a verify:: gate whose spec is
        // import/build-check language — a 27B dispatched to import-check MARKDOWN (operator
        // report). Docs-only modules have no isolated surface; mixed modules still fan.
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"core","depends_on":[],"files":["core.py"]},
                {"id":"readme","depends_on":["core"],"files":["README.md"]},
                {"id":"docs","depends_on":["core"],"files":["docs/guide.md","LICENSE"]},
                {"id":"web","depends_on":["core"],"files":["web/index.html","web/README.md"]},
                {"id":"integrate-verify","depends_on":["core","readme","docs","web"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let n = fan_verify_split(&mut plan, TargetLang::Python);
        assert_eq!(n, 2, "core and web fan; readme and docs do not");
        assert!(fv_task(&plan, "verify::core").is_some());
        assert!(
            fv_task(&plan, "verify::web").is_some(),
            "a module with ANY checkable file still gets its gate"
        );
        assert!(fv_task(&plan, "verify::readme").is_none());
        assert!(fv_task(&plan, "verify::docs").is_none());
    }

    #[test]
    fn fan_verify_split_emits_per_module_verify_and_thin_join() {
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"core","depends_on":[],"files":["core.py"]},
                {"id":"cli","depends_on":["core"],"files":["cli.py"]},
                {"id":"test-core","depends_on":["core"],"files":["test_core.py"]},
                {"id":"integrate-verify","depends_on":["core","cli","test-core"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let n = fan_verify_split(&mut plan, TargetLang::Python);
        assert_eq!(
            n, 2,
            "one verify task per file-owning non-test module (core, cli)"
        );
        // Each verify task depends on its module and NOTHING else — never on `test-core`, even though that
        // task writes core's tests. See a_verify_task_never_waits_on_a_test_subtask: that edge cascades a
        // failing test into integrate-verify and the end-to-end gate never runs.
        assert_eq!(fv_deps(&plan, "verify::core"), "core");
        assert_eq!(fv_deps(&plan, "verify::cli"), "cli");
        // No verify task issues ANY test command: the whole suite collects nothing this early and exits
        // CLEAN, which the model reads as a pass (MEASURED verify-6). Tests belong to `test-<module>`.
        for vid in ["verify::core", "verify::cli"] {
            let d = fv_task(&plan, vid).unwrap()["description"]
                .as_str()
                .unwrap()
                .to_string();
            assert!(d.contains("Run NO test command"), "{vid}");
            assert!(!d.contains("pytest"), "{vid} must get no pytest invocation");
        }
        for vid in ["verify::core", "verify::cli"] {
            assert!(
                fv_task(&plan, vid).unwrap()["files"]
                    .as_array()
                    .unwrap()
                    .is_empty(),
                "{vid} owns no files (read-only, fannable)"
            );
        }
        // No verify task for the test subtask.
        assert!(fv_task(&plan, "verify::test-core").is_none());
        // The thin join the split installs is the one the SINK ACTUALLY RECEIVES. The T2 canonicalizer in
        // parallel_plan re-writes integrate-verify's description ~200 lines later and used to hardcode the
        // FULL monolithic spec, so this thin text never reached a worker: every fan_verify run paid for N
        // extra verify tasks AND still ran the whole suite serially in the sink (36% of all node-busy time
        // across the corpus). T2 now selects thin_integrate_verify_spec when the split applied.
        assert_eq!(
            thin_integrate_verify_spec(TargetLang::Python),
            fv_task(&plan, "integrate-verify").unwrap()["description"]
                .as_str()
                .unwrap(),
            "the split's thin join must be exactly what T2 canonicalizes to"
        );
        // The join keeps its exact id, re-points module deps onto the verify tasks, and keeps the non-module
        // (test) dep. Order: mapped existing deps first, then any missing verify tasks appended (none here).
        assert_eq!(
            fv_deps(&plan, "integrate-verify"),
            "verify::core,verify::cli,test-core"
        );
        // The join is the thin whole-program oracle, not the monolithic suite-runner.
        let desc = fv_task(&plan, "integrate-verify").unwrap()["description"]
            .as_str()
            .unwrap();
        assert!(desc.contains("INTEGRATION JOIN"));
        assert!(desc.contains("SOLE integration gate"));
        assert!(
            !desc.contains("run the test suite"),
            "the whole-suite step moved to per-module verify"
        );
        // The module build tasks themselves are untouched.
        assert_eq!(fv_deps(&plan, "core"), "");
        assert_eq!(fv_deps(&plan, "cli"), "core");
    }

    /// A `verify::<M>` must NEVER depend on a test subtask — not even transitively, and not even to make a
    /// scoped test command safe to run.
    ///
    /// MEASURED (h1-treat-1): a version that added an edge onto whoever writes M's test file deadlocked the
    /// oracle. `test-wal` failed on a SyntaxError, `fail_descendants` cascaded Failed through `verify::wal`
    /// into `integrate-verify`, and the whole-program gate NEVER RAN. `strip_integrate_verify_test_deps`
    /// exists to keep a failing unit test from blocking the sink; routing the sink's dependency through a
    /// verify:: task re-introduces exactly that coupling.
    #[test]
    fn a_verify_task_never_waits_on_a_test_subtask() {
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"wal","depends_on":[],"files":["raftkv/wal.py"]},
                {"id":"test-wal","depends_on":["wal"],"files":["tests/test_wal.py"]},
                {"id":"integrate-verify","depends_on":["wal","test-wal"],"files":[]}
            ]}"#,
        )
        .unwrap();
        assert_eq!(fan_verify_split(&mut plan, TargetLang::Python), 1);
        // The ONLY edge is onto the module itself.
        assert_eq!(fv_deps(&plan, "verify::wal"), "wal");
        // And the verify spec issues NO test command, so there is nothing to be vacuous about: an empty or
        // not-yet-written suite can no longer exit CLEAN and read as a pass.
        let desc = fv_task(&plan, "verify::wal").unwrap()["description"]
            .as_str()
            .unwrap();
        assert!(desc.contains("Run NO test command"));
        assert!(!desc.contains("pytest"));
    }

    /// `id.contains("test")` classified any id with `test` ANYWHERE as a test subtask. A module called
    /// `latest-prices` therefore got NO `verify::` task and was ALSO left off the join's re-pointed dep
    /// list — verified by nothing, silently, while reading as a deliberate exclusion.
    #[test]
    fn a_module_whose_name_merely_contains_test_is_not_a_test_task() {
        // Real test ids stay tests (kebab and snake, any case).
        for id in [
            "tests",
            "test-core",
            "engine-tests",
            "tests-and-readme",
            "test_parser",
            "TESTS",
        ] {
            assert!(id_names_a_test(id), "{id} names a test");
        }
        // The false positives that cost a module its verify gate.
        for id in [
            "latest",
            "latest-prices",
            "contest",
            "attestation",
            "fastest-path",
            "testdata",
        ] {
            assert!(!id_names_a_test(id), "{id} is NOT a test task");
        }

        // End to end through the split: `latest-prices` now gets its verify task and the join gates on it.
        let mut plan = serde_json::json!({"subtasks":[
            {"id":"latest-prices","files":["latest.py"],"depends_on":[]},
            {"id":"integrate-verify","files":[],"depends_on":["latest-prices"]}
        ]});
        assert_eq!(fan_verify_split(&mut plan, TargetLang::Python), 1);
        assert!(fv_task(&plan, "verify::latest-prices").is_some());
        assert_eq!(fv_deps(&plan, "integrate-verify"), "verify::latest-prices");
    }

    #[test]
    fn fan_verify_split_is_idempotent_and_noops_without_sink() {
        // Idempotent: a second application does nothing (verify:: prefix already present).
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["a.py"]},
                {"id":"b","depends_on":[],"files":["b.py"]},
                {"id":"integrate-verify","depends_on":["a","b"],"files":[]}
            ]}"#,
        )
        .unwrap();
        assert_eq!(fan_verify_split(&mut plan, TargetLang::Python), 2);
        let after_first = plan.clone();
        assert_eq!(
            fan_verify_split(&mut plan, TargetLang::Python),
            0,
            "already fanned -> no-op"
        );
        assert_eq!(plan, after_first, "second application byte-identical");
        // No sink -> no-op, byte-identical.
        let mut no_sink: serde_json::Value =
            serde_json::from_str(r#"{"subtasks":[{"id":"a","depends_on":[],"files":["a.py"]}]}"#)
                .unwrap();
        let before = no_sink.clone();
        assert_eq!(fan_verify_split(&mut no_sink, TargetLang::Python), 0);
        assert_eq!(no_sink, before, "no sink -> plan left byte-identical");
    }

    #[test]
    fn split_fat_module_partitions_by_concern() {
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"core-miner","depends_on":["types"],"files":["internal/miner/masker.go","internal/miner/tree.go","internal/miner/miner.go","internal/miner/miner_test.go","internal/miner/diff.go"],"difficulty":"hard"},
                {"id":"types","depends_on":[],"files":["internal/miner/types.go"],"difficulty":"easy"},
                {"id":"integrate-verify","depends_on":["core-miner","types"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let n = split_fat_modules(&mut plan, TargetLang::Go, 4);
        assert_eq!(n, 1, "one fat module split");
        assert!(fv_task(&plan, "core-miner").is_none(), "fat parent removed");
        for cid in [
            "core-miner-masker",
            "core-miner-tree",
            "core-miner-miner",
            "core-miner-diff",
        ] {
            assert!(fv_task(&plan, cid).is_some(), "{cid} child created");
            assert_eq!(
                fv_deps(&plan, cid),
                "types",
                "{cid} carries the parent's external dep"
            );
        }
        // impl + its test land in the SAME child (both map to role 'miner').
        let miner_files: Vec<String> = fv_task(&plan, "core-miner-miner").unwrap()["files"]
            .as_array()
            .unwrap()
            .iter()
            .map(|f| f.as_str().unwrap().to_string())
            .collect();
        assert!(
            miner_files.iter().any(|f| f.ends_with("miner.go"))
                && miner_files.iter().any(|f| f.ends_with("miner_test.go")),
            "impl + its test stay together"
        );
        // Every dependent of the parent re-points onto ALL children; the non-parent dep survives.
        let iv = fv_deps(&plan, "integrate-verify");
        for cid in [
            "core-miner-masker",
            "core-miner-tree",
            "core-miner-miner",
            "core-miner-diff",
        ] {
            assert!(iv.contains(cid), "integrate-verify depends on {cid}");
        }
        assert!(iv.contains("types"), "non-parent dep preserved");
        assert!(
            iv.split(',').all(|d| d != "core-miner"),
            "the fat parent id is no longer a dependency"
        );
    }

    #[test]
    fn split_fat_splits_the_three_file_web_triplet() {
        // F873: the spec demands three separately-owned web files; 22 of 41 archived plans
        // shipped ONE `web` task owning all three and paid ~700s of judge-split tax. At the
        // new default threshold (3) the triplet must split at PLAN time into per-role
        // children with the parent's deps preserved.
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"api","depends_on":[],"files":["vendorsync/api.py"],"difficulty":"hard"},
                {"id":"web","depends_on":["api"],"difficulty":"hard",
                 "files":["vendorsync/web/index.html","vendorsync/web/styles.css","vendorsync/web/app.js"]},
                {"id":"integrate-verify","depends_on":["api","web"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let n = split_fat_modules(&mut plan, TargetLang::Python, 3);
        assert_eq!(
            n, 1,
            "the 3-file multi-role web task must split at threshold 3"
        );
        let ids: Vec<String> = plan["subtasks"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| s["id"].as_str().unwrap_or("").to_string())
            .collect();
        assert!(
            !ids.contains(&"web".to_string()),
            "the fat parent is replaced"
        );
        let children: Vec<&String> = ids.iter().filter(|i| i.starts_with("web-")).collect();
        assert!(
            children.len() >= 2,
            "per-role children must exist (html/css/js roles): {ids:?}"
        );
    }

    #[test]
    fn split_fat_noops_below_threshold_and_when_not_hard() {
        // Below the file threshold -> untouched, byte-identical.
        let mut small: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[{"id":"m","depends_on":[],"files":["a.go","b.go"],"difficulty":"hard"},{"id":"integrate-verify","depends_on":["m"],"files":[]}]}"#,
        )
        .unwrap();
        let before = small.clone();
        assert_eq!(split_fat_modules(&mut small, TargetLang::Go, 4), 0);
        assert_eq!(small, before, "below threshold -> byte-identical");
        // Not `hard` -> untouched even when it owns many files.
        let mut easy: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[{"id":"m","depends_on":[],"files":["a.go","b.go","c.go","d.go","e.go"],"difficulty":"medium"},{"id":"integrate-verify","depends_on":["m"],"files":[]}]}"#,
        )
        .unwrap();
        let before2 = easy.clone();
        assert_eq!(split_fat_modules(&mut easy, TargetLang::Go, 4), 0);
        assert_eq!(easy, before2, "not hard -> byte-identical");
    }

    // ---- QUEUED USER NOTES ------------------------------------------------------------------
    #[test]
    fn user_notes_are_read_in_order_and_never_block_or_vanish() {
        let dir = tempfile::TempDir::new().unwrap();
        let inbox = dir.path().join(".swarm").join("inbox");
        std::fs::create_dir_all(&inbox).unwrap();
        // Filenames are epoch-ms prefixed => sorting them is chronological order.
        std::fs::write(
            inbox.join("1700000002-b.json"),
            r#"{"text":"second: the DB is already seeded"}"#,
        )
        .unwrap();
        std::fs::write(
            inbox.join("1700000001-a.json"),
            r#"{"text":"first: prefer stdlib over new deps"}"#,
        )
        .unwrap();
        // Junk must not break the read — a torn/foreign file is skipped, never fatal.
        std::fs::write(inbox.join("1700000003-c.json"), "{not json").unwrap();
        std::fs::write(inbox.join("ignore.txt"), "not a note").unwrap();
        std::fs::write(inbox.join("1700000004-d.json"), r#"{"text":"   "}"#).unwrap();

        let out = read_user_notes(dir.path(), 0).block;
        let first = out.find("prefer stdlib").expect("first note present");
        let second = out.find("already seeded").expect("second note present");
        assert!(
            first < second,
            "notes must read in the order they were written"
        );
        assert!(out.contains("NOTES FROM THE USER"));
        // It must never be able to outrank the spec.
        assert!(out.contains("does NOT override the spec"));
        // The notes are still on disk — a crash must never lose one, so reading does not consume.
        assert!(inbox.join("1700000001-a.json").exists());
    }

    #[test]
    fn a_resumed_plan_parses_into_a_dag() {
        // The bug this pins: resume rebuilt the plan under "tasks" while Dag::from_planner_json
        // requires "subtasks", so EVERY resume exited with "missing field `subtasks`" after
        // paying the whole scout phase.
        let dir = tempfile::tempdir().unwrap();
        let sw = dir.path().join(".swarm");
        std::fs::create_dir_all(&sw).unwrap();
        let plan_loaded = serde_json::json!({
            "event": "plan_loaded",
            "tasks": [
                {"id": "core", "description": "build core", "files": ["app/core.py"],
                 "depends_on": [], "difficulty": "easy"},
                {"id": "api", "description": "build api", "files": ["app/api.py"],
                 "depends_on": ["core"], "difficulty": "hard"}
            ]
        });
        let log = format!(
            "{}\n{}\n",
            plan_loaded,
            serde_json::json!({"event": "task_completed", "task_id": "core", "status": "done"})
        );
        std::fs::write(sw.join("run-swarm-00-resumed.jsonl"), log).unwrap();
        let r = resume_state_from_dir(dir.path()).expect("resume state must be recovered");
        assert!(r.completed.contains("core"));
        Dag::from_planner_json(&r.plan_json)
            .expect("a resumed plan MUST parse into a Dag — this is the whole point of resume");
    }

    #[test]
    fn pillar_resume_round_trips_the_full_compiled_plan_and_spec_identity() {
        let frozen_spec = "Build the exact resumable pillar fixture.";
        let frozen_spec_digest = pillar_frozen_spec_digest(frozen_spec);
        let raw_plan_json = serde_json::json!({
            "subtasks": [{
                "id": "core",
                "description": "Implement the exact core contract and acceptance path",
                "difficulty": "hard",
                "model": "planner-model",
                "depends_on": [],
                "files": ["src/core.txt"],
                "canonical_requirement_coverage": {
                    "owns_requirement_ids": ["REQ-core"],
                    "applies_requirement_ids": [],
                    "verifies_requirement_ids": [],
                    "evidence_ids": []
                }
            }],
            "canonical_plan_authority": {
                "format": "canonical-plan-authority-v1",
                "requirement_ids": ["REQ-core"],
                "integration_required": false,
                "accepted_digest": "sha256:fixture",
                "engine_transforms": []
            }
        })
        .to_string();
        let log = serde_json::json!({
            "event": "plan_loaded",
            "tasks": [{"id": "display-only", "deps": [], "files": []}],
            "raw_plan_json": raw_plan_json,
            "frozen_spec_digest": frozen_spec_digest,
        })
        .to_string();

        let resume = resume_state_from_log(&log).expect("pillar plan was not recoverable");
        assert_eq!(resume.plan_json, raw_plan_json);
        assert_eq!(
            resume.frozen_spec_digest.as_deref(),
            Some(frozen_spec_digest.as_str())
        );
        let plan: serde_json::Value = serde_json::from_str(&resume.plan_json).unwrap();
        assert_eq!(plan["subtasks"][0]["id"], "core");
        assert_eq!(
            plan["canonical_plan_authority"]["integration_required"],
            false
        );
    }

    #[test]
