    #[tokio::test]
    async fn same_spec_pillar_resume_restores_exact_artifact_with_zero_build_dispatches() {
        let root = tempfile::tempdir().unwrap();
        let frozen_spec = "Build one durable artifact.";
        let frozen_spec_digest = pillar_frozen_spec_digest(frozen_spec);
        let raw_plan_json = serde_json::json!({
            "subtasks": [{
                "id": "artifact",
                "description": "Write the exact durable artifact",
                "difficulty": "hard",
                "model": "resume-model",
                "depends_on": [],
                "files": ["src/artifact.txt"]
            }],
            "canonical_plan_authority": {
                "integration_required": false
            }
        })
        .to_string();
        let log = serde_json::json!({
            "event": "plan_loaded",
            "tasks": [{
                "id": "artifact",
                "description": "display summary",
                "deps": [],
                "files": ["src/artifact.txt"]
            }],
            "raw_plan_json": raw_plan_json,
            "frozen_spec_digest": frozen_spec_digest,
        })
        .to_string();
        let previous = resume_state_from_log(&log).unwrap();
        let (selected, rejection) =
            select_resume_for_run(Some(previous), true, &frozen_spec_digest, 0);
        assert!(rejection.is_none());
        let selected = selected.expect("same-spec zero-call resume was rejected");
        let dag = Dag::from_planner_json(&selected.plan_json).unwrap();
        let task_spec = dag.tasks["artifact"].spec.clone();

        let artifact_path = root.path().join("src/artifact.txt");
        std::fs::create_dir_all(artifact_path.parent().unwrap()).unwrap();
        std::fs::write(&artifact_path, b"verified artifact bytes").unwrap();
        let store = SchedulerCheckpointStore::open_for_generation(
            root.path(),
            &frozen_spec_digest,
            &selected.plan_json,
        )
        .unwrap();
        store
            .persist_done(&task_spec, "verified artifact output", 2)
            .unwrap();
        drop(store);
        std::fs::remove_file(&artifact_path).unwrap();

        let dispatch = Arc::new(BuildDispatchProbe {
            starts: std::sync::atomic::AtomicUsize::new(0),
            descriptions: Mutex::new(Vec::new()),
        });
        let report = Scheduler::new(
            vec![DeviceCfg {
                id: "resume-device".to_string(),
                model_id: "resume-model".to_string(),
                weight: 1,
                enabled: true,
                speed_weight: 1,
                supervision: false,
            }],
            1,
        )
        .with_checkpoint_store(Arc::new(
            SchedulerCheckpointStore::open_for_generation(
                root.path(),
                &frozen_spec_digest,
                &selected.plan_json,
            )
            .unwrap(),
        ))
        .run(dag, dispatch.clone(), frozen_spec.to_string())
        .await
        .unwrap();

        assert_eq!(dispatch.starts.load(std::sync::atomic::Ordering::SeqCst), 0);
        assert_eq!(report.results["artifact"], "verified artifact output");
        assert_eq!(report.tasks[0].attempts, 2);
        assert_eq!(
            std::fs::read(&artifact_path).unwrap(),
            b"verified artifact bytes"
        );
    }

    #[test]
    fn a_seconds_prefixed_note_is_reported_skipped_not_silently_dropped() {
        // The exact operator error: a note named with SECONDS instead of milliseconds parses as
        // 1970, scopes out, and used to vanish without a word — no delivery, no warning, nothing
        // in the run log to distinguish it from a note that was never written.
        let dir = tempfile::tempdir().unwrap();
        let inbox = dir.path().join(".swarm").join("inbox");
        std::fs::create_dir_all(&inbox).unwrap();
        std::fs::write(
            inbox.join("1787347648-ledger-server-spec.json"), // seconds, not ms
            r#"{"text":"use the brief and contracts as authoritative"}"#,
        )
        .unwrap();
        let since_ms = 1_787_300_000_000i64; // this run started (ms)
        let d = read_user_notes(dir.path(), since_ms);
        assert!(
            d.ids.is_empty(),
            "a stale-scoped note must not be delivered"
        );
        assert_eq!(
            d.skipped_stale,
            vec!["1787347648-ledger-server-spec.json".to_string()],
            "and it must be REPORTED as skipped"
        );
        // A correctly-stamped note in the same inbox still lands.
        std::fs::write(
            inbox.join(format!("{}-good.json", since_ms + 1000)),
            r#"{"text":"bind before syncing"}"#,
        )
        .unwrap();
        let d2 = read_user_notes(dir.path(), since_ms);
        assert_eq!(d2.ids.len(), 1);
        assert_eq!(d2.skipped_stale.len(), 1);
    }

    #[test]
    fn no_inbox_means_no_notes_and_a_byte_identical_prompt() {
        let dir = tempfile::TempDir::new().unwrap();
        assert_eq!(read_user_notes(dir.path(), 0).block, "");
        // An empty inbox is the same as none.
        std::fs::create_dir_all(dir.path().join(".swarm").join("inbox")).unwrap();
        assert_eq!(read_user_notes(dir.path(), 0).block, "");
    }

    // ---- LEARN & REFLECT --------------------------------------------------------------------
    /// The trap this exists for: TargetLang collapses React, Angular and a node CLI all into `TypeScript`,
    /// and Swift into `Other` beside Ruby. Keying learned knowledge on that would inject an Angular lesson
    /// into a React build — poisoning the very thing the learning is meant to speed up.
    #[test]
    fn detect_stack_key_never_collapses_distinct_stacks() {
        let react = detect_stack_key(
            "Build Minesweeper as a React + TypeScript SPA using Vite",
            &[],
        );
        let angular = detect_stack_key("Build a dashboard with Angular", &["angular.json".into()]);
        assert_eq!(react.as_deref(), Some("react-vite-ts"));
        assert_eq!(angular.as_deref(), Some("angular"));
        assert_ne!(
            react, angular,
            "react and angular must NEVER share a bucket"
        );

        // THE WHOLE REASON THIS FUNCTION EXISTS: to TargetLang, React and Angular are the SAME thing.
        // (Second-order trap found while writing this test: detect_language DEFAULTS TO PYTHON without an
        // explicit cue, so "Build a React app with Vite" alone is Python to it. Given a real TypeScript spec
        // + manifest, both frameworks still collapse into one bucket.)
        let react_files = vec!["src/App.tsx".to_string(), "vite.config.ts".to_string()];
        let ng_files = vec![
            "src/app.component.ts".to_string(),
            "angular.json".to_string(),
        ];
        assert_eq!(
            detect_language("Build a React SPA in TypeScript", &react_files),
            TargetLang::TypeScript
        );
        assert_eq!(
            detect_language("Build an Angular SPA in TypeScript", &ng_files),
            TargetLang::TypeScript
        );
        // Identical to TargetLang; correctly distinct to detect_stack_key.
        assert_ne!(
            detect_stack_key("Build a React SPA in TypeScript with Vite", &react_files),
            detect_stack_key("Build an Angular SPA in TypeScript", &ng_files)
        );

        assert_eq!(
            detect_stack_key(
                "a macOS notes app in Swift 6 with SwiftUI",
                &["Package.swift".into()]
            )
            .as_deref(),
            Some("swift-spm")
        );
        assert_eq!(
            detect_stack_key("Build a FastAPI + SQLite web app", &[]).as_deref(),
            Some("fastapi")
        );
    }

    /// A bare language is NOT a stack: "python" spans a CLI, a web app and a library, whose proven layouts
    /// have nothing in common. Refusing to key is the safe answer — no key means nothing is learned and
    /// nothing is injected, which is byte-identical to today.
    #[test]
    fn detect_stack_key_refuses_when_it_is_not_confident() {
        assert_eq!(detect_stack_key("Build a python tool", &[]), None);
        assert_eq!(detect_stack_key("Build something nice", &[]), None);
        assert_eq!(detect_stack_key("", &[]), None);
        // React WITHOUT vite is not the react-vite-ts stack — do not guess it in.
        assert_eq!(detect_stack_key("a react native mobile app", &[]), None);
    }

    /// Moving personas into the SHARED skills root is what made this reachable: persona_dir is a pure
    /// function of the stack key, and write_persona truncates. A user who hand-writes a skill named
    /// `stack-fastapi` would have had it silently eaten by the first successful fastapi build. Authorship,
    /// not the path, decides — and the check runs against real bytes on a real disk, because the bug is in
    /// the filesystem call and a mocked one would prove nothing.
    #[test]
    fn a_persona_write_never_truncates_a_skill_goose_did_not_author() {
        let dir = tempfile::TempDir::new().unwrap();
        let path = dir.path().join("SKILL.md");
        let hand_written =
            "---\nname: stack-fastapi\ndescription: mine\n---\n\nMy own hard-won notes.\n";
        std::fs::write(&path, hand_written).unwrap();

        // the guard's exact predicate, over the real file
        let existing = std::fs::read_to_string(&path).unwrap();
        assert!(
            !existing.contains(PERSONA_PROVENANCE),
            "a hand-written skill must not look goose-authored"
        );
        assert_eq!(
            std::fs::read_to_string(&path).unwrap(),
            hand_written,
            "the user's file must be byte-identical after the check"
        );

        // ...whereas goose's own render IS recognised, so it can still update itself
        let rendered = render_persona_skill("fastapi", &PersonaSnapshot::default(), "x", 1, "");
        assert!(rendered.contains(PERSONA_PROVENANCE));
    }

    /// THE SAFETY CLAIM, PINNED. The persona is only defensible because the user can SEE the lesson a weak
    /// model wrote about itself and throw it out. That rests entirely on the write landing on a directory
    /// `goose::skills` actually walks — which the first version did not (it wrote to `data_dir/swarm/personas`,
    /// a path no skill root covers, so nothing goose learned was ever visible). Assert against the real
    /// discovery list, so moving either side of this contract fails here instead of silently un-mitigating it.
    #[test]
    fn learned_persona_lands_where_the_skills_ui_looks() {
        let dir = persona_dir("react-vite-ts");
        let roots: Vec<_> = goose::skills::all_skill_dirs(None)
            .into_iter()
            .map(|(d, _)| d)
            .collect();
        assert!(
            roots.iter().any(|r| dir.starts_with(r)),
            "persona dir {dir:?} is under NO skill discovery root {roots:?} — the user cannot see, edit or \
             delete what goose learned, which is the whole mitigation for a wrong lesson"
        );
        assert!(dir.ends_with("stack-react-vite-ts"));

        // The counter must NOT sit in the skill folder: every non-SKILL.md file there is advertised to the
        // model as a loadable supporting file, so a `runs` file becomes a tool call returning one integer.
        let counter = persona_runs_file("react-vite-ts");
        assert!(
            !counter.starts_with(&dir),
            "the run counter {counter:?} is inside the skill folder and would be advertised as loadable"
        );
    }

    /// The render must emit the exact sentence the write guard looks for. These are two constants in two
    /// functions and nothing but this test couples them: if the render stops emitting PERSONA_PROVENANCE,
    /// every future write silently takes the RefusedForeign branch and goose quietly stops learning — a
    /// dead feature behind a green build, which is the failure mode this codebase keeps producing.
    #[test]
    fn a_rendered_persona_is_recognised_as_goose_authored() {
        let snap = PersonaSnapshot::default();
        let rendered = render_persona_skill("fastapi", &snap, "a lesson", 1, "");
        assert!(
            rendered.contains(PERSONA_PROVENANCE),
            "the write guard proves authorship by finding PERSONA_PROVENANCE in the file it is about to \
             truncate; this render does not contain it, so goose would refuse to overwrite its own skill"
        );
        // and the warning must sit ABOVE the lesson, not only in the footer: the user fixes a wrong sentence
        // where the wrong sentence IS, and everything above the marker is regenerated.
        let warn = rendered
            .find("REGENERATED")
            .expect("no in-place-edit warning");
        let lesson = rendered.find("## What worked").expect("no lesson section");
        assert!(
            warn < lesson,
            "the warning that this region is regenerated must appear BEFORE the region the user will edit"
        );
    }

    /// The file tells the user their corrections are permanent. A rewrite is `fs::write` — truncating — so
    /// that promise is only true if the user's section round-trips through the render DETERMINISTICALLY.
    /// Handing it to a weak model as "prior" and hoping it merges is exactly the trust this cannot assume.
    #[test]
    fn user_notes_survive_a_rewrite_verbatim() {
        let snap = PersonaSnapshot {
            stack_key: Some("fastapi".into()),
            files: vec!["app/main.py".into()],
            shape: vec![("api".into(), vec!["app/main.py".into()])],
            judge_lessons: vec!["pin the pydantic version".into()],
        };
        let correction =
            "goose keeps getting this wrong: we use SQLModel here, NOT raw SQLAlchemy.";
        let first = render_persona_skill("fastapi", &snap, "use uvicorn", 1, "");
        assert!(first.contains(PERSONA_USER_MARKER));
        assert_eq!(
            persona_user_notes(&first),
            "",
            "a fresh skill has no user notes"
        );
        // The banner NAMES the marker inline, above the real heading. Cutting at the first textual hit
        // would hand back the whole document as "the user's notes" — assert we cut at the heading itself.
        assert!(
            first.matches(PERSONA_USER_MARKER).count() > 1,
            "this test only bites while the banner names the marker inline"
        );
        assert!(
            !persona_user_notes(&first).contains("use uvicorn"),
            "the split landed on the banner, not the heading — goose's own lesson is being preserved as \
             though the user wrote it, and it will compound on every rewrite"
        );

        // the user opens the file and appends their correction under the marker
        let edited = format!("{first}\n{correction}\n");
        assert_eq!(persona_user_notes(&edited), correction);

        // ...and a later successful build rewrites everything ABOVE the marker
        let rewritten =
            render_persona_skill("fastapi", &snap, "a totally different lesson", 2, &edited);
        assert!(
            rewritten.contains(correction),
            "the rewrite dropped the user's correction — 'write here and it sticks' is then a lie:\n{rewritten}"
        );
        assert!(rewritten.contains("a totally different lesson"));
        assert!(
            !rewritten.contains("use uvicorn"),
            "the model's old lesson should be replaced, not kept"
        );
        // and it must be idempotent: rewriting again does not duplicate or nest the notes
        let again = render_persona_skill("fastapi", &snap, "third lesson", 3, &rewritten);
        assert_eq!(
            again.matches(correction).count(),
            1,
            "the notes were duplicated across rewrites"
        );
        // Exactly one real HEADING. The banner names the marker inline too, so a raw substring count is the
        // wrong invariant — what must never happen is a SECOND notes section, which would strand the first.
        let headings = |s: &str| {
            s.matches(&format!("\n{PERSONA_USER_MARKER}")).count()
                + usize::from(s.starts_with(PERSONA_USER_MARKER))
        };
        assert_eq!(headings(&again), 1, "a rewrite grew a second notes section");
        assert_eq!(headings(&first), 1);
    }

    /// Only a CORRECTIVE verdict carries a lesson; "ok"/"observed" means the judge had nothing to say. Uses
    /// the real event shape emitted by a run.
    #[test]
    fn judge_lessons_keeps_only_corrective_hints() {
        let dir = tempfile::TempDir::new().unwrap();
        let log = dir.path().join("run.jsonl");
        std::fs::write(
            &log,
            "{\"event\":\"judge_verdict\",\"verdict\":\"ok\",\"hint\":\"\"}\n\
             {\"event\":\"judge_verdict\",\"verdict\":\"observed\",\"hint\":\"looks fine\"}\n\
             {\"event\":\"judge_verdict\",\"verdict\":\"broken_code\",\"hint\":\"Add @MainActor to the NoteStore class declaration\"}\n\
             {\"event\":\"judge_verdict\",\"verdict\":\"broken_code\",\"hint\":\"Add @MainActor to the NoteStore class declaration\"}\n\
             {\"event\":\"task_completed\",\"hint\":\"not a judge event\"}\n\
             not json at all\n",
        )
        .unwrap();
        let out = judge_lessons_from_log(&log);
        assert_eq!(
            out.len(),
            1,
            "dedup + drop ok/observed/non-judge, got {out:?}"
        );
        assert!(out[0].contains("@MainActor"));
    }

    #[test]
    fn judge_lessons_from_a_missing_log_is_empty_not_a_panic() {
        assert!(judge_lessons_from_log(std::path::Path::new("/nonexistent/run.jsonl")).is_empty());
    }

    // ---- TURN-CONTEXT STRIP -----------------------------------------------------------------
    /// The desktop prepends a per-turn `<turn-context>` block to the goal. MEASURED (loop-06): it is 171
    /// chars, and the retarget's research question uses `opts.prompt.chars().take(200)` — so the "task" the
    /// researcher was handed was 171 chars of XML and 28 chars of real spec. This fixture is the REAL wrapper
    /// copied from that run's run_started event, not a hand-made one.
    #[test]
    fn strip_turn_context_removes_the_real_desktop_wrapper() {
        let real = "<turn-context>\n<current-time>2026-07-16 14:52:00</current-time>\n\
                    <working-directory>/Users/mihaiperdum/goose-builds/loop-06-py-splitwise</working-directory>\n\
                    </turn-context>\nBuild \"Settle\" — a shared-expense splitter as a Python web app.";
        let out = strip_turn_context(real);
        assert!(
            out.starts_with("Build \"Settle\""),
            "the spec must lead, got: {:.60}",
            out
        );
        assert!(!out.contains("turn-context"));
        assert!(!out.contains("current-time"));
        // The first 200 chars a research question sees are now ALL spec.
        assert!(out
            .chars()
            .take(200)
            .collect::<String>()
            .contains("shared-expense splitter"));
    }

    #[test]
    fn strip_turn_context_leaves_everything_else_byte_identical() {
        // No wrapper -> untouched.
        let plain = "Build a Flask kanban app.";
        assert_eq!(strip_turn_context(plain), plain);
        // MENTIONS the words but is not the canonical wrapper -> untouched (never strip blindly).
        let mentions = "Write a parser for <turn-context> tags and a <current-time> helper.";
        assert_eq!(strip_turn_context(mentions), mentions);
        // Opens correctly but never closes -> untouched rather than eating the whole goal.
        let unclosed = "<turn-context>\n<current-time>2026</current-time>\nBuild an app.";
        assert_eq!(strip_turn_context(unclosed), unclosed);
        assert_eq!(strip_turn_context(""), "");
    }

    // ---- USER NOTES: run scoping + budget ----------------------------------------------------
    /// THE CROSS-RUN LEAK. Nothing ever cleared `.swarm/inbox` (run_swarm clears only `.swarm/prereview`),
    /// so before the cutoff every note ever written to a project dir was injected into every worker of every
    /// FUTURE run there — under a header claiming it was "added while this build was running". Yesterday's
    /// "the DB is already seeded" silently steered today's fresh build.
    #[test]
    fn a_note_from_a_previous_run_is_not_delivered_to_this_one() {
        let dir = tempfile::TempDir::new().unwrap();
        let inbox = dir.path().join(".swarm").join("inbox");
        std::fs::create_dir_all(&inbox).unwrap();
        std::fs::write(
            inbox.join("1700000000000.json"),
            r#"{"text":"STALE: the DB is already seeded"}"#,
        )
        .unwrap();
        std::fs::write(
            inbox.join("1800000000000.json"),
            r#"{"text":"FRESH: prefer stdlib over new deps"}"#,
        )
        .unwrap();

        let d = read_user_notes(dir.path(), 1_750_000_000_000);
        assert!(
            d.block.contains("FRESH"),
            "this run's note must be delivered"
        );
        assert!(
            !d.block.contains("STALE"),
            "a previous run's note must NEVER ride this run: {}",
            d.block
        );
        assert_eq!(d.ids, vec!["1800000000000.json".to_string()]);

        // The note is SCOPED OUT, never destroyed — a crash must not lose one, and an older cutoff sees it.
        assert!(read_user_notes(dir.path(), 0).block.contains("STALE"));
        assert!(inbox.join("1700000000000.json").is_file());
    }

    /// A hand-placed file with no epoch prefix is the deliberate escape hatch for a standing instruction:
    /// it has no run to belong to, so it is always in scope.
    #[test]
    fn a_standing_note_without_a_timestamp_is_always_delivered() {
        let dir = tempfile::TempDir::new().unwrap();
        let inbox = dir.path().join(".swarm").join("inbox");
        std::fs::create_dir_all(&inbox).unwrap();
        std::fs::write(
            inbox.join("standing-orders.json"),
            r#"{"text":"always write tests first"}"#,
        )
        .unwrap();
        let d = read_user_notes(dir.path(), i64::MAX);
        assert!(d.block.contains("always write tests first"));
    }

    /// The block rides EVERY dispatch for the rest of the run, so an unbounded inbox taxes every prompt on a
    /// fleet whose own worker prompt warns that large context degrades quality. Keep the NEWEST, report the
    /// rest — a silently-trimmed block would make the user think a note landed when it did not.
    #[test]
    fn the_notes_block_is_bounded_and_reports_what_it_dropped() {
        let dir = tempfile::TempDir::new().unwrap();
        let inbox = dir.path().join(".swarm").join("inbox");
        std::fs::create_dir_all(&inbox).unwrap();
        for i in 0..40 {
            std::fs::write(
                inbox.join(format!("18000000000{i:02}.json")),
                serde_json::json!({ "text": format!("note {i} {}", "x".repeat(100)) }).to_string(),
            )
            .unwrap();
        }
        let d = read_user_notes(dir.path(), 0);
        assert!(
            d.block.chars().count() < 2500,
            "block must stay bounded, got {}",
            d.block.chars().count()
        );
        assert!(d.dropped > 0, "dropped notes must be COUNTED, never silent");
        assert_eq!(
            d.ids.len() + d.dropped,
            40,
            "every in-scope note is either delivered or reported dropped — none may vanish"
        );
        // The NEWEST guidance is what survives.
        assert!(d.block.contains("note 39"));
    }

    #[test]
    fn note_epoch_ms_reads_the_desktops_filename_shape() {
        assert_eq!(note_epoch_ms("1785213270712.json"), Some(1_785_213_270_712));
        assert_eq!(note_epoch_ms("1700000002-b.json"), Some(1_700_000_002));
        assert_eq!(note_epoch_ms("standing-orders.json"), None);
        assert_eq!(note_epoch_ms(".json"), None);
    }

    // ---- APP SCOPE: a static scan may only ever see the app THIS run built ------------------
    /// The manifest branch, the planned-directory sweep, and everything each must EXCLUDE. Reproduces the
    /// $HOME shape in miniature: unrelated trees beside the app, which the old os.walk(root) happily scanned
    /// (measured 10,916 .py under $HOME vs 8 in a build dir).
    #[test]
    fn app_scope_takes_the_manifest_and_planned_dirs_but_never_the_root_at_large() {
        let dir = std::env::temp_dir().join(format!("goose_scope_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("pkg")).unwrap();
        std::fs::create_dir_all(dir.join("Documents/other")).unwrap();
        std::fs::write(dir.join("pkg/a.py"), "x = 1\n").unwrap();
        // An UNPLANNED helper inside a planned dir IS the app's — that is what keeps the import graph closed.
        std::fs::write(dir.join("pkg/helper_unplanned.py"), "y = 2\n").unwrap();
        std::fs::write(dir.join("stray.py"), "z = 3\n").unwrap();
        std::fs::write(dir.join("Documents/other/x.py"), "w = 4\n").unwrap();

        // `main.py` is planned but NOT on disk (the pre-EXECUTE snapshot's greenfield case).
        let planned: Vec<String> = ["pkg/a.py", "main.py"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let scope = app_scope_py(&dir, &planned);
        let _ = std::fs::remove_dir_all(&dir);

        assert_eq!(
            scope.files,
            vec![
                "pkg/a.py".to_string(),
                "pkg/helper_unplanned.py".to_string()
            ],
            "the planned file + its planned dir, and NOTHING from the root or an unrelated tree"
        );
        assert!(scope.dropped.is_empty());
    }

    /// owned_files is MODEL-authored. One `..` or absolute entry would re-open the whole tree this closes.
    #[test]
    fn app_scope_refuses_an_escaping_manifest_entry() {
        let planned: Vec<String> = [
            "../../../etc/hosts.py",
            "/tmp/evil.py",
            "./pkg/a.py",
            "..\\..\\win.py",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        for d in scope_dirs(&planned) {
            assert!(
                d != ".." && !d.is_empty() && !d.starts_with('/'),
                "escaping dir: {d}"
            );
        }
        // The one legitimate entry is the only dir that survives.
        assert_eq!(scope_dirs(&planned), vec!["pkg".to_string()]);
    }

    /// A cap must produce a LABELLED PARTIAL, never a quiet short list — a silently-truncated scan reads
    /// as a clean tree, which is the false-green class this engine exists to prevent.
    #[test]
    fn app_scope_surfaces_dropped_files_instead_of_capping_silently() {
        let dir = std::env::temp_dir().join(format!("goose_scope_cap_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("pkg")).unwrap();
        let planned: Vec<String> = (0..5)
            .map(|i| {
                let rel = format!("pkg/m{i}.py");
                std::fs::write(dir.join(&rel), "x = 1\n").unwrap();
                rel
            })
            .collect();
        let scope = app_scope_py_capped(&dir, &planned, 2);
        let _ = std::fs::remove_dir_all(&dir);
        assert_eq!(scope.files.len(), 2);
        assert_eq!(scope.dropped.len(), 3);
        assert_eq!(
            scope.files.len() + scope.dropped.len(),
            5,
            "nothing may VANISH — every file is either scanned or reported dropped"
        );
    }

    /// The teeth: `unwired_demotes_verified` defaults TRUE and can flip a run's `verified` to false off
    /// demote_survivors. A scan that did not see every file cannot prove a module is imported by nothing.
    #[test]
    fn a_partial_scan_can_never_demote() {
        let before = std::collections::HashSet::new();
        let complete = AstReviewResult {
            ran: true,
            modules: 3,
            findings: vec![],
            demote_eligible: vec!["kanban.db".to_string()],
            partial: false,
        };
        assert_eq!(
            new_demote_survivors(&complete, &before),
            vec!["kanban.db".to_string()],
            "a COMPLETE scan may demote"
        );
        let partial = AstReviewResult {
            partial: true,
            ..complete.clone()
        };
        assert!(
            new_demote_survivors(&partial, &before).is_empty(),
            "a PARTIAL scan must never retract a green verdict"
        );
        let never_ran = AstReviewResult {
            ran: false,
            ..complete.clone()
        };
        assert!(new_demote_survivors(&never_ran, &before).is_empty());
    }

    // ---- APP ROOT GUARD ---------------------------------------------------------------------
    /// The desktop passes the session working directory, which with no project chosen is $HOME. A run
    /// treats its root as the app: it DELETES source files that appear under it (contracts cleanup),
    /// COPIES it whole (entry_help), and WALKS it (AST + drift scans). MEASURED at $HOME: 10,916 .py
    /// scanned vs 8 in a build dir, a 7-minute stall before any dispatch, and ~638 GB of attempted copy.
    #[test]
    fn home_and_its_ancestors_are_never_a_valid_app_root() {
        let home = Path::new("/Users/mihaiperdum");
        // The exact desktop default, and every ancestor of it.
        for bad in ["/Users/mihaiperdum", "/Users", "/"] {
            assert!(
                is_unsafe_app_root(Path::new(bad), home),
                "{bad} must never be treated as the app tree"
            );
        }
        // A real project dir — including the build dir we redirect INTO — stays untouched.
        for ok in [
            "/Users/mihaiperdum/goose-builds/swarm-20260727-190000000",
            "/Users/mihaiperdum/Projects/goose",
            "/tmp/scratch",
            "/Users/someone-else",
        ] {
            assert!(
                !is_unsafe_app_root(Path::new(ok), home),
                "{ok} is a legitimate project root and must be left alone"
            );
        }
    }

    /// The redirect target must itself be a SAFE root, or resolve_app_root would recurse into the same bug.
    #[test]
    fn the_redirect_target_is_itself_a_safe_root() {
        let home = Path::new("/Users/mihaiperdum");
        let target = home.join("goose-builds").join("swarm-20260727-190000000");
        assert!(!is_unsafe_app_root(&target, home));
    }

    // ---- ORPHAN / STUB FILE DETECTION -------------------------------------------------------
    #[test]
    fn orphan_source_files_flags_only_the_unplanned() {
        // loop-04's real case: dummy.swift shipped, in no task's owned_files.
        let on_disk = vec![
            "Sources/NotesLibrary/Note.swift".to_string(),
            "Sources/NotesLibrary/NoteStore.swift".to_string(),
            "Sources/NotesLibrary/dummy.swift".to_string(),
        ];
        let planned = vec![
            "Sources/NotesLibrary/Note.swift".to_string(),
            "Sources/NotesLibrary/NoteStore.swift".to_string(),
        ];
        assert_eq!(
            orphan_source_files(&on_disk, &planned),
            vec!["Sources/NotesLibrary/dummy.swift".to_string()]
        );
        // Separator + ./ normalization: a planned "./a.py" matches an on-disk "a.py".
        assert!(orphan_source_files(&["a.py".into()], &["./a.py".into()]).is_empty());
        // Nothing unplanned -> no orphans.
        assert!(orphan_source_files(&planned, &planned).is_empty());
    }

    #[test]
    fn is_stub_content_catches_placeholders_not_real_code() {
        assert!(is_stub_content("// NotesLibrary stub\nimport Foundation")); // the real dummy.swift
        assert!(is_stub_content("# placeholder"));
        assert!(is_stub_content("// TODO: implement\n"));
        assert!(is_stub_content("import Foundation")); // one meaningful line = trivial
        assert!(is_stub_content("")); // empty
                                      // Real code is not a stub.
        assert!(!is_stub_content(
            "func add(a: Int, b: Int) -> Int {\n    return a + b\n}\nlet x = add(1, 2)"
        ));
    }

    /// P1 substrate: `classify_research_attempt` widens `grounded:bool` into the four cases the ASK-AWAY
    /// interim routing needs (CalledEmpty → ask the user; Errored/NeverCalled → retry the fetch). The
    /// CalledEmpty-vs-Errored boundary is the load-bearing distinction — verify it explicitly.
    #[test]
    fn classify_research_attempt_separates_the_four_cases() {
        let mk = |name: &str, is_mcp: bool, ok: Option<bool>| ToolCallRecord {
            name: name.to_string(),
            is_mcp,
            ok,
            fetched_external: false,
        };
        // NeverCalled: no tool call at all — pure model reasoning.
        assert_eq!(classify_research_attempt(&[]), ResearchAttempt::NeverCalled);
        // Grounded: at least one successful MCP lookup, and it wins even alongside a failed one.
        assert_eq!(
            classify_research_attempt(&[mk("web-search__search", true, Some(true))]),
            ResearchAttempt::Grounded
        );
        assert_eq!(
            classify_research_attempt(&[
                mk("web-search__search", true, Some(false)),
                mk("context7__get-library-docs", true, Some(true)),
            ]),
            ResearchAttempt::Grounded
        );
        // Errored: a lookup was attempted and failed or was cut off (Some(false) / None), none succeeded.
        assert_eq!(
            classify_research_attempt(&[mk("web-search__search", true, Some(false))]),
            ResearchAttempt::Errored
        );
        assert_eq!(
            classify_research_attempt(&[mk("context7__resolve-library-id", true, None)]),
            ResearchAttempt::Errored
        );
        // CalledEmpty: tools ran and none errored, but nothing grounded — only non-MCP shell calls.
        assert_eq!(
            classify_research_attempt(&[mk("developer__shell", false, Some(true))]),
            ResearchAttempt::CalledEmpty
        );
    }

    // ---- PROVEN-CRASH DEMOTE ----------------------------------------------------------------
    // These replay the real archived runs in evals/swarm-gym/apps. The corpus contains exactly one
    // false-green and exactly one correctly-repaired app, and the rule must separate them.

    #[test]
    fn malformed_tool_name_recovers_the_quoted_name_without_panicking() {
        assert_eq!(
            malformed_tool_name(
                "The provided function name 'developer__shel' had invalid characters"
            ),
            "developer__shel (malformed)"
        );
        // No quoted name -> a marker, never an empty lane in the panel.
        assert_eq!(
            malformed_tool_name("arguments were not valid json"),
            "(malformed call)"
        );
        assert_eq!(malformed_tool_name("''"), "(malformed call)");
        // Multi-byte chars on the quote boundary must not panic (the message carries raw model output).
        assert_eq!(
            malformed_tool_name("bad name 'café—x' here"),
            "café—x (malformed)"
        );
        assert_eq!(malformed_tool_name("日本語のエラー"), "(malformed call)");
    }

    /// The demote path must read `demote_eligible`, not `findings` — the detector FLAGS standalone scripts
    /// (measured: this repo's own calls_report.py / conf_trail.py, both perfectly alive), so gating on the
    /// finding list would false-fail a correct app. Older stdout without the key must degrade to demoting
    /// nothing rather than to demoting everything.
    #[test]
    fn ast_review_demote_eligible_is_separate_from_findings() {
        let r = parse_ast_review(
            r#"{"modules":6,"findings":["module 'kanban.db' is imported by no non-test module — built-but-unwired (dead or unreachable from the app)"],"demote_eligible":["kanban.db"]}"#,
        );
        assert!(r.ran);
        assert_eq!(r.demote_eligible, vec!["kanban.db".to_string()]);

        // A flagged-but-alive script: a finding, but NOT demote-eligible.
        let scripts = parse_ast_review(
            r#"{"modules":2,"findings":["module 'calls_report' is imported by no non-test module — built-but-unwired (dead or unreachable from the app)"],"demote_eligible":[]}"#,
        );
        assert_eq!(
            scripts.findings.len(),
            1,
            "it must still be FLAGGED (advisory is free)"
        );
        assert!(
            scripts.demote_eligible.is_empty(),
            "a standalone script must never demote"
        );

        // Absent key (an older/other producer) -> demote nothing. Fail safe, never fail closed.
        let legacy = parse_ast_review(r#"{"modules":3,"findings":["x"]}"#);
        assert!(legacy.ran);
        assert!(legacy.demote_eligible.is_empty());

        // Unparseable -> ran=false, nothing to act on (a reviewer hiccup must not manufacture a demotion).
        let broken = parse_ast_review("not json");
        assert!(!broken.ran);
        assert!(broken.demote_eligible.is_empty());
    }

    // ---- CONTEXTUAL PITFALL RETRIEVAL (the author finally gets the fact library) -------------------

    /// The parser must find EVERY item and lose NO text — it feeds a prompt, so a silently dropped fact is
    /// a fact the author never learns. Also pins the trigger table to the library: adding a pitfall without
    /// a trigger row makes it unreachable to the author, and that must fail loudly here.
    #[test]
    fn pitfall_items_match_triggers() {
        let items = pitfall_items();
        assert_eq!(
            items.len(),
            PITFALL_TRIGGERS.len(),
            "every DOMAIN_PITFALLS item needs a trigger row (or the author can never receive it)"
        );
        for (i, item) in items.iter().enumerate() {
            assert!(
                item.starts_with(&format!("{}. ", i + 1)),
                "item {} out of order: {:.40}",
                i + 1,
                item
            );
            assert!(
                !PITFALL_TRIGGERS[i].is_empty(),
                "item {} has no triggers",
                i + 1
            );
        }
        // No text may be lost between the const and the items the author would see.
        let rejoined: String = items.join("\n");
        let norm = |s: &str| s.split_whitespace().collect::<Vec<_>>().join(" ");
        assert_eq!(
            norm(&rejoined),
            norm(DOMAIN_PITFALLS),
            "the split lost or mangled library text"
        );
    }

    #[test]
    fn relevant_pitfalls_retrieves_only_what_the_task_is_about() {
        // A cron task gets the cron fact (the measured off-by-one class) and NOT money/unicode noise.
        let cron =
            relevant_pitfalls("Build a cron scheduler that parses a crontab day-of-week field")
                .expect("cron task must retrieve the cron pitfall");
        assert!(cron.contains("CRON day-of-week is 0=Sunday"));
        assert!(
            !cron.contains("MUST NOT be a binary float"),
            "money trivia must not ride along"
        );

        // An invoice task gets money, not cron.
        let money = relevant_pitfalls("Compute the invoice total price in currency with rounding")
            .expect("money task must retrieve the money pitfall");
        assert!(money.contains("MUST NOT be a binary float"));
        assert!(
            !money.contains("CRON day-of-week"),
            "cron trivia must not ride along"
        );

        // Retrieval is case-insensitive (specs are prose, not lowercase).
        assert!(relevant_pitfalls("Handle TIMEZONE and DST correctly").is_some());

        // A task about none of it gets NOTHING — silence beats diluting the prompt.
        assert!(
            relevant_pitfalls("Render a static about page with a logo").is_none(),
            "an unrelated task must receive no pitfalls at all"
        );
    }

    /// The HTTP-timeout fact must REACH the module that owns the client, and must not spray.
    ///
    /// `client_timeouts` is the only check of 35 where all four archived 3-node cells score below the
    /// 1-node cell — every one of them shipped "no request timeout". The fact existing in the library
    /// is worth nothing if no trigger carries it to the author, which is exactly the failure
    /// `pitfall_items_match_triggers` cannot see: that test only proves the ROW EXISTS.
    #[test]
    fn the_http_timeout_fact_reaches_a_client_task_and_no_one_else() {
        let client = relevant_pitfalls(
            "Build the Meridian client: fetch payments from http://127.0.0.1:8930/v1/payments",
        )
        .expect("a task that calls an HTTP endpoint must retrieve the timeout pitfall");
        assert!(client.contains("outbound HTTP call needs an EXPLICIT timeout"));

        // Library names, not domain words. The archived plans put "vendor" in 11 of 16 task specs and
        // "api" in 6, so triggering on either would hand this fact to tasks that open no socket.
        assert!(
            relevant_pitfalls("Store the vendor payment rows in the api schema").is_none(),
            "domain words must NOT trigger it — that is the crying-wolf this library forbids"
        );

        // And it must not drag the rest of the library along with it.
        assert!(
            !client.contains("CRON day-of-week"),
            "cron trivia must not ride along with the network fact"
        );
    }

    /// Every bool lever the golden bake ships ON must SAY so in its own doc block.
    ///
    /// The v1.41.94 bake flipped ~40 levers ON in `Default for SwarmConfig` and updated none of their
    /// prose, leaving 25 docs asserting "OFF by default" about behaviour that is now what ships (F392).
    /// That is not cosmetic: it made me publish a false claim about `sink_lean_prefill` — documented
    /// "None => OFF", actually `Some(true)` and ON in every archived run — and design an arm to enable
    /// something already enabled.
    ///
    /// The invariant is deliberately the SIMPLE one: presence of a marker, never "does the prose
    /// contradict the default". Phrase-matching was tried and failed three different ways (F393) — a
    /// claim split across two doc lines, a claim in `//` rather than `///`, and an off-by-default
    /// phrase sitting inside an ARGUMENT rather than an assertion. A marker has none of those shapes.
    /// A round that verified NOTHING must never read as a pass, however much else it recorded.
    ///
    /// MEASURED: 9 of 9 `spec_contract` events in the archive carried
    /// `verified: 0, findings: 0, inconclusive: 1` and the string "every advertised check that bound
    /// was satisfied". The old condition demanded all three counters be zero before saying "CHECKED
    /// NOTHING", so the single message explaining WHY it could not conclude promoted the round to
    /// success — the check reported best when it was most honest.
    #[test]
    fn a_spec_contract_round_that_verified_nothing_never_reads_as_a_pass() {
        // The exact archived shape: nothing bound, one recorded reason.
        assert!(
            spec_contract_detail(0, 0).starts_with("CHECKED NOTHING"),
            "{}",
            spec_contract_detail(0, 0)
        );
        // A real pass needs an affirmative 2xx, and only then.
        assert_eq!(
            spec_contract_detail(3, 0),
            "every advertised check that bound was satisfied"
        );
        // A finding outranks everything, including a verified endpoint alongside it.
        assert!(spec_contract_detail(0, 1).contains("blocking the green claim"));
        assert!(spec_contract_detail(3, 1).contains("blocking the green claim"));
        // The regression itself: verified==0 must NOT be rescued by a nonzero verified count elsewhere
        // or by any other signal — the only input that can produce a pass is `verified`.
        for verified in 0..4usize {
            let d = spec_contract_detail(verified, 0);
            assert_eq!(
                d == "every advertised check that bound was satisfied",
                verified > 0,
                "verified={verified} produced {d}"
            );
        }
    }

    /// VALIDATED AGAINST THE ARCHIVE BEFORE SHIPPING, in both directions: run over the five archived
    /// app trees, the script finds 0 findings in the one cell the scorer marks `client_timeouts` 1.00
    /// and 4/15/7/3 in the four it marks 0.00 — 5 of 5 agreement with an independent grader, including
    /// the production client (`vendorsync/meridian.py`) in two of them.
    ///
    /// This test covers the PARSER half, which is what runs without python.
    /// The advertised invocation is what makes the contract check able to conclude at all.
    #[test]
    fn spec_run_argv_v2_fills_each_placeholder_by_kind() {
        let tmp = tempfile::TempDir::new().unwrap();
        let spec = "Run `python -m vendorsync --db PATH --port N` to serve.";
        let (argv, ports) = spec_run_argv_v2(spec, "vendorsync", tmp.path(), 8999);
        assert_eq!(argv[0], "--db");
        assert!(argv[1].starts_with(&*tmp.path().to_string_lossy()));
        assert_eq!(argv[2], "--port");
        assert_eq!(ports.len(), 1);
        assert_eq!(argv[3], ports[0].to_string());

        // F910 defect 1, pinned: the sb-7 combined boot — TWO DISTINCT ports, a created
        // scratch dir, the spec's vendor base for URL, a scratch tokens file.
        let sb7 = "Boot: `python -m app --db-dir P --ledger-port N --notifier-port M --vendor URL --tokens-file T`";
        let (a, p2) = spec_run_argv_v2(sb7, "app", tmp.path(), 8901);
        assert_eq!(p2.len(), 2, "each port-flag gets its OWN port: {a:?}");
        assert_ne!(
            p2[0], p2[1],
            "the two services must never share a probe port"
        );
        let vendor = a[a.iter().position(|t| t == "--vendor").unwrap() + 1].clone();
        assert_eq!(
            vendor, "http://127.0.0.1:8901",
            "URL fills with the spec's vendor base"
        );
        let dbdir = a[a.iter().position(|t| t == "--db-dir").unwrap() + 1].clone();
        assert!(
            std::path::Path::new(&dbdir).is_dir(),
            "dir-flag gets a CREATED directory"
        );
        let tok = a[a.iter().position(|t| t == "--tokens-file").unwrap() + 1].clone();
        assert!(
            std::path::Path::new(&tok).is_file(),
            "token-flag gets a scratch file"
        );

        // Literals survive; no invocation / wrong package = empty.
        let (lit, _) = spec_run_argv_v2("`python -m app serve --port N`", "app", tmp.path(), 9);
        assert_eq!(lit[0], "serve");
        assert!(
            spec_run_argv_v2("Build a CLI. It should be fast.", "app", tmp.path(), 9)
                .0
                .is_empty()
        );
        assert!(
            spec_run_argv_v2("`python -m other --port N`", "app", tmp.path(), 9)
                .0
                .is_empty()
        );
    }

    #[test]
    fn spec_python_invocations_lists_every_advertised_entry_once() {
        let spec = "`python -m app --db-dir P` boots both. `python -m app.ledgerd --port N` alone. `python -m app.notifierd --port M` alone. Test with `python -m pytest`. Again: `python -m app --db-dir P`.";
        assert_eq!(
            spec_python_invocations(spec),
            vec!["app", "app.ledgerd", "app.notifierd"],
            "deduped, spec order, tool modules excluded"
        );
    }

    #[test]
    fn the_no_timeout_scan_turns_its_json_into_actionable_findings() {
        let d = parse_http_timeout(
            r#"{"checked": 3, "findings": [{"file": "vendorsync/meridian.py", "line": 55, "call": "urlopen"}]}"#,
        );
        assert!(d.ran);
        assert_eq!(d.checked, 3);
        assert_eq!(d.findings.len(), 1);
        assert!(d.findings[0].contains("vendorsync/meridian.py:55"));
        assert!(d.findings[0].contains("urlopen"));
        // The finding must forbid the cheap escapes, or a weak model deletes the call to clear it.
        assert!(d.findings[0].contains("Do not remove the call"));

        // A clean tree: ran, checked>0, no findings — distinguishable from "did not run".
        let clean = parse_http_timeout(r#"{"checked": 5, "findings": []}"#);
        assert!(clean.ran && clean.checked == 5 && clean.findings.is_empty());

        // Python is free to print a warning first; the last JSON line still wins.
        let noisy =
            parse_http_timeout("DeprecationWarning: whatever\n{\"checked\": 1, \"findings\": []}");
        assert!(noisy.ran && noisy.checked == 1);

        // Garbage must NOT read as a clean tree: `ran` stays false so `checked == 0` cannot be mistaken
        // for a scan that looked and found nothing (L230).
        let broken = parse_http_timeout("not json at all");
        assert!(
            !broken.ran,
            "unparseable output must not report a completed scan"
        );
    }

    /// REGRESSION, from a LIVE FALSE CLEAR — and the reason the test above was never enough.
    ///
    /// `the_no_timeout_scan_turns_its_json_into_actionable_findings` tests `parse_http_timeout`,
    /// which is the JSON PARSER. Nothing ever executed `HTTP_TIMEOUT_SCRIPT` itself, so the thing
    /// that actually decides what is a defect was the one part with no coverage. baseline-n1-r0
    /// then shipped `http.client.HTTPSConnection(self._host, self._port)` — timeout defaults to the
    /// global socket default of None, i.e. blocks FOREVER — and the scan emitted `findings: 0` twice
    /// while affirming every outbound call passed a timeout. A parser test cannot catch that.
    ///
    /// The negative controls matter as much as the positives: this scan feeds `verdict.findings`,
    /// which gates `final_passed`, so a false positive stops a CORRECT build and sends the repair
    /// loop to edit working code.
    #[tokio::test]
    async fn the_timeout_scan_sees_http_client_and_still_spares_a_positional_timeout() {
        let dir = std::env::temp_dir().join(format!("goose_http_to_{}", std::process::id()));
        let pkg = dir.join("pkg");
        std::fs::create_dir_all(&pkg).unwrap();
        std::fs::write(pkg.join("__init__.py"), "").unwrap();
        // THE MEASURED DEFECT, in all three import forms it can wear.
        std::fs::write(
            pkg.join("bad.py"),
            "import http.client\nfrom http import client\nfrom http.client import HTTPSConnection\n\
             def a(h, p):\n    return http.client.HTTPSConnection(h, p)\n\
             def b(h):\n    return client.HTTPConnection(h)\n\
             def c(h):\n    return HTTPSConnection(h)\n",
        )
        .unwrap();
        // CORRECT CODE, which must stay silent: keyword timeout, and timeout in its POSITIONAL slot.
        std::fs::write(
            pkg.join("good.py"),
            "import http.client\nfrom urllib.request import urlopen\n\
             def a(h, p):\n    return http.client.HTTPSConnection(h, p, timeout=10)\n\
             def b(h, p):\n    return http.client.HTTPConnection(h, p, 30)\n\
             def c(u):\n    return urlopen(u, None, 30)\n",
        )
        .unwrap();
        let planned: Vec<String> = ["pkg/__init__.py", "pkg/bad.py", "pkg/good.py"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let res = http_timeout_scan(&dir, TargetLang::Python, &app_scope_py(&dir, &planned)).await;
        let _ = std::fs::remove_dir_all(&dir);
        if !res.ran {
            return; // python3 not available in this environment
        }
        let joined = res.findings.join("\n");
        assert!(
            res.checked >= 2,
            "a scan that parsed nothing proves nothing (L230): checked={}",
            res.checked
        );
        for form in ["bad.py:5", "bad.py:7", "bad.py:9"] {
            assert!(
                joined.contains(form),
                "http.client with no timeout must be flagged at {form}: {joined}"
            );
        }
        assert!(
            !joined.contains("good.py"),
            "a timeout passed by keyword OR in its positional slot is CORRECT code and must not be \
             flagged — a false positive here sends the repair loop to break a working client: {joined}"
        );
    }

    /// F870 END-TO-END (L242: the DETECTOR, not the parser). The measured defect verbatim:
    /// swarm-3node-r0's styles.css defined 35 class rules and the markup wore almost none —
    /// the page shipped browser-default and every gate stayed green. The negative controls
    /// carry equal weight: this scan feeds `verdict.findings`, so a false fire sends the
    /// repair loop to break working styling. Review-hardened v2: the adversarial pass proved
    /// the first version's test PASSED VACUOUSLY (the gate resolved OFF and the early-return
    /// blamed python3), so this version checks python3 itself and then DEMANDS the scan ran.
    #[tokio::test]
    async fn css_coherence_flags_the_dead_stylesheet_and_spares_real_styling_shapes() {
        let have_py = std::process::Command::new("python3")
            .arg("--version")
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false);
        if !have_py {
            return; // the one legitimate skip; a dead gate can no longer hide behind it
        }
        let dir = std::env::temp_dir().join(format!("goose_cssco_{}", std::process::id()));
        std::fs::create_dir_all(dir.join("web")).unwrap();
        // THE MEASURED DEFECT: id-only markup, a class-only stylesheet, js that builds rows
        // with literal classes from a THIRD vocabulary.
        std::fs::write(
            dir.join("web/index.html"),
            "<body><h1 id=\"title\">App</h1><table id=\"rows\"></table>\
             <div id=\"loading-state\">Loading</div></body>",
        )
        .unwrap();
        std::fs::write(
            dir.join("web/styles.css"),
            "body { font-family: system-ui; } /* .ghost { color: red } */\n\
             .app-header { padding: 1rem } .btn { border: 0 } .btn-primary { background: #333 }\n\
             .toolbar { display: flex } .spinner { transition: .5s } .state-overlay { display: none }\n\
             .status-badge { background: url(ok.png) } .pagination { gap: 4px }\n\
             .summary-bar { color: #222 } .error-banner { color: red }\n\
             @media (max-width: 600px) { .table-wrapper { overflow-x: auto } }",
        )
        .unwrap();
        std::fs::write(
            dir.join("web/app.js"),
            "document.getElementById('rows').innerHTML = '<tr><td class=\"cell-x\">x</td></tr>';",
        )
        .unwrap();
        let files: Vec<String> = ["web/index.html", "web/styles.css", "web/app.js"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let res = css_coherence_scan(&dir, &files).await;
        assert!(
            res.ran,
            "python3 is present yet the scan did not run — the gate is dead again (the exact \
             defect the review caught: swarm_gate(_, true) is not a default)"
        );
        assert_eq!(res.checked, 3, "all three web files must be parsed");
        assert_eq!(
            res.findings.len(),
            1,
            "an id-only page under a class-only stylesheet is THE unstyled-page defect: {:?}",
            res.findings
        );
        let f = &res.findings[0];
        for needle in [
            "web/styles.css",
            ".app-header",
            "defines 11 class rules",
            "do not delete the styling",
        ] {
            assert!(f.contains(needle), "finding must carry `{needle}`: {f}");
        }
        // The finding must lead with a SINGLE routable path token (multi-file "a.css, b.css"
        // prefixes fail is_code and fall to the unassigned bucket — review finding).
        let prefix = f.split(':').next().unwrap_or("");
        assert!(
            !prefix.contains(' ') && prefix.ends_with(".css"),
            "finding prefix must be one routable css path: {prefix}"
        );

        // COHERENT SHAPES, same scan — each must stay silent.
        // (a) literal classes wearing most of the stylesheet;
        std::fs::write(
            dir.join("web/index.html"),
            "<body class=\"app-header\"><button class=\"btn btn-primary\">Go</button>\
             <div class=\"toolbar spinner state-overlay summary-bar error-banner\"></div>\
             <span class=\"status-badge\"></span><nav class=\"pagination\"></nav></body>",
        )
        .unwrap();
        std::fs::write(
            dir.join("web/app.js"),
            "el.classList.add('table-wrapper');\nrow.innerHTML = `<td class=\"status-badge\">ok</td>`;",
        )
        .unwrap();
        let clean = css_coherence_scan(&dir, &files).await;
        assert!(
            clean.ran && clean.findings.is_empty(),
            "a stylesheet the markup actually wears must stay silent: {:?}",
            clean.findings
        );
        // (b) the SPA shape from the review's fp1: classes applied via interpolated
        // attributes whose names live in constants/returns — the widened same-file literal
        // harvest must silence it.
        std::fs::write(
            dir.join("web/index.html"),
            "<body><div id=\"app\"></div></body>",
        )
        .unwrap();
        std::fs::write(
            dir.join("web/app.js"),
            "const T = 'toolbar';\nfunction rowCls(r){ return r.ok ? 'app-header' : 'error-banner'; }\n\
             function badge(r){ if (r.s === 'paid') return 'btn btn-primary'; if (r.s === 'x') \
             return 'spinner state-overlay'; return 'status-badge pagination summary-bar table-wrapper'; }\n\
             app.innerHTML = `<div class=\"${T}\"><span class=\"${badge(r)} ${rowCls(r)}\"></span></div>`;",
        )
        .unwrap();
        let spa = css_coherence_scan(&dir, &files).await;
        let _ = std::fs::remove_dir_all(&dir);
        assert!(
            spa.ran && spa.findings.is_empty(),
            "computed-class SPAs whose names appear as literals must stay silent: {:?}",
            spa.findings
        );
    }

    /// F874: a task id with a path separator aimed its digest at a nonexistent directory and the
    /// write failed SILENTLY — every scheduled fix task ran invisible, and the judge, whose
    /// deterministic evidence IS that digest, was disarmed for exactly the tasks that repair the
    /// app (measured: 9 empty `ok` reviews in 10 minutes on one fix task). The key must be a flat
    /// filename AND must round-trip back to the task id, because the desktop indexes digests by
    /// filename and every consumer looks them up by task id.
    #[test]
    fn activity_digest_key_flattens_paths_and_round_trips() {
        // The desktop's decoder, mirrored here so the two can never drift apart: a left-to-right
        // scan of `~.` escape pairs (`~t` -> `~`, `~s` -> `/`, `~b` -> `\`).
        fn decode(k: &str) -> String {
            let mut out = String::new();
            let mut it = k.chars();
            while let Some(c) = it.next() {
                if c == '~' {
                    match it.next() {
                        Some('t') => out.push('~'),
                        Some('s') => out.push('/'),
                        Some('b') => out.push('\\'),
                        Some(other) => {
                            out.push('~');
                            out.push(other);
                        }
                        None => out.push('~'),
                    }
                } else {
                    out.push(c);
                }
            }
            out
        }
        for id in [
            "fix::r0::vendorsync/web/app.js",
            "fix::r12::a/b/c/d.py",
            "verify::web-index",
            "integrate-verify",
            "fix::r0::weird~name.py",
        ] {
            let k = activity_digest_key(id);
            assert!(
                !k.contains('/') && !k.contains('\\'),
                "digest key must be a flat filename: {k}"
            );
            assert_eq!(
                decode(&k),
                id,
                "the key must round-trip through the decoder"
            );
        }
        // INJECTIVE: a literal `~` and a separator must never collide on one digest file.
        // The escape alphabet's whole reason: adjacent mixes that the doubling scheme aliased.
        assert_ne!(
            activity_digest_key("fix::r0::a/~b"),
            activity_digest_key("fix::r0::a~/b"),
            "adjacent mixed separators must not alias"
        );
        assert_ne!(
            activity_digest_key("fix::r0::a/b"),
            activity_digest_key("fix::r0::a~b"),
            "a/b and a~b must not alias onto the same digest"
        );
        // Ids without separators are untouched, so every existing digest keeps its name.
        assert_eq!(activity_digest_key("api"), "api");
        assert_eq!(activity_digest_key("verify::api"), "verify::api");
    }

    /// F877: a fix worker repairing `meridian.py` against five failing assertions in
    /// `test_meridian.py` never received the test file — the dependency loop skips tests by
    /// construction — so it was asked to satisfy an expectation it could not read (measured:
    /// 1,756s, promoted:false). The finding text already names the evidence; extract it.
    #[test]
    fn fix_evidence_pointers_names_the_files_the_findings_cite() {
        let findings = vec![
            "`pytest -q` failed: FAILED test_meridian.py::TestFetchAllPaymentsPagination::\
             test_multi_page_pagination — assert body == {...}"
                .to_string(),
            "vendorsync/web/app.js:32 references DOM id `summary-line` which NO html file in the \
             app defines (see vendorsync/web/index.html)."
                .to_string(),
        ];
        let block = fix_evidence_pointers(&findings);
        for p in [
            "test_meridian.py",
            "vendorsync/web/app.js",
            "vendorsync/web/index.html",
        ] {
            assert!(block.contains(p), "must point the fixer at {p}: {block}");
        }
        assert!(
            block.contains("read prohibitions in your rules do NOT apply"),
            "the pointer is useless unless it overrides the no-reading rules: {block}"
        );
        // A finding naming no file adds nothing — no empty ceremony section.
        assert!(fix_evidence_pointers(&["the server never bound a port".to_string()]).is_empty());
    }

    /// F871 holistic-review round: the DELETION ESCAPE (a fix twin deleting/gutting the
    /// stylesheet cleared the finding and was PROMOTED), and the TS/React false-fire (scope
    /// dropped .tsx and JSX className was never harvested — confirmed on two real archived
    /// apps).
    #[tokio::test]
    async fn css_coherence_closes_the_deletion_escape_and_reads_jsx() {
        let have_py = std::process::Command::new("python3")
            .arg("--version")
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false);
        if !have_py {
            return;
        }
        let dir = std::env::temp_dir().join(format!("goose_cssdel_{}", std::process::id()));
        std::fs::create_dir_all(dir.join("web")).unwrap();
        // (a) DELETED: the html links a stylesheet that does not exist — must fire even with
        // no .css in scope at all.
        std::fs::write(
            dir.join("web/index.html"),
            "<head><link rel=\"stylesheet\" href=\"styles.css\"></head><body><h1>App</h1></body>",
        )
        .unwrap();
        let files_no_css: Vec<String> = vec!["web/index.html".to_string()];
        let gone = css_coherence_scan(&dir, &files_no_css).await;
        assert!(gone.ran, "html-only scope must still run the scan");
        assert!(
            gone.findings.len() == 1 && gone.findings[0].contains("does NOT exist"),
            "a linked-but-deleted stylesheet is a finding, not a clean tree: {:?}",
            gone.findings
        );
        // (b) GUTTED: the stylesheet exists but holds almost nothing.
        std::fs::write(dir.join("web/styles.css"), "body { color: #111 }").unwrap();
        let files: Vec<String> = vec!["web/index.html".into(), "web/styles.css".into()];
        let gutted = css_coherence_scan(&dir, &files).await;
        assert!(
            gutted.findings.len() == 1 && gutted.findings[0].contains("effectively unstyled"),
            "a nearly-empty linked stylesheet must fire: {:?}",
            gutted.findings
        );
        // (c) JSX/TS: a React-shaped app whose vocabulary lives in className attributes of a
        // .tsx file — quoted AND braced forms — must be silent (the real loop-05 false-fire).
        std::fs::write(
            dir.join("web/styles.css"),
            ".mine-counter { color: red } .cell { border: 0 } .cell-open { background: #eee }\n\
             .board { display: grid } .status { font-weight: 700 } .btn-reset { padding: 4px }\n\
             .timer { font-family: monospace } .flag { color: orange } .grid-row { display: flex }\n\
             .overlay { position: fixed } .won { color: green } .lost { color: black }",
        )
        .unwrap();
        std::fs::write(
            dir.join("web/app.tsx"),
            "export function Board() {\n\
             return <div className=\"board overlay\">\n\
               <span className=\"mine-counter timer\">0</span>\n\
               <button className=\"btn-reset\">r</button>\n\
               <div className={r.won ? 'won status' : 'lost status'}>\n\
                 <i className={`cell ${open ? 'cell-open' : 'flag'}`} />\n\
                 <b className=\"grid-row\"/></div></div>;\n}",
        )
        .unwrap();
        let files_tsx: Vec<String> = vec![
            "web/index.html".into(),
            "web/styles.css".into(),
            "web/app.tsx".into(),
        ];
        let jsx = css_coherence_scan(&dir, &files_tsx).await;
        let _ = std::fs::remove_dir_all(&dir);
        assert!(
            jsx.ran && jsx.findings.is_empty(),
            "a styled JSX/TSX app must stay silent — className quoted and braced forms are \
             real usage: {:?}",
            jsx.findings
        );
    }

    /// C1 END-TO-END (F711/F712): the SCAN must skip the swarm's own tests, not merely the helper.
    ///
    /// My first test for this covered `is_test_path` in isolation and passed — which proves nothing
    /// about the scan, because the defect it replaces was a CALL SITE handing a full path to a
    /// basename predicate. That is the third time in one day a pure-predicate test would have missed
    /// the real bug (the shadow/branch drift, the orphan refusal that could never fire, and this).
    /// So this drives `http_timeout_scan` itself and asserts BOTH directions on the same run.
    #[tokio::test]
    async fn timeout_scan_skips_the_swarms_own_tests_and_still_flags_app_code() {
        let dir = std::env::temp_dir().join(format!("c1scan{}", std::process::id()));
        let pkg = dir.join("pkg");
        let tests = dir.join("tests");
        std::fs::create_dir_all(&pkg).unwrap();
        std::fs::create_dir_all(&tests).unwrap();
        std::fs::write(pkg.join("__init__.py"), "").unwrap();
        // APP CODE with a real no-timeout defect — MUST still be flagged.
        std::fs::write(
            pkg.join("bad.py"),
            "import http.client\ndef a(h):\n    return http.client.HTTPConnection(h)\n",
        )
        .unwrap();
        // THE SWARM'S OWN TEST FILE, same defect. 28 of 60 real findings named exactly this shape,
        // and the scorer never grades it. MUST be absent.
        std::fs::write(
            tests.join("test_api.py"),
            "import http.client\ndef t(h):\n    return http.client.HTTPConnection(h)\n",
        )
        .unwrap();

        let planned: Vec<String> = ["pkg/__init__.py", "pkg/bad.py", "tests/test_api.py"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let app_only: Vec<String> = planned
            .iter()
            .filter(|f| !is_test_path(TargetLang::Python, f))
            .cloned()
            .collect();
        let skipped = planned.len() - app_only.len();
        let res = http_timeout_scan(&dir, TargetLang::Python, &app_scope_py(&dir, &app_only)).await;
        let _ = std::fs::remove_dir_all(&dir);
        if !res.ran {
            return; // python3 not available in this environment
        }
        let joined = res.findings.join("\n");

        assert_eq!(skipped, 1, "the filter must remove exactly the tests/ file");
        // A FILTER THAT ATE THE WHOLE SCOPE LOOKS IDENTICAL TO A CLEAN APP — this is the guard.
        assert!(
            res.checked > 0,
            "checked==0 after filtering: the filter removed everything, so a clean result here is \
             silence, not evidence"
        );
        assert!(
            joined.contains("bad.py"),
            "APP code with a no-timeout client must STILL be flagged — if the filter is too greedy \
             the detector goes silent and the fix loop stops seeing real defects: {joined}"
        );
        assert!(
            !joined.contains("test_api.py"),
            "the swarm's OWN test file must NOT be flagged — 55% of real round-0 findings were this, \
             and the scorer grades none of them: {joined}"
        );
    }

    #[test]
    fn every_baked_on_lever_declares_itself_baked_on() {
        const SRC: &str = include_str!("swarm.rs");

        // `split_once` rather than byte-slicing: this file contains multi-byte characters (the marker's
        // own ⚠️ among them), and indexing a &str by byte offset is a panic waiting for the day a
        // boundary moves.
        let d = SRC
            .split_once("impl Default for SwarmConfig {")
            .expect("Default impl")
            .1;
        let d = d.split_once("\n    }\n}").expect("end of Default impl").0;
        let on: std::collections::HashSet<&str> = d
            .lines()
            .filter_map(|l| l.trim().split_once(':'))
            .filter(|(_, v)| matches!(v.trim().trim_end_matches(','), "true" | "Some(true)"))
            .map(|(n, _)| n.trim())
            .collect();

        let s = SRC
            .split_once("pub struct SwarmConfig {")
            .expect("SwarmConfig struct")
            .1;
        let s = s.split_once("\n}").expect("end of struct").0;

        let mut doc = String::new();
        let mut checked = 0usize;
        let mut missing: Vec<&str> = Vec::new();
        for line in s.lines() {
            let t = line.trim();
            if t.starts_with("//") || t.starts_with("#[") {
                doc.push_str(t);
                doc.push('\n');
                continue;
            }
            if let Some((name, ty)) = t.strip_prefix("pub ").and_then(|r| r.split_once(':')) {
                if matches!(ty.trim().trim_end_matches(','), "bool" | "Option<bool>")
                    && on.contains(name.trim())
                {
                    checked += 1;
                    if !doc.contains("BAKED ON") {
                        missing.push(name.trim());
                    }
                }
            }
            doc.clear();
        }

        // ANTI-VACUITY. If the struct is renamed or the layout changes, this parser quietly matches
        // nothing and an empty `missing` would read as a pass — `all([])` is true. A floor makes the
        // parser's own failure loud instead, and it is the only reason this test can be trusted.
        assert!(
            checked >= 40,
            "parser found only {checked} baked-on bool levers (expected 40+) — the PARSER is broken, \
             not the docs; fix it before trusting an empty failure list"
        );
        assert!(
            missing.is_empty(),
            "{} lever(s) are ON in `Default for SwarmConfig` but their doc block never says so: {:?}. \
             Add a `BAKED ON` line to each, or the next reader will believe the stale default and act \
             on it (F392).",
            missing.len(),
            missing
        );
    }

    #[test]
    fn summarize_tool_call_extracts_the_intent_field() {
        // shell: the whole command line is the summary.
        assert_eq!(
            summarize_tool_call(
                "developer__shell",
                &serde_json::json!({"command": "pytest -q tests/"})
            ),
            "pytest -q tests/"
        );
        // text_editor: verb + path.
        assert_eq!(
            summarize_tool_call(
                "developer__text_editor",
                &serde_json::json!({"command": "write", "path": "src/main.py", "file_text": "x"})
            ),
            "write src/main.py"
        );
        // path-only tools fall back to the path.
        assert_eq!(
            summarize_tool_call("some__reader", &serde_json::json!({"path": "notes.md"})),
            "notes.md"
        );
        // query-style tools surface the query; newlines/extra whitespace are flattened.
        assert_eq!(
            summarize_tool_call("web__search", &serde_json::json!({"query": "a\n  b   c"})),
            "a b c"
        );
        // No known field: compact JSON, never empty.
        assert!(!summarize_tool_call("x__y", &serde_json::json!({"foo": 1})).is_empty());
        // Overlong summaries are capped with an ellipsis.
        let long = "x ".repeat(300);
        let s = summarize_tool_call("developer__shell", &serde_json::json!({"command": long}));
        assert!(s.chars().count() <= 200, "summary must be capped");
        assert!(s.ends_with('…'));
    }

    #[test]
    fn clip_tail_keeps_the_informative_end() {
        assert_eq!(clip_tail("short output", 400), "short output");
        let long: String = "x".repeat(500);
        let c = clip_tail(&long, 400);
        assert_eq!(c.chars().count(), 401, "400 chars + a leading ellipsis");
        assert!(c.starts_with('…'));
    }

    #[test]
    fn build_reasoning_drops_trivial_fragments() {
        // The lone dots / backticks / stray words coder models emit between tool calls are dropped —
        // so the panel never shows a reasoning box holding just ".".
        assert_eq!(
            build_reasoning(&[".".into(), "`.".into(), " result".into(), "backs".into()]),
            ""
        );
        // A real narration sentence survives.
        assert_eq!(
            build_reasoning(&[
                ".".into(),
                "Writing the tokenizer module now.".into(),
                "`".into()
            ]),
            "Writing the tokenizer module now."
        );
    }

    #[test]
    fn build_full_reasoning_matches_full_walk_at_clip_boundary() {
        // build_full_reasoning now walks from the back and stops once it has covered the 24000-char clip,
        // instead of scanning the whole (growing) texts vec every write. Prove the output is byte-identical
        // to the naive full walk it replaced, ACROSS the clip boundary where the early-stop actually kicks in.
        fn reference(texts: &[String]) -> String {
            let joined = texts
                .iter()
                .map(|t| t.trim())
                .filter(|t| t.chars().count() >= 6 && t.contains(char::is_whitespace))
                .collect::<Vec<_>>()
                .join("\n\n");
            clip_tail(&joined, 24000)
        }
        // 400 chunks of ~120 chars each ≈ 48000 chars total — well past the 24000 clip, plus interleaved
        // trivial fragments (dropped) and a couple of short no-whitespace tokens (also dropped).
        let mut texts: Vec<String> = Vec::new();
        for i in 0..400 {
            texts.push(".".into());
            texts.push(format!(
                "chunk {i} narration line describing what the worker is doing at this particular step {}",
                "x".repeat(60)
            ));
            texts.push("`".into());
        }
        assert_eq!(build_full_reasoning(&texts), reference(&texts));
        // And the small case (under the clip) is identical too.
        let small = vec![
            "first substantive narration line".to_string(),
            ".".to_string(),
            "second substantive narration line".to_string(),
        ];
        assert_eq!(build_full_reasoning(&small), reference(&small));
        assert_eq!(build_full_reasoning(&[]), reference(&[]));
    }

    #[test]
    fn integrate_verify_does_not_block_on_tests() {
        // A failing `tests` subtask must not block integrate-verify (UNIQ6: tests failed -> integrate-verify
        // never ran -> the app's real bug went uncaught + the run looked failed for the wrong reason).
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"core","depends_on":[],"files":["core.py"]},
                {"id":"cli-entry","depends_on":["core"],"files":["cli.py"]},
                {"id":"tests","depends_on":["core"],"files":["tests/test_core.py"]},
                {"id":"integrate-verify","depends_on":["core","cli-entry","tests"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let stripped = strip_integrate_verify_test_deps(&mut plan, TargetLang::Python);
        assert_eq!(stripped, 1, "the single 'tests' dep should be stripped");
        let iv = plan["subtasks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|s| s["id"] == "integrate-verify")
            .unwrap();
        let deps: Vec<&str> = iv["depends_on"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|d| d.as_str())
            .collect();
        assert_eq!(
            deps,
            vec!["core", "cli-entry"],
            "real module/entry deps stay; tests dep removed"
        );
    }

    #[test]
    fn relax_test_module_deps_truth_table() {
        fn deps(plan: &serde_json::Value, id: &str) -> String {
            plan["subtasks"]
                .as_array()
                .unwrap()
                .iter()
                .find(|s| s["id"] == id)
                .unwrap()["depends_on"]
                .as_array()
                .unwrap()
                .iter()
                .filter_map(|d| d.as_str())
                .collect::<Vec<_>>()
                .join(",")
        }
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"store","depends_on":[],"files":["store.py"]},
                {"id":"shared","depends_on":[],"files":["shared.py"]},
                {"id":"cli-entry","depends_on":["store","shared"],"files":["cli.py","__main__.py"]},
                {"id":"test-store","depends_on":["store","cli-entry"],"files":["test_store.py"]},
                {"id":"test-shared-user","depends_on":["shared","cli-entry"],"files":["test_shared.py"]},
                {"id":"test-cli","depends_on":["cli-entry"],"files":["test_cli.py"]},
                {"id":"tests","depends_on":["store","cli-entry"],"files":["test_store.py","test_cli.py"]},
                {"id":"integrate-verify","depends_on":["store","shared","cli-entry"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let n = relax_test_module_deps(&mut plan, TargetLang::Python);
        // uniquely-leaf test: cli edge dropped, its module dep kept
        assert_eq!(deps(&plan, "test-store"), "store");
        // THE regression guard: a leaf test that genuinely imports a sibling keeps the sibling, drops only cli
        assert_eq!(deps(&plan, "test-shared-user"), "shared");
        // the cli's OWN test keeps its cli dep (self is cli)
        assert_eq!(deps(&plan, "test-cli"), "cli-entry");
        // monolithic/ambiguous test (spans store+cli) left untouched
        assert_eq!(deps(&plan, "tests"), "store,cli-entry");
        // integrate-verify never touched
        assert_eq!(deps(&plan, "integrate-verify"), "store,shared,cli-entry");
        assert_eq!(n, 2, "exactly the two stray cli edges relaxed");
    }

    #[test]
    fn relax_test_module_deps_noop_on_monolithic_plan() {
        let mut plan: serde_json::Value = serde_json::from_str(
            r#"{"subtasks":[
                {"id":"core","depends_on":[],"files":["core.py"]},
                {"id":"cli-entry","depends_on":["core"],"files":["cli.py"]},
                {"id":"tests","depends_on":["cli-entry"],"files":["tests/test_core.py","tests/test_cli.py"]},
                {"id":"integrate-verify","depends_on":["core","cli-entry","tests"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let before = plan.clone();
        let n = relax_test_module_deps(&mut plan, TargetLang::Python);
        assert_eq!(n, 0, "no uniquely-leaf per-module test -> nothing relaxed");
        assert_eq!(plan, before, "monolithic plan left byte-identical");
    }

    #[tokio::test]
    async fn ast_review_counts_from_pkg_import_submodule_as_wired() {
        // A package whose __main__ wires its cli via `from pkg import cli` must NOT be flagged unwired
        // (the observed UNIQ12 false-positive); a genuinely orphaned module still must be. Skips if python3
        // is unavailable (run_ast_review returns ran=false then).
        let dir = std::env::temp_dir().join(format!("goose_ast_review_{}", std::process::id()));
        let pkg = dir.join("pkg");
        std::fs::create_dir_all(&pkg).unwrap();
        std::fs::write(pkg.join("__init__.py"), "").unwrap();
        std::fs::write(pkg.join("__main__.py"), "from pkg import cli\ncli.main()\n").unwrap();
        std::fs::write(pkg.join("cli.py"), "def main():\n    return 0\n").unwrap();
        std::fs::write(pkg.join("orphan.py"), "x = 1\n").unwrap();
        // Scoped to the plan's own files. The assertions below are UNCHANGED, so they double as proof
        // that scoping did not BLIND the check — the genuine orphan must still be flagged.
        let planned: Vec<String> = [
            "pkg/__init__.py",
            "pkg/__main__.py",
            "pkg/cli.py",
            "pkg/orphan.py",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        let res = run_ast_review(&dir, &app_scope_py(&dir, &planned)).await;
        let _ = std::fs::remove_dir_all(&dir);
        if !res.ran {
            return; // python3 not available in this environment
        }
        let joined = res.findings.join("\n");
        assert!(
            !joined.contains("module 'pkg.cli' is imported by no"),
            "cli wired via `from pkg import cli` must not be flagged UNWIRED: {joined}"
        );
        assert!(
            joined.contains("pkg.orphan"),
            "a genuinely orphaned module must still be flagged: {joined}"
        );
    }

    /// REGRESSION, from a FALSE DEMOTE on a WORKING app.
    ///
    /// A run built settle/api.py — the FastAPI app, with the spec's exact /api surface — plus a
    /// __main__.py doing `uvicorn.run("settle.api:app")`. That is a STRING, not an import, so the
    /// import-edge scan reported "settle.api is imported by no non-test module" and
    /// `unwired_demotes_verified` RETRACTED `verified` on the best app of the run. Technically true,
    /// semantically false. Without this, EVERY idiomatic FastAPI/Flask/Celery layout is flagged — the
    /// conventional shape those specs ask for.
    #[tokio::test]
    async fn ast_review_counts_a_runtime_loader_string_as_wired() {
        let dir = std::env::temp_dir().join(format!("goose_ast_uvicorn_{}", std::process::id()));
        let pkg = dir.join("app");
        std::fs::create_dir_all(&pkg).unwrap();
        std::fs::write(pkg.join("__init__.py"), "").unwrap();
        // The real shape: the entry NAMES its app, it never imports it.
        std::fs::write(
            pkg.join("__main__.py"),
            "import uvicorn\nuvicorn.run(\"app.api:app\", host=\"127.0.0.1\", port=8000)\n",
        )
        .unwrap();
        std::fs::write(
            pkg.join("api.py"),
            "CONST = 1\ndef make():\n    return CONST\n",
        )
        .unwrap();
        // ...and a module NOTHING names, anywhere. The fix must not blind the check.
        std::fs::write(pkg.join("orphan.py"), "x = 1\n").unwrap();
        let planned: Vec<String> = [
            "app/__init__.py",
            "app/__main__.py",
            "app/api.py",
            "app/orphan.py",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        let res = run_ast_review(&dir, &app_scope_py(&dir, &planned)).await;
        let _ = std::fs::remove_dir_all(&dir);
        if !res.ran {
            return; // python3 not available
        }
        let joined = res.findings.join("\n");
        assert!(
            !joined.contains("'app.api'"),
            "a module named by a uvicorn/gunicorn \"pkg.mod:attr\" string is WIRED — it is the entry \
             point: {joined}"
        );
        assert!(
            !res.demote_eligible.contains(&"app.api".to_string()),
            "and it must never be demote-eligible: {:?}",
            res.demote_eligible
        );
        assert!(
            joined.contains("app.orphan"),
            "a module nothing names must STILL be flagged — the fix must not blind the check: {joined}"
        );
    }

    #[test]
    fn web_vocab_note_fires_for_frontend_owners_only() {
        // css/html owners always get the vocabulary obligation.
        assert!(web_vocab_note(&["web/styles.css".into()], true).contains("ONE vocabulary"));
        assert!(web_vocab_note(&["web/index.html".into()], true).contains("hidden by default"));
        // js only under a frontend-shaped path — a Node backend shares no styling vocabulary.
        assert!(web_vocab_note(&["server/api.js".into()], true).is_empty());
        assert!(web_vocab_note(&["web/app.js".into()], true).contains("ONE vocabulary"));
        // python-only tasks and the OFF gate stay byte-identical.
        assert!(web_vocab_note(&["pkg/store.py".into()], true).is_empty());
        assert!(web_vocab_note(&["web/styles.css".into()], false).is_empty());
    }

    #[test]
    fn multifile_stub_note_fires_only_for_multifile_non_entry() {
        // Multi-file non-entry module (the plan-shopping case) -> stub-first note; entry, single-file, and
        // disabled -> empty.
        let note = multifile_stub_note(
            &["recipes/plan.py".into(), "recipes/shopping.py".into()],
            true,
        );
        assert!(note.contains("STUB-FIRST") && note.contains("COMPILING STUB"));
        // A file set that includes the entry is covered by skeleton_note -> empty here.
        assert!(multifile_stub_note(&["pkg/cli.py".into(), "pkg/util.py".into()], true).is_empty());
        assert!(
            multifile_stub_note(&["pkg/__main__.py".into(), "pkg/x.py".into()], true).is_empty()
        );
        // Single-file -> empty (skeleton-first was a wash on simple single-file tasks).
        assert!(multifile_stub_note(&["pkg/only.py".into()], true).is_empty());
        // Disabled -> empty.
        assert!(multifile_stub_note(&["a.py".into(), "b.py".into()], false).is_empty());
    }

    #[test]
    fn cli_contract_note_fires_only_for_entry_when_enabled() {
        // Entry file + enabled -> a non-empty CLI-structure contract mentioning nested/global/units.
        let note = cli_contract_note(true, true);
        assert!(note.contains("CLI STRUCTURE CONTRACT"));
        assert!(note.contains("NESTED") && note.contains("GLOBAL"));
        // POSITIONAL-vs-flag + no-rename rules (UNIQ16 drifted positionals to flags + renamed --from/--to).
        assert!(note.contains("POSITIONAL") && note.contains("do NOT rename"));
        // Keyword-subcommand-name rule (UNIQ26 registered `import_` for the spec's `import` -> `store import` failed).
        assert!(note.contains("reserved word") && note.contains("add_parser(\"import\")"));
        // Disabled, or no entry file among the owned set -> empty (no-op, byte-identical default-off path).
        assert!(cli_contract_note(true, false).is_empty());
        assert!(cli_contract_note(false, true).is_empty());
    }

    #[test]
    fn ask_replan_defaults_off_and_opts_in() {
        // Default (unset) now REUSES the plan (skip the re-plan, per the UNIQ12/UNIQ12b A/B); opt INTO the
        // re-plan only with an explicit on-value.
        assert!(
            !ask_replan_resolved(None, None),
            "unset (env+config None) defaults OFF (reuse plan / skip re-plan)"
        );
        assert!(ask_replan_enabled(Some("1".into())));
        assert!(ask_replan_enabled(Some("on".into())));
        assert!(ask_replan_enabled(Some("true".into())));
        assert!(ask_replan_enabled(Some("YES".into())), "case-insensitive");
        assert!(!ask_replan_enabled(Some("0".into())));
        assert!(!ask_replan_enabled(Some("off".into())));
        assert!(
            !ask_replan_enabled(Some("anything".into())),
            "unknown values skip — only explicit on-values re-plan"
        );
        assert!(!ask_replan_enabled(Some(" no ".into())));
    }

    #[test]
    fn answers_win_floor_defaults_on_and_opts_out() {
        // #129: the guard ships ON. Unset env+config resolves TRUE (unlike ask_replan, which defaults off) so a
        // config that omits the field — every user who never toggled it — gets the foot-gun fix.
        assert!(
            answers_win_floor_resolved(None, None),
            "unset (env+config None) defaults ON — the #129 fix reaches users who never touched it"
        );
        assert!(
            answers_win_floor_resolved(None, Some(true)),
            "explicit config true stays on"
        );
        // Explicit opt-OUT restores the legacy re-plan (for A/B / rollback), env winning over config.
        assert!(!answers_win_floor_resolved(Some("0".into()), None));
        assert!(!answers_win_floor_resolved(Some("off".into()), Some(true)));
        assert!(!answers_win_floor_resolved(None, Some(false)));
        // Explicit on-values, case-insensitive, env beats a config false.
        assert!(answers_win_floor_resolved(Some("1".into()), Some(false)));
        assert!(answers_win_floor_resolved(Some("YES".into()), None));
        // An unknown env value is NOT an on-value; env-present means env decides, so it is off.
        assert!(!answers_win_floor_resolved(
            Some("anything".into()),
            Some(true)
        ));
    }

    #[test]
    fn stream_decode_retry_defaults_on_and_opts_out() {
        // #121 ships ON: unset env+config resolves TRUE so the false-green fix reaches every user, including
        // desktop configs that omit the field.
        assert!(
            stream_decode_retry_resolved(None, None),
            "unset defaults ON — the #121 false-green fix reaches users who never toggled it"
        );
        assert!(stream_decode_retry_resolved(None, Some(true)));
        // Explicit opt-OUT restores the legacy accept-as-done path (for the A/B), env winning over config.
        assert!(!stream_decode_retry_resolved(Some("0".into()), None));
        assert!(!stream_decode_retry_resolved(
            Some("off".into()),
            Some(true)
        ));
        assert!(!stream_decode_retry_resolved(None, Some(false)));
        assert!(stream_decode_retry_resolved(Some("1".into()), Some(false)));
        assert!(stream_decode_retry_resolved(Some("YES".into()), None));
    }

    #[test]
    fn stream_decode_interrupt_predicate_is_deterministic() {
        // BOTH halves required: the marker AND the exact trailing resend sentence (the agent loop appends it
        // as the last chunk after a NetworkError, then breaks).
        let hit = "Network error: Stream decode error: error decoding response body\n\nPlease resend your message to try again.";
        assert!(is_stream_decode_interrupt(hit));
        // Trailing whitespace is tolerated (trim_end before the suffix check).
        assert!(is_stream_decode_interrupt(&format!("{hit}\n  ")));
        // Marker present but NOT the trailing sentence (e.g. a genuine verdict that merely quotes the phrase)
        // -> not an interrupt; the run's real output must be preserved.
        assert!(!is_stream_decode_interrupt(
            "The app logs a 'Stream decode error' when the socket closes; VERDICT: PASS."
        ));
        // The resend sentence WITHOUT the decode marker (some other transient) -> not this predicate.
        assert!(!is_stream_decode_interrupt(
            "Some other failure.\n\nPlease resend your message to try again."
        ));
        // A normal, clean verdict is never a false positive.
        assert!(!is_stream_decode_interrupt(
            "VERDICT: PASS — all endpoints return 200 and balances sum to zero."
        ));
    }

    #[test]
    fn straggler_stop_defaults_off_and_opts_in() {
        // A timing change, not a correctness fix — ships OFF (byte-identical await-all) until validated.
        assert!(!straggler_stop_resolved(None, None));
        assert!(!straggler_stop_resolved(None, Some(false)));
        assert!(straggler_stop_resolved(None, Some(true)));
        assert!(straggler_stop_resolved(Some("1".into()), None));
        assert!(
            straggler_stop_resolved(Some("on".into()), Some(false)),
            "env beats config"
        );
        assert!(!straggler_stop_resolved(Some("0".into()), Some(true)));
        assert!(!straggler_stop_resolved(
            Some("nonsense".into()),
            Some(true)
        ));
    }

    #[test]
    fn straggler_grace_resolves_env_then_config_then_derive() {
        // G1: no explicit value means DERIVE per round (None), no baked constant — an explicit
        // env or config value stays a fixed override exactly as before.
        assert_eq!(straggler_grace_resolved(None, None), None);
        assert_eq!(straggler_grace_resolved(None, Some(30)), Some(30));
        assert_eq!(
            straggler_grace_resolved(Some("90".into()), Some(30)),
            Some(90)
        );
        // Unparseable env falls through to config, then to derive.
        assert_eq!(
            straggler_grace_resolved(Some("abc".into()), Some(30)),
            Some(30)
        );
        assert_eq!(straggler_grace_resolved(Some("abc".into()), None), None);
    }

    #[test]
    fn straggler_grace_arms_only_for_the_lone_last_draft() {
        // n < 3: no lone straggler concept — never arm (both drafts are needed for agreement).
        assert!(!should_arm_straggler_grace(1, 1));
        assert!(!should_arm_straggler_grace(2, 2));
        // n == 3: Mihai's "2 of 3" — arm exactly when 2 valid are in and 1 is still out.
        assert!(
            !should_arm_straggler_grace(3, 1),
            "one valid draft is not a quorum"
        );
        assert!(
            should_arm_straggler_grace(3, 2),
            "2 of 3 valid -> race the 3rd"
        );
        assert!(should_arm_straggler_grace(3, 3));
        // n == 6: conservative — only ever race the single last draft (5 of 6), never sacrifice diversity
        // while more than one draft is still outstanding.
        assert!(!should_arm_straggler_grace(6, 2));
        assert!(!should_arm_straggler_grace(6, 4));
        assert!(
            should_arm_straggler_grace(6, 5),
            "5 of 6 valid -> race the 6th"
        );
    }

    // The async abort/grace path — the pure predicate test above did NOT exercise this, and that is exactly
    // where a panic hid (a huge inert-timer duration overflowed std::Instant). Real (short) durations, no
    // test-util needed; big margins keep them deterministic.
    #[tokio::test]
    async fn straggler_stop_aborts_lone_lagging_draft() {
        let mut js = tokio::task::JoinSet::new();
        js.spawn(async { Some("A".to_string()) });
        js.spawn(async { Some("B".to_string()) });
        js.spawn(async {
            tokio::time::sleep(std::time::Duration::from_secs(30)).await;
            Some("C".to_string())
        });
        // Two valid drafts land instantly and arm a 1s grace; the 30s straggler is aborted ~1s later.
        let (c, dead, stopped, _) = collect_drafts_with_straggler_stop(
            js,
            3,
            StragglerGrace::Fixed(1),
            |_| true,
            |_: &[String]| true,
        )
        .await;
        assert_eq!(stopped, 1, "the lone straggler is stopped");
        assert_eq!(dead, 0);
        assert_eq!(c.len(), 2, "quorum of 2 kept; straggler dropped");
        assert!(c.contains(&"A".to_string()) && c.contains(&"B".to_string()));
        assert!(!c.contains(&"C".to_string()));
    }

    #[tokio::test]
    async fn straggler_stop_keeps_all_when_none_lags() {
        let mut js = tokio::task::JoinSet::new();
        for k in ["A", "B", "C"] {
            let s = k.to_string();
            js.spawn(async move { Some(s) });
        }
        let (c, dead, stopped, _) = collect_drafts_with_straggler_stop(
            js,
            3,
            StragglerGrace::Fixed(1),
            |_| true,
            |_: &[String]| true,
        )
        .await;
        assert_eq!(stopped, 0);
        assert_eq!(dead, 0);
        assert_eq!(c.len(), 3);
    }

    #[tokio::test]
    async fn straggler_that_finishes_within_grace_is_kept() {
        let mut js = tokio::task::JoinSet::new();
        js.spawn(async { Some("A".to_string()) });
        js.spawn(async { Some("B".to_string()) });
        js.spawn(async {
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
            Some("C".to_string())
        });
        // grace 10s >> the 50ms straggler, so it lands inside the window and is kept (all 3 collected).
        let (c, dead, stopped, _) = collect_drafts_with_straggler_stop(
            js,
            3,
            StragglerGrace::Fixed(10),
            |_| true,
            |_: &[String]| true,
        )
        .await;
        assert_eq!(stopped, 0, "straggler finished within grace");
        assert_eq!(dead, 0);
        assert_eq!(c.len(), 3);
    }

    #[tokio::test]
    async fn straggler_invalid_drafts_do_not_arm_the_grace() {
        let mut js = tokio::task::JoinSet::new();
        js.spawn(async { Some("VALID".to_string()) });
        js.spawn(async { Some("BAD".to_string()) });
        js.spawn(async {
            tokio::time::sleep(std::time::Duration::from_millis(80)).await;
            Some("VALID2".to_string())
        });
        // Only ONE valid draft lands until the 3rd resolves, so the 2-valid quorum never forms before the
        // last draft — the grace never arms and nothing is stopped, even though a draft was slower.
        let (c, dead, stopped, _) = collect_drafts_with_straggler_stop(
            js,
            3,
            StragglerGrace::Fixed(1),
            |s| s.starts_with("VALID"),
            |_: &[String]| true,
        )
        .await;
        assert_eq!(stopped, 0, "one valid draft is not a quorum -> never armed");
        assert_eq!(dead, 0);
        assert_eq!(c.len(), 3);
    }

    #[tokio::test]
    async fn straggler_quorum_below_floor_defers_the_abort() {
        // B5 both directions. Direction 1: the in-hand pair does NOT decide (quorum_decides false),
        // so the count condition holding must NOT arm the grace — the slow third draft is awaited in
        // full and `deferred` reports why.
        let mut js = tokio::task::JoinSet::new();
        js.spawn(async { Some("A".to_string()) });
        js.spawn(async { Some("B".to_string()) });
        js.spawn(async {
            tokio::time::sleep(std::time::Duration::from_millis(80)).await;
            Some("C".to_string())
        });
        let (c, dead, stopped, deferred) = collect_drafts_with_straggler_stop(
            js,
            3,
            StragglerGrace::Fixed(1),
            |_| true,
            |_: &[String]| false,
        )
        .await;
        assert_eq!(
            stopped, 0,
            "below-floor quorum must never abort the last draft"
        );
        assert!(deferred, "the deferral must be observable");
        assert_eq!(dead, 0);
        assert_eq!(c.len(), 3, "the full pool is collected");

        // Direction 2: the pair DOES decide -> today's behavior exactly (abort after grace).
        let mut js = tokio::task::JoinSet::new();
        js.spawn(async { Some("A".to_string()) });
        js.spawn(async { Some("B".to_string()) });
        js.spawn(async {
            tokio::time::sleep(std::time::Duration::from_secs(30)).await;
            Some("C".to_string())
        });
        let (c, _dead, stopped, deferred) = collect_drafts_with_straggler_stop(
            js,
            3,
            StragglerGrace::Fixed(1),
            |_| true,
            |_: &[String]| true,
        )
        .await;
        assert_eq!(stopped, 1, "deciding quorum keeps the pre-B5 abort");
        assert!(!deferred);
        assert_eq!(c.len(), 2);
    }

    #[test]
    fn the_derived_grace_scales_with_the_round_and_respects_the_backstop() {
        // G1 both directions. A slow round (quorum at 200s, timeout 480) earns a patient grace…
        assert_eq!(derived_straggler_grace(200, 480), 100);
        // …a fast round gets the floor, not a constant sized for a slower fleet…
        assert_eq!(derived_straggler_grace(12, 480), 10);
        // …and near the hard backstop the grace can never outrun draft_timeout.
        assert_eq!(derived_straggler_grace(470, 480), 10);
        assert_eq!(derived_straggler_grace(400, 480), 80);
    }

    #[test]
    fn score_skeleton_does_not_rewrite_real_dependencies_for_width() {
        let wide = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["a.py"]},
                {"id":"b","depends_on":[],"files":["b.py"]},
                {"id":"c","depends_on":[],"files":["c.py"]},
                {"id":"integrate-verify","depends_on":["a","b","c"],"files":["t.py"]}
            ]}"#,
        )
        .unwrap();
        let deep = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["a.py"]},
                {"id":"b","depends_on":["a"],"files":["b.py"]},
                {"id":"c","depends_on":["b"],"files":["c.py"]},
                {"id":"integrate-verify","depends_on":["a","b","c"],"files":["t.py"]}
            ]}"#,
        )
        .unwrap();
        let sw = score_skeleton(&wide).unwrap();
        let sd = score_skeleton(&deep).unwrap();
        assert_eq!(
            sw, sd,
            "dependency depth is job truth, not a structural quality verdict"
        );
        // a dep on an unknown task is not a valid DAG -> None (so it can never be picked).
        let bad = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[{"id":"x","depends_on":["nope"],"files":["x.py"]}]}"#,
        )
        .unwrap();
        assert!(score_skeleton(&bad).is_none());
    }

    #[test]
    fn converge_role_normalizes_surface_variety() {
        // Two drafts with the SAME roles (types, parser, cli) but different dirs/case/entry-name, plus the
        // injected sink + a test module. Role-normalized agreement should read near-perfect; the raw metric
        // reads them as heavily divergent (different file strings + task counts).
        let d1 = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"types","depends_on":[],"files":["pkg/types.py"]},
                {"id":"parser","depends_on":["types"],"files":["pkg/parser.py"]},
                {"id":"cli","depends_on":["parser"],"files":["pkg/__main__.py"]},
                {"id":"tests","depends_on":["parser"],"files":["tests/test_parser.py"]},
                {"id":"integrate-verify","depends_on":["cli"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let d2 = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"shared-types","depends_on":[],"files":["src/Types.py"]},
                {"id":"the-parser","depends_on":["shared-types"],"files":["src/Parser.py"]},
                {"id":"entry","depends_on":["the-parser"],"files":["src/cli.py"]},
                {"id":"integrate-verify","depends_on":["entry"],"files":[]}
            ]}"#,
        )
        .unwrap();
        let cands = vec![d1, d2];
        let (raw, _) = plan_agreement(&cands, false);
        let (norm, reason) = plan_agreement(&cands, true);
        assert!(norm > raw, "role-normalized {norm} should beat raw {raw}");
        assert!(
            norm >= 85,
            "same 3 roles -> near-perfect agreement, got {norm}"
        );
        assert!(reason.contains("role-normalized"));
    }

    #[test]
    fn canonical_role_folds_entry_but_keeps_distinct_stages() {
        // Entry-point synonyms fold to one role.
        for f in [
            "__main__.py",
            "app.py",
            "src/main.py",
            "cli.py",
            "run.py",
            "entry.py",
        ] {
            assert_eq!(canonical_role(f), "cli", "{f} should be the cli role");
        }
        // Distinct compilation stages must NOT merge (conservative — no over-counting).
        assert_eq!(canonical_role("src/lexer.py"), "lexer");
        assert_eq!(canonical_role("Parser.PY"), "parser");
        assert_eq!(canonical_role("ast.rs"), "ast");
        assert_ne!(canonical_role("lexer.py"), canonical_role("parser.py"));
        // A genuinely different decomposition (split lexer+parser vs one combined parser) stays < perfect.
        let split = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"lexer","depends_on":[],"files":["lexer.py"]},
                {"id":"parser","depends_on":["lexer"],"files":["parser.py"]},
                {"id":"cli","depends_on":["parser"],"files":["cli.py"]}
            ]}"#,
        )
        .unwrap();
        let combined = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"parser","depends_on":[],"files":["parser.py"]},
                {"id":"cli","depends_on":["parser"],"files":["cli.py"]}
            ]}"#,
        )
        .unwrap();
        let (norm, _) = plan_agreement(&[split, combined], true);
        assert!(
            norm < 100,
            "genuinely different decompositions must not read perfect: {norm}"
        );
    }

    #[test]
    fn plan_agreement_default_path_unchanged() {
        let d = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["a.py"]},
                {"id":"b","depends_on":["a"],"files":["b.py"]}
            ]}"#,
        )
        .unwrap();
        // Two identical drafts, raw path: spread 0 (40) + jaccard 1 (45) + indep 0 (15) = 100, no marker.
        let (c, r) = plan_agreement(&[d.clone(), d.clone()], false);
        assert_eq!(c, 100);
        assert!(!r.contains("role-normalized"));
        // Single draft -> inert neutral 60 on both paths.
        assert_eq!(plan_agreement(std::slice::from_ref(&d), false).0, 60);
        assert_eq!(plan_agreement(std::slice::from_ref(&d), true).0, 60);
    }

    #[test]
    fn best_subset_agreement_drops_the_outlier() {
        // Three tight drafts (same 3 roles) + one wild outlier (5 modules, disjoint files). The full-set
        // measure is dragged down by the outlier; the best 3-of-4 consensus recovers the tight cluster.
        let tight = |seed: &str| {
            goose_swarm::specs_from_plan_json(&format!(
                r#"{{"subtasks":[
                    {{"id":"types{seed}","depends_on":[],"files":["types.py"]}},
                    {{"id":"core{seed}","depends_on":["types{seed}"],"files":["core.py"]}},
                    {{"id":"cli{seed}","depends_on":["core{seed}"],"files":["cli.py"]}}
                ]}}"#
            ))
            .unwrap()
        };
        let outlier = goose_swarm::specs_from_plan_json(
            r#"{"subtasks":[
                {"id":"a","depends_on":[],"files":["alpha.py"]},
                {"id":"b","depends_on":[],"files":["beta.py"]},
                {"id":"c","depends_on":["a"],"files":["gamma.py"]},
                {"id":"d","depends_on":["b"],"files":["delta.py"]},
                {"id":"e","depends_on":["c","d"],"files":["epsilon.py"]}
            ]}"#,
        )
        .unwrap();
        let pool = vec![tight("1"), tight("2"), tight("3"), outlier];
        let (full, _) = plan_agreement(&pool, true);
        let (subset, reason) = best_subset_agreement(&pool, true, 3);
        assert!(
            subset > full,
            "consensus cluster {subset} should beat the outlier-dragged full set {full}"
        );
        assert!(subset >= 85, "the 3 tight drafts agree on roles: {subset}");
        assert!(reason.contains("consensus 3 of 4"));
        // Inert when the pool has not grown past k: identical to the full-set measure (byte-identical default).
        let two = vec![tight("1"), tight("2")];
        assert_eq!(
            best_subset_agreement(&two, true, 3),
            plan_agreement(&two, true)
        );
    }

    /// THE RESCORE MUST NEVER FLATTER A RUN.
    ///
    /// When the user answers, spec-clarity is re-scored deterministically with the SAME pure function the
    /// first score used — over (open - ANSWERED), never over 0. `ask_max_q` truncates the question list
    /// with a `.take()`, so a run with 8 open decisions that asked 5 still has 3 the user never saw and
    /// goose will guess. Snapping to zero there would raise a number the run did not earn — precisely the
    /// failure the low score exists to prevent (before it, research INVENTED 5 decisions and reported 96).
    #[test]
    fn rescore_credits_only_what_was_actually_answered() {
        // The measured case: 5 open, all 5 asked and answered -> the spec really is pinned.
        assert_eq!(
            spec_clarity_score(true, 5),
            30,
            "the 30 Mihai saw: 100-16*5=20, floored to 30"
        );
        assert_eq!(
            spec_clarity_score(true, 5usize.saturating_sub(5)),
            100,
            "all answered => pinned"
        );

        // The trap: 8 open but the cap asked only 5. THREE are still guesses.
        let still_open = 8usize.saturating_sub(5);
        assert_eq!(still_open, 3);
        let rescored = spec_clarity_score(true, still_open);
        assert_eq!(
            rescored, 52,
            "credit 5 answers, keep charging for the 3 nobody asked about"
        );
        assert!(
            rescored < 100,
            "a truncated ask must NEVER read as a pinned spec"
        );

        // Monotonic: answering more can only raise it, and it can never exceed a pinned spec.
        assert!(spec_clarity_score(true, 3) > spec_clarity_score(true, 5));
        assert!(spec_clarity_score(true, 0) >= spec_clarity_score(true, 1));

        // final = min(agreement, clarity) — the SAME expression as the first score. Agreement is never
        // touched by the rescore: it describes the DAG that actually ships, which IS the pre-answer plan.
        let agreement = 88u8;
        assert_eq!(
            agreement.min(spec_clarity_score(true, 5)),
            30,
            "before: the spec binds"
        );
        assert_eq!(
            agreement.min(spec_clarity_score(true, 0)),
            88,
            "after: agreement binds, not 100"
        );
    }

    #[test]
    fn spec_contract_parsing() {
        let spec =
            "It runs as `python3 -m quorum` which starts the server. REST: POST /api/polls; \
                    GET /api/polls/<id>; GET /api/polls/<id>/results; GET /api/polls (list).";
        assert_eq!(spec_python_entry(spec).as_deref(), Some("quorum"));
        let gets = spec_get_endpoints(spec);
        // The concrete list endpoint is kept; the param'd routes are excluded (no false base-path finding).
        assert_eq!(gets, vec!["/api/polls".to_string()]);
        assert!(!gets.iter().any(|g| g.contains("id") || g.contains('<')));
        // No advertised python entry -> None (a Swift/TS spec no-ops the whole check).
        assert!(spec_python_entry("Build a Swift CLI note-taker").is_none());
        // Port: default 8000, else the advertised one.
        assert_eq!(spec_port("no port mentioned"), 8000);
        assert_eq!(spec_port("the server listens on 127.0.0.1:9100"), 9100);
        // A pure-CLI spec with no GET endpoints yields nothing to curl.
        assert!(spec_get_endpoints("python3 -m tool add x").is_empty());
    }

    #[test]
    fn clarity_fail_closed_reasons() {
        // FAIL-CLOSED (learned nothing → ask): timeout / agent_error / no_final_output, incl. the ": detail" tail.
        assert!(clarity_reason_is_fail_closed("timeout"));
        assert!(clarity_reason_is_fail_closed(
            "agent_error: connection refused"
        ));
        assert!(clarity_reason_is_fail_closed("no_final_output"));
        // FAIL-OPEN (the model DID answer, the JSON just didn't fit): unparseable stays out → no false-ask storm.
        assert!(!clarity_reason_is_fail_closed("unparseable: {truncated"));
        // The clamp value is below the default ask floor (documented on the const) AND is not a producible
        // spec_clarity_score, so a 20 in the breakdown is an unambiguous fail-closed sentinel — checked at
        // runtime against every score the function can emit (a const-vs-const assert is a clippy error).
        for n in 0..=9 {
            assert_ne!(spec_clarity_score(true, n), CLARITY_FAILCLOSED);
            assert_ne!(spec_clarity_score(false, n), CLARITY_FAILCLOSED);
        }
    }

    #[test]
    fn clarity_failure_is_reset_for_every_probe() {
        let failure = Mutex::new(Some("timeout".to_string()));
        reset_clarity_failure(&failure);
        assert!(failure.lock().unwrap().is_none());
        *failure.lock().unwrap() = Some("no_final_output".to_string());
        reset_clarity_failure(&failure);
        assert!(failure.lock().unwrap().is_none());
    }

    // ---- #136 DELEGATED DECISIONS ----------------------------------------------------------------
    // The real spec that caused the bug, trimmed to the shapes that matter.
    const LOGFOLD_SPEC: &str = "\
Build `logfold` — a log template miner, in Go, stdlib only.\n\
\n\
## The core\n\
Mask first, then tokenize, then route by a fixed-depth tree. Determinism is required.\n\
\n\
## Calls I'm leaving to you\n\
- **Placeholder vocabulary — typed or flat.** Whether a masked slot renders as a single `<*>` everywhere, or\n\
  keeps its type (`<NUM>`, `<IP>`, `<UUID>`). Typed reads better and diffs more precisely but grows the\n\
  masker surface. Your call, but be consistent between the mask stage and the tree-generalization stage.\n\
- **Template identity across runs.** How a template gets a stable id used by `diff` to match baseline to new\n\
  — hash of the token sequence? This decision is the whole ballgame; make it and defend it in a comment.\n\
";

    #[test]
    fn delegated_decisions_do_not_block_but_a_silent_spec_still_asks() {
        // A: the spec DELEGATES -> recorded, never asked. This is the measured mtp-base case.
        let decisions = vec![
            "Placeholder vocabulary: typed placeholders (<NUM>, <IP>, <UUID>) vs a flat wildcard everywhere. \
             Typed gives better diff precision but grows the masker surface."
                .to_string(),
            "Template identity across runs for diff matching: how a template gets a stable id used by diff to \
             match baseline to new, and what counts as the same template."
                .to_string(),
        ];
        let (blocking, delegated) = partition_delegated_decisions(&decisions, LOGFOLD_SPEC);
        assert_eq!(
            delegated.len(),
            2,
            "both are delegated by the spec's own section"
        );
        assert!(blocking.is_empty(), "nothing should block: {blocking:?}");
        // and the confidence recovers, which is the whole point
        assert_eq!(spec_clarity_score(true, decisions.len()), 68);
        assert_eq!(spec_clarity_score(true, blocking.len()), 100);

        // B: a decision the spec NEVER MENTIONS must still block. The gate must not become a blanket silencer.
        let unmentioned = vec![
            "Which authentication provider should the billing portal use for single sign-on"
                .to_string(),
        ];
        let (blocking, delegated) = partition_delegated_decisions(&unmentioned, LOGFOLD_SPEC);
        assert_eq!(blocking.len(), 1, "an unmentioned decision MUST still ask");
        assert!(delegated.is_empty());
    }

    #[test]
    fn a_reservation_phrase_outranks_delegation_in_the_same_region() {
        // C: "do NOT guess — ask me" must win, even sitting inside a delegating section, or one loose
        // "your call" would silence the questions the author most wanted asked.
        let spec = "## Calls I'm leaving to you\n\
                    Styling and output formatting are your call.\n\
                    The storage backend and retention window are NOT: do not guess them, ask me.\n";
        let d = vec![
            "storage backend and retention window for the archived records, no sensible default exists"
                .to_string(),
        ];
        let (blocking, delegated) = partition_delegated_decisions(&d, spec);
        assert_eq!(blocking.len(), 1, "a reserved decision must still block");
        assert!(delegated.is_empty());
    }

    #[test]
    fn no_delegation_section_is_a_total_passthrough() {
        // F: with nothing delegating, the partition must return the input unchanged — this is what makes the
        // lever byte-identical on the specs that do not use delegation language at all.
        let spec = "Build a CLI that converts markdown to HTML. Support tables and footnotes.";
        let d = vec![
            "whether footnote backlinks render inline or collected at the document foot"
                .to_string(),
            "which markdown flavour to accept for tables".to_string(),
        ];
        let (blocking, delegated) = partition_delegated_decisions(&d, spec);
        assert_eq!(blocking, d, "unchanged");
        assert!(delegated.is_empty());
    }

    #[test]
    fn model_prose_appended_to_the_prompt_can_never_manufacture_a_delegation() {
        // THE EXPOSURE, pinned. opts.prompt is appended to by MODEL output at :19660 (research findings) and
        // :19799 (clarify Q&A), and a retarget round re-plans with the enlarged prompt. Research output
        // routinely contains "either is defensible" -- which is one of DELEGATION_MARKERS verbatim. If the
        // partition read the live prompt, the model would be able to silence a question the user needed to
        // answer, which is the exact direction this gate must never fail in.
        let operator_spec =
            "Build a CLI that syncs two folders. It must never delete without a prompt.";
        let model_appended = "\n\n## RESEARCH FINDINGS\n\
             - Conflict resolution: either is defensible, your call whether last-write-wins or newest-mtime \
               wins; pick something sensible and defend it in a comment.\n";
        let polluted = format!("{operator_spec}{model_appended}");
        let decision = vec![
            "Conflict resolution strategy when both sides changed: last-write-wins versus newest-mtime wins, \
             no sensible default exists and guessing wrong silently loses a user's edits"
                .to_string(),
        ];

        // Parsed from the POLLUTED prompt the model would have silenced it...
        let (blocking_bad, delegated_bad) = partition_delegated_decisions(&decision, &polluted);
        assert!(
            !delegated_bad.is_empty() || blocking_bad.len() == 1,
            "sanity: the polluted text is the risky input"
        );

        // ...but parsed from the FROZEN operator spec, which says nothing about delegation, it MUST still ask.
        let (blocking, delegated) = partition_delegated_decisions(&decision, operator_spec);
        assert_eq!(
            blocking.len(),
            1,
            "the operator never delegated this — it must still block"
        );
        assert!(
            delegated.is_empty(),
            "model prose must never create a delegation: {delegated:?}"
        );
    }

    #[test]
    fn a_thin_decision_is_never_assumed_delegated() {
        // Guard the conservative bias: too few significant tokens to match on => keep asking. A false
        // "delegated" silences a real question, which is strictly worse than an unnecessary ask.
        let regions = delegation_regions(LOGFOLD_SPEC);
        assert!(!regions.is_empty());
        assert!(!decision_is_delegated("typed or flat", &regions));
        assert!(!decision_is_delegated("the id", &regions));
    }

    #[test]
    fn delegation_lever_defaults_off_and_env_overrides_config() {
        // Default OFF, and the resolver precedence matches every other lever (env beats config beats default).
        assert!(!delegated_decisions_ok(None));
        assert!(delegated_decisions_ok(Some(true)));
        assert!(!delegated_decisions_ok(Some(false)));
    }

    #[test]
    fn spec_clarity_score_is_continuous_not_a_constant() {
        // Defined product: continuous, decreasing with each material open decision (NOT the old 100/72/50/30
        // buckets); floored at 30 so a very-open-but-defined spec still reads "low, ask".
        assert_eq!(spec_clarity_score(true, 0), 100);
        assert_eq!(spec_clarity_score(true, 1), 84);
        assert_eq!(spec_clarity_score(true, 2), 68);
        assert_eq!(spec_clarity_score(true, 3), 52);
        assert_eq!(spec_clarity_score(true, 9), 30); // floored, count clamped
                                                     // Undefined product: always LOW (<= 30 so it asks regardless of agreement) but VARIES with how many
                                                     // axes are open — so vague specs no longer all snap to a flat 20.
        assert_eq!(spec_clarity_score(false, 0), 30);
        assert_eq!(spec_clarity_score(false, 1), 24);
        assert_eq!(spec_clarity_score(false, 2), 18);
        assert_eq!(spec_clarity_score(false, 9), 8); // floored
                                                     // Ask boundary vs a ~70 floor preserved: defined+0/1 proceed, defined+2 asks, undefined always asks.
        assert!(spec_clarity_score(true, 1) >= 70);
        assert!(spec_clarity_score(true, 2) < 70);
        assert!(spec_clarity_score(false, 0) < 70);
    }

    #[test]
    fn consensus_backbone_pins_only_the_strict_majority() {
        let draft = |ids: &[(&str, &str)]| {
            let subs: Vec<String> = ids
                .iter()
                .map(|(id, file)| format!(r#"{{"id":"{id}","depends_on":[],"files":["{file}"]}}"#))
                .collect();
            goose_swarm::specs_from_plan_json(&format!(r#"{{"subtasks":[{}]}}"#, subs.join(",")))
                .unwrap()
        };
        // 3 drafts: models+cli appear in 2/3; parser in 1/3; a per-module test task must NOT contribute a role.
        let d1 = draft(&[
            ("models", "models.py"),
            ("cli", "__main__.py"),
            ("t", "test_models.py"),
        ]);
        let d2 = draft(&[("models", "models.py"), ("entry", "cli.py")]);
        let d3 = draft(&[("parser", "parser.py"), ("main", "main.py")]);
        let bb = consensus_backbone(&[d1, d2, d3]);
        // cli (folded from __main__/cli/main/entry) in all 3, models in 2 → both pinned; parser (1/3) dropped.
        assert!(bb.contains(&"cli".to_string()), "cli is unanimous: {bb:?}");
        assert!(bb.contains(&"models".to_string()), "models is 2/3: {bb:?}");
        assert!(
            !bb.contains(&"parser".to_string()),
            "parser is only 1/3: {bb:?}"
        );
        assert!(
            !bb.iter().any(|r| r.contains("test")),
            "scaffolding excluded: {bb:?}"
        );
        // <2 drafts → no backbone.
        assert!(consensus_backbone(&[draft(&[("a", "a.py")])]).is_empty());
    }

    #[test]
    fn plan_covers_backbone_requires_every_role() {
        let plan = r#"{"subtasks":[
            {"id":"models","depends_on":[],"files":["pkg/models.py"]},
            {"id":"cli","depends_on":["models"],"files":["pkg/__main__.py"]}
        ]}"#;
        assert!(plan_covers_backbone(plan, &["cli".into(), "models".into()]));
        // A missing role → not covered (the lock was disobeyed).
        assert!(!plan_covers_backbone(
            plan,
            &["cli".into(), "models".into(), "parser".into()]
        ));
        // Invalid JSON → not covered (never adopt an unparseable round-2 plan).
        assert!(!plan_covers_backbone("not json", &["cli".into()]));
    }

