    #[test]
    fn corroborated_no_output_recurrence_retires_only_the_same_provider_request() {
        let request = ProviderRequestKey {
            ordinal: 0,
            provider_request_id: "incident-shaped-request".to_string(),
        };
        let first = ReasoningRecurrenceSnapshot {
            window_chars: 48,
            observed_windows: 31_000,
            repeated_windows: 9_500,
            repeat_share: 9_500.0 / 31_000.0,
            earlier_reasoning: "the earlier reasoning revisits the same unresolved choice"
                .to_string(),
        };
        let second = ReasoningRecurrenceSnapshot {
            window_chars: 48,
            observed_windows: 31_359,
            repeated_windows: 9_852,
            repeat_share: 9_852.0 / 31_359.0,
            earlier_reasoning: first.earlier_reasoning.clone(),
        };
        let mut gate = PreSchedulerRecurrenceFailoverGate::default();
        assert!(!gate.observe(
            Some(&request),
            &first,
            ProviderStreamProgressSnapshot::default(),
        ));
        assert!(gate.observe(
            Some(&request),
            &second,
            ProviderStreamProgressSnapshot::default(),
        ));

        let next_request = ProviderRequestKey {
            ordinal: 1,
            provider_request_id: "distinct-retry-request".to_string(),
        };
        assert!(!gate.observe(
            Some(&next_request),
            &second,
            ProviderStreamProgressSnapshot::default(),
        ));
        assert!(!gate.observe(
            Some(&next_request),
            &second,
            ProviderStreamProgressSnapshot {
                structured_output_chunks: 1,
                structured_output_bytes: 377,
                ..ProviderStreamProgressSnapshot::default()
            },
        ));
        assert_eq!(gate.confirmations(), 0);
    }

    #[test]
    fn recurrence_from_a_finished_turn_cannot_summon_for_the_next_turn() {
        let first = ProviderRequestKey {
            ordinal: 0,
            provider_request_id: "turn-one".to_string(),
        };
        let second = ProviderRequestKey {
            ordinal: 1,
            provider_request_id: "turn-two".to_string(),
        };
        let mut tracked = Some(first);
        let mut meter = ReasoningRecurrenceMeter::default();
        // Keep this beyond the meter's distant-evidence reach. The old 400-cycle fixture was only
        // 14,000 characters, so it could never satisfy the 20,000-character separation invariant.
        let repeated = "the same recurrent reasoning cycle ".repeat(900);
        meter.push(&repeated);
        let mut recent = repeated;
        let first_turn = meter.snapshot();
        assert!(
            recurrence_warrants_semantic_review(&first_turn),
            "first-turn fixture must contain distant recurrence evidence: {first_turn:?}"
        );

        bind_recurrence_to_provider_request(
            Some(second.clone()),
            &mut tracked,
            &mut meter,
            &mut recent,
        );

        assert_eq!(tracked, Some(second));
        assert!(recent.is_empty());
        assert!(!recurrence_warrants_semantic_review(&meter.snapshot()));
    }

