    #[test]
    fn rendered_capability_audit_prompt_is_evidence_first_and_file_scoped() {
        let capability = capability_task("cap-a", &["src/a.rs", "tests/a.rs"], &[]);
        let layout = format!(
            "{}{}",
            capability_audit_owner_body(),
            capability_repair_description(
                std::slice::from_ref(&capability),
                &capability.owned_files,
            )
        );
        let prompt = render_worker_system_prompt(WorkerSystemPromptParts {
            worker_directive: "Build and test Rust. ",
            fix_directive: "",
            lang_rules: "",
            file_write_rule: worker_file_write_rule(true),
            reading_rules: capability_audit_reading_rules(),
            stopping_rules: capability_audit_stopping_rules(),
            write_first_block: "",
            decisions_block: "",
            doc_facts_block: "",
            pitfalls_block: "",
            notes_block: "",
            pillars_block: "",
            layout_block: &layout,
            contracts_block: "",
            context_block: "",
        });
        for required in [
            "No defect is presumed",
            "no-edit result",
            "OWNED files only",
            "port 0",
            "whole-product ruler",
        ] {
            assert!(prompt.contains(required), "missing `{required}`: {prompt}");
        }
        let normalized = prompt.to_lowercase();
        for forbidden in [
            "proven defect",
            "third tool call",
            "you may edit any file",
            "shadow",
            "must have made an edit",
            "zero file modifications fails",
        ] {
            assert!(
                !normalized.contains(forbidden),
                "capability audit leaked forced-fix rule `{forbidden}`: {prompt}"
            );
        }
    }

    #[test]
    fn integration_owner_closes_capabilities_without_duplicating_requirement_ownership() {
        let opening = ResearchPillarOpening {
            requirements: vec![
                AuthoredRequirement {
                    id: "REQ-a".to_string(),
                    text: "Build A".to_string(),
                    critical: true,
                },
                AuthoredRequirement {
                    id: "REQ-b".to_string(),
                    text: "Build B".to_string(),
                    critical: true,
                },
            ],
            pillars: vec![
                ResearchPillar {
                    id: "a".to_string(),
                    title: "A".to_string(),
                    objective: "Build A".to_string(),
                    requirement_ids: vec!["REQ-a".to_string()],
                    dependencies: Vec::new(),
                    research_questions: vec!["What is A's interface?".to_string()],
                    acceptance_criteria: vec!["A passes".to_string()],
                    exclusions: vec!["B".to_string()],
                },
                ResearchPillar {
                    id: "b".to_string(),
                    title: "B".to_string(),
                    objective: "Build B".to_string(),
                    requirement_ids: vec!["REQ-b".to_string()],
                    dependencies: Vec::new(),
                    research_questions: vec!["What is B's interface?".to_string()],
                    acceptance_criteria: vec!["B passes".to_string()],
                    exclusions: vec!["A".to_string()],
                },
            ],
            integration_contract: IntegrationContract {
                owner: "workhorse".to_string(),
                integration_required: true,
                objective: "Hook A and B into one application".to_string(),
                interface_invariants: vec!["Use both public interfaces".to_string()],
                acceptance_criteria: vec!["The application starts".to_string()],
            },
        };
        let plan = serde_json::json!({"subtasks": [
            {"id":"a", "description":"A", "model":"local", "depends_on":[], "files":["a.rs"]},
            {"id":"b", "description":"B", "model":"mac", "depends_on":[], "files":["b.rs"]},
            {"id":"hook", "description":"Hook A and B", "model":"workhorse", "depends_on":["a","b"], "files":["main.rs"]}
        ]});
        let coverages = vec![
            CanonicalPlanTaskCoverageDraft {
                task_id: "a".to_string(),
                owns_requirement_ids: vec!["REQ-a".to_string()],
                applies_requirement_ids: Vec::new(),
                verifies_requirement_ids: Vec::new(),
                evidence_ids: Vec::new(),
            },
            CanonicalPlanTaskCoverageDraft {
                task_id: "b".to_string(),
                owns_requirement_ids: vec!["REQ-b".to_string()],
                applies_requirement_ids: Vec::new(),
                verifies_requirement_ids: Vec::new(),
                evidence_ids: Vec::new(),
            },
            CanonicalPlanTaskCoverageDraft {
                task_id: "hook".to_string(),
                owns_requirement_ids: Vec::new(),
                applies_requirement_ids: vec!["REQ-a".to_string(), "REQ-b".to_string()],
                verifies_requirement_ids: Vec::new(),
                evidence_ids: Vec::new(),
            },
        ];
        validate_pillar_integration_owner(&opening, &plan, &coverages).unwrap();

        let double_integration = serde_json::json!({"subtasks": [
            {"id":"a", "description":"A", "model":"local", "depends_on":[], "files":["a.rs"]},
            {"id":"b", "description":"B", "model":"mac", "depends_on":[], "files":["b.rs"]},
            {"id":"audit-hook", "description":"Second production hook", "model":"local", "depends_on":["a","b"], "files":["bridge.rs"]},
            {"id":"hook", "description":"Hook A and B", "model":"workhorse", "depends_on":["audit-hook"], "files":["main.rs"]}
        ]});
        let mut double_coverages = coverages.clone();
        double_coverages.push(CanonicalPlanTaskCoverageDraft {
            task_id: "audit-hook".to_string(),
            owns_requirement_ids: Vec::new(),
            applies_requirement_ids: Vec::new(),
            verifies_requirement_ids: vec!["REQ-a".to_string(), "REQ-b".to_string()],
            evidence_ids: Vec::new(),
        });
        let error =
            validate_pillar_integration_owner(&opening, &double_integration, &double_coverages)
                .unwrap_err()
                .to_string();
        assert!(
            error.contains("exactly one multi-pillar implementation task"),
            "{error}"
        );

        let mut disconnected = plan;
        disconnected["subtasks"][2]["depends_on"] = serde_json::json!(["a"]);
        assert!(
            validate_pillar_integration_owner(&opening, &disconnected, &coverages)
                .unwrap_err()
                .to_string()
                .contains("exactly one non-test terminal owner")
        );
    }

    #[test]
    fn pillar_task_compiler_requires_specific_structure_and_replaces_freeform_text() {
        let mut plan = serde_json::json!({
            "subtasks": [{
                "id": "build-core",
                "description": "vague",
                "difficulty": "hard",
                "model": "qwen",
                "depends_on": [],
                "files": ["src/core.rs"]
            }]
        });
        let mut incomplete = pillar_task_spec("build-core");
        incomplete.edge_cases.clear();
        assert!(
            compile_pillar_task_specs(&mut plan.clone(), vec![incomplete])
                .unwrap_err()
                .to_string()
                .contains("edge_cases")
        );

        compile_pillar_task_specs(&mut plan, vec![pillar_task_spec("build-core")]).unwrap();
        let description = plan["subtasks"][0]["description"].as_str().unwrap();
        for section in [
            "OBJECTIVE",
            "EXCLUSIVE MODULE BOUNDARY",
            "CONCRETE IMPLEMENTATION STEPS",
            "PRODUCER / CONSUMER INTERFACES",
            "EDGE CASES",
            "EXECUTABLE ACCEPTANCE EVIDENCE",
            "EXPLICIT EXCLUSIONS",
        ] {
            assert!(
                description.contains(section),
                "missing {section}: {description}"
            );
        }
        assert!(!description.contains("vague"));

        let mut mismatched_plan = serde_json::json!({
            "subtasks": [{
                "id": "build-core",
                "description": "preserve this semantic description on rejection",
                "model": "qwen",
                "depends_on": [],
                "files": ["src/core.rs"]
            }]
        });
        let mismatch = compile_pillar_task_specs(
            &mut mismatched_plan,
            vec![pillar_task_spec("different-task")],
        )
        .unwrap_err()
        .to_string();
        assert!(mismatch.contains("planner_correction[task_spec_alignment]"));
        assert!(mismatch.contains("missing task_specs [build-core]"));
        assert!(mismatch.contains("unknown task_specs [different-task]"));
        assert_eq!(
            mismatched_plan["subtasks"][0]["description"],
            "preserve this semantic description on rejection"
        );

        let mut connected_plan = serde_json::json!({"subtasks": [
            {"id":"producer", "description":"producer", "model":"qwen", "depends_on":[], "files":["src/producer.rs"]},
            {"id":"consumer", "description":"consumer", "model":"qwen", "depends_on":["producer"], "files":["src/consumer.rs"]}
        ]});
        let mut producer = pillar_task_spec("producer");
        producer.interfaces.clear();
        let consumer = pillar_task_spec("consumer");
        assert!(
            compile_pillar_task_specs(&mut connected_plan, vec![producer, consumer])
                .unwrap_err()
                .to_string()
                .contains("dependency edge")
        );
    }

    #[test]
    fn pillar_plan_missing_advertised_entry_is_a_focused_correction_not_a_mutation() {
        let opening = pillar_plan_test_opening(false);
        let raw = serde_json::json!({
            "task_coverage": [{
                "task_id": "build-core", "owns_requirement_ids": ["REQ-core"],
                "applies_requirement_ids": [], "verifies_requirement_ids": [], "evidence_ids": []
            }],
            "task_specs": [{
                "task_id": "build-core", "objective": "Implement core",
                "module_boundary": "Own only src/core.py",
                "concrete_steps": ["Implement core"], "interfaces": [],
                "edge_cases": ["Reject empty input"],
                "acceptance_evidence": ["python core test passes"],
                "exclusions": ["Do not invent boot files"]
            }],
            "uncertainty_routes": [],
            "canonical_plan": {"subtasks": [{
                "id": "build-core",
                "description": "model-authored core responsibility",
                "model": "qwen", "depends_on": [], "files": ["src/core.py"]
            }]}
        });
        let frozen_raw = raw.to_string();
        let error = compile_pillar_plan(
            &frozen_raw,
            &opening,
            &[],
            &["qwen".to_string()],
            "Build one Python application; `python -m app` must boot it.",
        )
        .unwrap_err()
        .to_string();
        assert!(error.contains("planner_correction[missing_advertised_entries]"));
        assert!(error.contains("app/__main__.py"));
        assert_eq!(raw.to_string(), frozen_raw);
        assert!(!frozen_raw.contains("app/__main__.py"));
        assert!(frozen_raw.contains("model-authored core responsibility"));
    }

    #[test]
    fn pillar_planner_only_fail_closes_lifecycle_integrity_errors() {
        assert!(pillar_planner_integrity_failure(&anyhow!(
            "pre-scheduler source terminal reconciliation failed: conflicting terminal receipt"
        )));
        assert!(pillar_planner_integrity_failure(&anyhow!(
            "pre-scheduler physical lifecycle completion failed: invalid transition"
        )));
        assert!(pillar_planner_integrity_failure(&anyhow!(
            "provider failed; pre-scheduler physical lifecycle completion also failed: invalid transition"
        )));
        assert!(!pillar_planner_integrity_failure(&anyhow!(
            "provider connection reset before a typed response"
        )));
        assert!(!pillar_planner_integrity_failure(&anyhow!(
            "pillar plan was not valid typed JSON"
        )));
    }

