    #[test]
    fn fix_attempt_progress_fold_tracks_first_change_and_longest_still() {
        // F781/#15: 5 samples — still, change, still, still, change. First change at 120s;
        // longest still window = 2 consecutive still samples after a change = 120s.
        let mut st = FixAttemptProgress::default();
        let mut last = None;
        st.note_sample(60, (3, 100), &mut last); // baseline — no prior, not "changed"
        st.note_sample(120, (4, 200), &mut last); // first change
        st.note_sample(180, (4, 200), &mut last);
        st.note_sample(240, (4, 200), &mut last);
        st.note_sample(300, (5, 290), &mut last);
        assert_eq!(st.samples, 5);
        assert_eq!(st.changed, 2);
        assert_eq!(st.first_change_secs, Some(120));
        assert_eq!(st.longest_still_secs, 2 * FIX_PROGRESS_SAMPLE_SECS);
        // An attempt that never writes: no first change, still window grows the whole run.
        let mut idle = FixAttemptProgress::default();
        let mut last2 = None;
        for k in 1..=4u64 {
            idle.note_sample(60 * k, (3, 100), &mut last2);
        }
        assert_eq!(idle.first_change_secs, None);
        assert_eq!(idle.longest_still_secs, 3 * FIX_PROGRESS_SAMPLE_SECS);
    }

    #[test]
    fn judge_probes_the_shadow_only_in_an_active_fix_round() {
        let cwd = PathBuf::from("/real");
        let shadow = PathBuf::from("/shadow");
        // No round: always the real tree, even when a shadow exists (speculation twins keep
        // today's judge semantics byte-identical).
        assert_eq!(
            judge_probe_root_for(false, Some(shadow.clone()), cwd.clone()),
            cwd
        );
        // Active round + shadow: probe what the fix agent actually edits.
        assert_eq!(
            judge_probe_root_for(true, Some(shadow.clone()), cwd.clone()),
            shadow
        );
        // Active round, no shadow (yet): the real tree, never a panic.
        assert_eq!(judge_probe_root_for(true, None, cwd.clone()), cwd);
    }

    #[test]
    fn pending_questions_finds_unanswered_oldest_first_and_answer_marks_done() {
        // F790-3: the answer file's existence IS the answered-marker.
        let dir = tempfile::TempDir::new().unwrap();
        let root = dir.path();
        let qdir = root.join(".swarm").join("questions");
        let adir = root.join(".swarm").join("answers");
        std::fs::create_dir_all(&qdir).unwrap();
        std::fs::create_dir_all(&adir).unwrap();
        assert!(
            pending_questions(root).is_empty(),
            "empty inbox: nothing pending"
        );
        std::fs::write(qdir.join("q1.txt"), "how far along?").unwrap();
        std::fs::write(qdir.join("q2.txt"), "why is api slow?").unwrap();
        std::fs::write(qdir.join("notes.md"), "not a question").unwrap();
        let pend = pending_questions(root);
        assert_eq!(pend.len(), 2, "only .txt files are questions");
        std::fs::write(adir.join("q1.txt"), "we are 8/12 done").unwrap();
        let pend = pending_questions(root);
        assert_eq!(pend.len(), 1);
        assert!(pend[0].ends_with("q2.txt"), "answered q1 dropped out");
    }

    #[test]
    fn digest_failed_calls_block_extracts_only_failures_capped() {
        // F790-2: 5 calls — 1 ok, 4 failed; the block carries the LAST 3 failures with tails.
        let digest = Some(serde_json::json!({
            "calls": [
                {"name": "shell", "summary": "pytest", "ok": false, "result": "fail-1"},
                {"name": "write", "summary": "api.py", "ok": true, "result": "ok"},
                {"name": "shell", "summary": "pytest", "ok": false, "result": "fail-2"},
                {"name": "edit", "summary": "store.py", "ok": false, "result": "fail-3"},
                {"name": "shell", "summary": "run", "ok": false, "result": "fail-4"},
            ]
        }));
        let b = digest_failed_calls_block(&digest).unwrap();
        assert!(b.contains("fail-2") && b.contains("fail-3") && b.contains("fail-4"));
        assert!(!b.contains("fail-1"), "capped to the last 3 failures");
        assert!(!b.contains("api.py"), "successful calls are not evidence");
        // In-flight calls (ok: null) are not failures.
        let pending = Some(serde_json::json!({
            "calls": [{"name": "shell", "summary": "x", "ok": null, "result": ""}]
        }));
        assert!(digest_failed_calls_block(&pending).is_none());
        assert!(digest_failed_calls_block(&None).is_none());
    }

    #[test]
    fn generated_tests_extract_fenced_or_bare_but_never_garbage() {
        // Fenced: unchanged behavior.
        let fenced = "here you go\n```python\nimport pytest\n\ndef test_a():\n    assert 1\n```";
        assert!(extract_generated_tests(fenced)
            .unwrap()
            .starts_with("import pytest"));
        // F804-batch: a BARE reply (the measured 0/3 class) lands via the fallback — reasoning
        // preamble stripped to the first import/def line.
        let bare = "I'll write the tests now. They cover the happy path.\n\nimport pytest\n\ndef test_b():\n    assert 2";
        let got = extract_generated_tests(bare).unwrap();
        assert!(got.starts_with("import pytest") && got.contains("def test_b"));
        // No test function anywhere: nothing to land.
        assert!(extract_generated_tests("just prose, no code").is_none());
        assert!(extract_generated_tests("def helper(): pass").is_none());
    }

