    #[test]
    fn fix_shadow_guard_discards_only_while_armed() {
        // c3: judge kills run ONLY Drop. Armed drop removes the entry (TempDir cleanup);
        // a disarmed guard leaves the epilogue's decision alone.
        let shadows: Mutex<HashMap<String, (tempfile::TempDir, Vec<String>)>> =
            Mutex::new(HashMap::new());
        let dir = tempfile::TempDir::new().unwrap();
        let path = dir.path().to_path_buf();
        shadows
            .lock()
            .unwrap()
            .insert("fix::r0::a.py".into(), (dir, vec!["a.py".into()]));
        {
            let _g = FixShadowGuard {
                shadows: &shadows,
                task_id: "fix::r0::a.py".into(),
                armed: true,
            };
        }
        assert!(
            !shadows.lock().unwrap().contains_key("fix::r0::a.py"),
            "armed drop discards the shadow"
        );
        assert!(!path.exists(), "the TempDir is gone with the entry");

        let dir2 = tempfile::TempDir::new().unwrap();
        shadows
            .lock()
            .unwrap()
            .insert("fix::r0::b.py".into(), (dir2, vec!["b.py".into()]));
        let g2 = FixShadowGuard {
            shadows: &shadows,
            task_id: "fix::r0::b.py".into(),
            armed: true,
        };
        g2.disarm();
        assert!(
            shadows.lock().unwrap().contains_key("fix::r0::b.py"),
            "a disarmed guard leaves the shadow to the epilogue"
        );
    }

    #[test]
    fn fix_round_specs_disjoint_roots_and_collision_proof_join() {
        // F781/#16 commit 4: two file groups + one file-less finding -> two Ready roots owning
        // one file each, plus a #join owning everything and depending on both.
        let findings = vec![
            "app/api.py:12: TypeError in handler".to_string(),
            "app/api.py:40: missing timeout".to_string(),
            "app/store.py:5: bad upsert".to_string(),
            "the second sync re-fetched 247 rows".to_string(),
        ];
        let all = vec!["app/api.py".to_string(), "app/store.py".to_string()];
        let specs = fix_round_specs(&findings, &all, 2, TargetLang::Python);
        let ids: Vec<&str> = specs.iter().map(|t| t.id.as_str()).collect();
        assert_eq!(
            ids,
            [
                "fix::r2::app/api.py",
                "fix::r2::app/store.py",
                "fix::r2::#join"
            ]
        );
        assert_eq!(specs[0].owned_files, ["app/api.py"]);
        assert!(specs[0].deps.is_empty(), "fix tasks are roots — born Ready");
        assert_eq!(specs[2].owned_files, all, "the join owns every smoke file");
        assert_eq!(
            specs[2].deps,
            ["fix::r2::app/api.py", "fix::r2::app/store.py"],
            "the join waits for every fix"
        );
        // The DAG accepts the specs; roots are Ready, the join is Pending.
        let dag = goose_swarm::Dag::from_specs(specs).unwrap();
        assert_eq!(
            dag.tasks["fix::r2::app/api.py"].state,
            goose_swarm::TaskState::Ready
        );
        assert_eq!(
            dag.tasks["fix::r2::#join"].state,
            goose_swarm::TaskState::Pending
        );
        // A source file whose name is exactly `join` (with any matchable extension) cannot
        // collide with the join id — '#' never appears in a normalized file id.
        let tricky = vec!["join.py:1: broken".to_string(), "no file here".to_string()];
        let all2 = vec!["join.py".to_string()];
        let specs2 = fix_round_specs(&tricky, &all2, 0, TargetLang::Python);
        let ids2: Vec<&str> = specs2.iter().map(|t| t.id.as_str()).collect();
        assert_eq!(ids2, ["fix::r0::join.py", "fix::r0::#join"]);
        assert!(
            goose_swarm::Dag::from_specs(specs2).is_ok(),
            "no id collision"
        );
        // No file-less findings -> no join at all.
        let only_file = vec!["app/api.py:1: x".to_string()];
        let specs3 = fix_round_specs(&only_file, &all, 1, TargetLang::Python);
        assert_eq!(specs3.len(), 1);
        assert!(!specs3.iter().any(|t| t.id.ends_with("#join")));
        // No findings -> no tasks.
        assert!(fix_round_specs(&[], &all, 0, TargetLang::Python).is_empty());
    }

    /// F881 REGRESSION (run 8, score 0.601): the repair round RACED whole-tree twins even though its
    /// first finding literally begins with a path. 0 of 3 twins promoted, as 0 of 9 had before it.
    /// These are the THREE finding strings run 8's own `complete_verify` emitted, and the file list
    /// its DAG owned. If attribution returns no group, the round can only race — so this test pins
    /// the routing INPUT, not the routing rule (which `prefer_shard_over_race` already pins).
    #[test]
    fn run8_findings_attribute_to_files_so_the_round_shards() {
        let files: Vec<String> = [
            "README.md",
            "test_api.py",
            "test_main.py",
            "test_meridian.py",
            "test_store.py",
            "test_web.py",
            "vendorsync/__init__.py",
            "vendorsync/__main__.py",
            "vendorsync/api.py",
            "vendorsync/meridian.py",
            "vendorsync/store.py",
            "vendorsync/web/app.js",
            "vendorsync/web/index.html",
            "vendorsync/web/styles.css",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        let findings = vec![
            "vendorsync/web/app.js:132 references DOM id `sync-error` which NO html file in the app \
             defines — getElementById returns null there and the page throws at runtime (the \
             rendered-nothing class). Either add the id to the HTML or fix the reference to an id \
             that exists.".to_string(),
            "POST /api/sync is not CHEAP on a repeat run — the second sync re-fetched 247 row(s) it \
             already had. FIX: make the client send If-None-Match per page.".to_string(),
            "the page renders but the browser console carries 2 error(s) in normal use (first: \
             Failed to load resource: net::ERR_EMPTY_RESPONSE) — fix the JS errors; users hit them \
             as broken interactions.".to_string(),
        ];
        let (groups, unassigned) = group_findings_by_file(&findings, &files);
        eprintln!("GROUPS={} UNASSIGNED={}", groups.len(), unassigned.len());
        for g in &groups {
            eprintln!("  group {} <- {} finding(s)", g.file, g.findings.len());
        }
        let attributed: usize = groups.iter().map(|g| g.findings.len()).sum();
        assert!(
            prefer_shard_over_race(true, groups.len(), attributed),
            "run 8's findings must route to per-file sharding, not a whole-tree race"
        );
    }

    /// F881 (run 8, 0.601): the vendor client stored ONE collection-wide ETag and looped on 304
    /// forever after a cursor restart. The author must receive the conditional-request fact, and it
    /// must not spray onto tasks that have nothing to do with paged fetching.
    #[test]
    fn conditional_request_pitfall_reaches_the_client_author() {
        let client = relevant_pitfalls(
            "Implement the Meridian vendor client: paginate with next_cursor, honour ETag / \
             If-None-Match, and handle 429 Retry-After. vendorsync/meridian.py",
        )
        .expect("a conditional-request task must retrieve the ETag pitfall");
        assert!(
            client.contains("an ETag belongs to ONE page"),
            "the ETag-per-page fact did not reach the client author: {client}"
        );
        assert!(
            client.contains("infinite loop"),
            "the measured 304 loop must be named, not merely implied: {client}"
        );
        assert!(
            !client.contains("CRON day-of-week"),
            "unrelated trivia must not ride along"
        );
        // A frontend task mentions "pagination controls" and must NOT be handed vendor-protocol
        // trivia — the triggers are deliberately protocol words, not topical ones.
        assert!(
            relevant_pitfalls(
                "Render the payments table with pagination controls and a status filter"
            )
            .is_none_or(|p| !p.contains("an ETag belongs to ONE page")),
            "a UI pagination task must not receive vendor conditional-request trivia"
        );
    }

    /// F881: the paired-observation rule that separates "this endpoint died once it held data" from
    /// "this endpoint is slow" — the distinction curl's exit code alone could not make.
    #[test]
    fn only_a_read_that_worked_empty_and_died_populated_is_a_wedge() {
        // The measured case: /api/summary answered 200 empty, nothing at all after a sync.
        assert!(wedged_after_populating(200, 0));
        assert!(wedged_after_populating(204, 0));
        // Already broken while empty -> the FIRST pass owns it; reporting it twice is double-counting.
        assert!(!wedged_after_populating(500, 0));
        assert!(!wedged_after_populating(404, 0));
        // Never answered in either state -> a transport story, never an app defect.
        assert!(!wedged_after_populating(0, 0));
        // Still answering once populated -> no wedge, whatever else the body may be missing.
        assert!(!wedged_after_populating(200, 200));
        assert!(!wedged_after_populating(200, 500));
    }

    /// F882 REGRESSION (run 9, round 0): TWO findings, both describing file-anchored work, BOTH
    /// attributed to nothing — so the round raced whole-tree twins (lifetime 0 of 12 promoted)
    /// instead of sharding. These are the REAL shapes from that round: (1) a `pytest -q` failure
    /// whose only file mentions are node-id summary lines with a status word in front; (2) the
    /// gate's own NotCheap finding, which described the client fix in full and named no file —
    /// now required to carry the client path the spec's module table derives.
    #[test]
    fn run9_round0_findings_attribute_and_shard() {
        let files: Vec<String> = [
            "vendorsync/api.py",
            "vendorsync/meridian.py",
            "vendorsync/store.py",
            "tests/test_api.py",
            "tests/test_meridian.py",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        let pytest_finding =
            "`pytest -q` failed — the generated tests exercise runtime paths that \
             `--help`/`--collect-only` never invoke:\n\
             ERROR tests/test_api.py::TestPayments::test_payments_item_keys - AttributeError\n\
             ERROR tests/test_api.py::TestSummarySync::test_summary_empty_db - AttributeError\n\
             19 failed, 33 passed, 16 warnings, 15 errors in 22.59s"
                .to_string();
        let notcheap_finding = "POST /api/sync is not CHEAP on a repeat run — the second sync \
             re-fetched 247 row(s) it already had. Key each page's ETag by the exact request that \
             produced it. The vendor client lives in `vendorsync/meridian.py` — fix it there."
            .to_string();
        assert_eq!(
            extract_file_from_finding(&pytest_finding, &files).as_deref(),
            Some("tests/test_api.py"),
            "a pytest -q node-id summary must resolve to its file"
        );
        assert_eq!(
            extract_file_from_finding(&notcheap_finding, &files).as_deref(),
            Some("vendorsync/meridian.py"),
            "a client-behaviour finding must resolve to the client file it now names"
        );
        let (groups, unassigned) =
            group_findings_by_file(&[pytest_finding, notcheap_finding], &files);
        assert_eq!(groups.len(), 2, "two files, two shards");
        assert!(unassigned.is_empty());
        let attributed: usize = groups.iter().map(|g| g.findings.len()).sum();
        assert!(
            prefer_shard_over_race(true, groups.len(), attributed),
            "run 9's round must shard, not race"
        );
    }

    /// F885 (run 10, round 0, watched live): the app.js shard's worker added every missing DOM
    /// id to index.html — a file it did not own — so grade-what-lands refused the byte-identical
    /// app.js and a CORRECT repair was discarded. A js/css shard owns its page markup too.
    #[test]
    fn a_script_shard_owns_the_markup_it_must_reconcile_with() {
        let files: Vec<String> = [
            "vendorsync/web/app.js",
            "vendorsync/web/index.html",
            "vendorsync/web/styles.css",
            "vendorsync/api.py",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        let taken: std::collections::HashSet<String> =
            ["vendorsync/web/app.js".to_string()].into_iter().collect();
        assert_eq!(
            shard_owned_files("vendorsync/web/app.js", &files, &taken),
            vec![
                "vendorsync/web/app.js".to_string(),
                "vendorsync/web/index.html".to_string()
            ]
        );
        // If a sibling group already owns the html, the partition stays disjoint.
        let taken2: std::collections::HashSet<String> = [
            "vendorsync/web/app.js".to_string(),
            "vendorsync/web/index.html".to_string(),
        ]
        .into_iter()
        .collect();
        assert_eq!(
            shard_owned_files("vendorsync/web/app.js", &files, &taken2),
            vec!["vendorsync/web/app.js".to_string()]
        );
    }

    /// F892 (fleet sb-6 run, round 0, watched live): the Unreadable-POST finding hardcoded the
    /// sync counters, so on a spec with four POST endpoints the note/batch/webhook handlers were
    /// accused of missing ANOTHER endpoint's fields. The keys must come from the accused path's
    /// own table row.
    #[test]
    fn each_post_is_accused_only_of_its_own_documented_shape() {
        let spec = "| method | path | response |\n|---|---|---|\n\
            | `POST` | `/api/sync` | `{\"fetched\": 0, \"inserted\": 0, \"total\": 0}` |\n\
            | `POST` | `/api/payments/batch` | `{\"created\": [], \"failed\": []}` |\n";
        assert_eq!(
            spec_documented_keys(spec, "/api/sync"),
            vec!["fetched", "inserted", "total"]
        );
        assert_eq!(
            spec_documented_keys(spec, "/api/payments/batch"),
            vec!["created", "failed"]
        );
        assert!(spec_documented_keys(spec, "/api/webhooks/meridian").is_empty());
    }

    #[test]
    fn group_findings_by_file_partitions_dedups_and_serializes() {
        let findings = vec![
            "tests/test_a.py:5: in test_x\n    assert foo() == 1\nE   AssertionError".to_string(),
            "spendlog/cli.py:12: in cmd_add\n    raise ValueError\nE   ValueError: boom"
                .to_string(),
            "spendlog/cli.py:40: in cmd_budget\n    x\nE   KeyError".to_string(), // SAME file
            "spendlog/cli.py:12: in cmd_add\n    raise ValueError\nE   ValueError: boom"
                .to_string(), // dup
            "no python3 -m spendlog entry point found".to_string(),               // unassigned
        ];
        let (groups, unassigned) = group_findings_by_file(&findings, &[]);
        let cli = groups
            .iter()
            .find(|g| g.file == "spendlog/cli.py")
            .expect("cli.py group");
        // The two DISTINCT cli.py findings collapse into ONE group (same-file serialize); the dup is dropped.
        assert_eq!(cli.findings.len(), 2);
        assert!(groups.iter().any(|g| g.file == "tests/test_a.py"));
        assert_eq!(unassigned.len(), 1); // the file-less finding
                                         // Partition invariant: every group names a distinct file.
        let files: std::collections::HashSet<_> = groups.iter().map(|g| &g.file).collect();
        assert_eq!(files.len(), groups.len());
    }

    /// THE FAN'S PRECONDITION. `complete_parallel` groups findings by file and fans one shard per
    /// group; anything with no file falls to the single serial fix worker that owns 22-44% of the
    /// run. MEASURED by porting this extractor and running it on the finding strings three real runs
    /// actually produced: FIVE of six shapes returned None, including the only two that appeared in
    /// every run. The fan was well built and had almost nothing to fan — the same shape as the
    /// judge-side splitter that never fires and the e2e fan that did not partition.
    #[test]
    fn every_real_finding_shape_resolves_to_a_file_group() {
        let files = vec![
            "vendorsync/api.py".to_string(),
            "vendorsync/store.py".to_string(),
            "vendorsync/meridian.py".to_string(),
            "tests/test_meridian.py".to_string(),
        ];
        let cases: [(&str, &str); 5] = [
            // AST review — names a MODULE, never a path. Present in 3 of 3 runs.
            (
                "function 'log_message' in module 'vendorsync.api' is a STUB/UNIMPLEMENTED — implement it",
                "vendorsync/api.py",
            ),
            // cross-module drift — names two modules; the READER is the one to fix.
            (
                "module 'vendorsync.api' reads field 'total' that 'vendorsync.store' does not define",
                "vendorsync/api.py",
            ),
            // engine-authored, path in backticks mid-sentence.
            (
                "planned deliverable `vendorsync/store.py` is MISSING or EMPTY — create it",
                "vendorsync/store.py",
            ),
            (
                "planned task `test-meridian` FAILED, but its deliverable `tests/test_meridian.py` IS \
              written. Its attempts were exhausted because the checks it runs DO NOT PASS.",
                "tests/test_meridian.py",
            ),
            // the pytest traceback the extractor was originally written for must still work.
            (
                "`pytest -q` failed:\ntests/test_meridian.py:89: in test_x\nE   AssertionError",
                "tests/test_meridian.py",
            ),
        ];
        for (finding, want) in cases {
            assert_eq!(
                extract_file_from_finding(finding, &files).as_deref(),
                Some(want),
                "finding did not resolve to its file: {finding:?}"
            );
        }
        // A finding that genuinely names no file must STILL be unassigned — the serial path is the
        // correct home for it, and inventing a file would aim a fix shard at nothing.
        assert_eq!(
            extract_file_from_finding(
                "GET /api/health returned 404 — the app does not implement it",
                &files
            ),
            None
        );

        // THE REAL PYTEST TRACEBACK, in the shape of the first finding this engine ever emitted. Its
        // FIRST frame is CPython's own threading.py and the app frame is ABSOLUTE. Neither may
        // escape: a stdlib path sends a fix shard to repair CPython, and an absolute path keys the
        // file-group differently from the rest of the engine and breaks the shadow tree's
        // promote-by-relative-path. Latent until F41 made the fan fire.
        let tb = "`pytest -q` failed:\n    File \"/opt/homebrew/Cellar/python@3.14/lib/python3.14/threading.py\", line 1024, in run\n    File \"/Users/x/runs/unit/vendorsync/meridian.py\", line 40, in serve";
        assert_eq!(
            extract_file_from_finding(tb, &files).as_deref(),
            Some("vendorsync/meridian.py"),
            "a traceback must resolve to the OWNED, repo-relative file — never the stdlib, never absolute"
        );

        // Naming only files this run does not own resolves to NOTHING; the serial fix path handles
        // it. Inventing an owner is worse than admitting there is none.
        let foreign =
            "File \"/opt/homebrew/Cellar/python@3.14/lib/python3.14/socket.py\", line 9, in x";
        assert_eq!(extract_file_from_finding(foreign, &files), None);
    }

    #[test]
    fn normalize_rel_path_collapses_spellings_to_one_group() {
        assert_eq!(normalize_rel_path("./pkg/x.py"), "pkg/x.py");
        assert_eq!(normalize_rel_path("pkg//x.py"), "pkg/x.py");
        assert_eq!(normalize_rel_path("pkg\\x.py"), "pkg/x.py");
        assert_eq!(normalize_rel_path("pkg/x.py"), "pkg/x.py");
        // Two DISTINCT findings that name the same file with different spellings must resolve to ONE
        // file-group — otherwise two shards would promote to the same real dst (a torn write).
        let findings = vec![
            "./pkg/cli.py:1: in a\nE   Err".to_string(),
            "pkg//cli.py:2: in b\nE   Err".to_string(),
        ];
        let (groups, _) = group_findings_by_file(&findings, &[]);
        assert_eq!(groups.len(), 1, "both spellings collapse to one group");
        assert_eq!(groups[0].file, "pkg/cli.py");
    }

    #[test]
    fn is_agent_loop_filler_catches_max_turns_message_and_empty() {
        // The exact goose core agent-loop max-turns filler (agent.rs MAX_TURNS_MESSAGE) — the string that
        // leaked into detailer specs (logstat-2, ledgr-2) and repro/verify verdicts.
        assert!(is_agent_loop_filler(
            "I've reached the maximum number of actions I can do without user input. Would you like me to continue?"
        ));
        assert!(is_agent_loop_filler(
            "  Final output tool has not been called yet. Continuing agent loop.  "
        ));
        // Empty / whitespace -> filler (subsumes the old empty-only guard).
        assert!(is_agent_loop_filler(""));
        assert!(is_agent_loop_filler("   \n\t"));
        // A REAL detailed subtask spec -> NOT filler (must be kept, not replaced by the brief).
        assert!(!is_agent_loop_filler(
            "Implement parser.py: tokenize the input into (ts, level, fields) records; skip malformed lines; \
             numeric field values parse as numbers. Files: logstat/parser.py."
        ));
        assert!(!is_agent_loop_filler(
            "def compute_ratio(a, b): guard b==0 with a clean error"
        ));
    }

    #[test]
    fn review_file_excerpt_keeps_small_whole_and_large_tail() {
        // A small file (< 6000 chars) is shown WHOLE.
        let small = "import argparse\n\ndef main():\n    pass\n";
        assert_eq!(review_file_excerpt(small), small);
        // A large file keeps its TAIL (the argparse dispatch the old head-truncation hid).
        let big = format!(
            "# top of file\n{}\ndef main():\n    args = p.parse_args()\n    DISPATCH_TAIL_MARKER(args)\n",
            "x = 1  # filler line\n".repeat(500)
        );
        let ex = review_file_excerpt(&big);
        assert!(ex.contains("# top of file"));
        assert!(ex.contains("DISPATCH_TAIL_MARKER"));
        assert!(ex.contains("middle elided"));
        assert!(ex.chars().count() < big.chars().count());
    }

    #[test]
    fn normalize_plan_files_to_package_truth_table() {
        use std::collections::HashSet;
        let pkg = "gradebook";
        let existing: HashSet<String> = ["stats.py", "__main__.py", "__init__.py"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        // COLLISION: a bare module that exists in the package -> pinned to <pkg>/<name>.
        let mut v = serde_json::json!({"subtasks":[
            {"id":"stats","files":["stats.py"]},                 // collision -> gradebook/stats.py
            {"id":"newf","files":["ranking.py"]},                // NEW module (not in pkg) -> untouched
            {"id":"test","files":["tests/test_stats.py"]},       // dir-prefixed -> untouched
            {"id":"cli","files":["gradebook/__main__.py"]},      // already pkg-prefixed -> untouched
            {"id":"conf","files":["conftest.py"]}                // root file, NOT in pkg -> untouched
        ]});
        let n = normalize_plan_files_to_package(&mut v, pkg, &existing);
        assert_eq!(n, 1); // only stats.py collided
        let f = |i: usize| v["subtasks"][i]["files"][0].as_str().unwrap().to_string();
        assert_eq!(f(0), "gradebook/stats.py"); // collision rewritten
        assert_eq!(f(1), "ranking.py"); // new module untouched
        assert_eq!(f(2), "tests/test_stats.py"); // dir-prefixed untouched
        assert_eq!(f(3), "gradebook/__main__.py"); // already-prefixed untouched
        assert_eq!(f(4), "conftest.py"); // root non-collision untouched
                                         // NO package (greenfield / empty existing set) -> no-op.
        let mut v2 = serde_json::json!({"subtasks":[{"id":"s","files":["stats.py"]}]});
        assert_eq!(
            normalize_plan_files_to_package(&mut v2, pkg, &HashSet::new()),
            0
        );
        assert_eq!(v2["subtasks"][0]["files"][0].as_str().unwrap(), "stats.py");
    }

    #[test]
    fn a_shifting_repetition_loop_recurs_across_judge_looks() {
        // The measured pathology: one sentence repeated verbatim; the window SHIFTS between looks.
        let sentence = "Let me write the two files. First, `app/ledgerd/server.py`: ";
        let looped = sentence.repeat(60);
        let look1 = looped.get(..2000).unwrap();
        let look2 = looped.get(137..2137).unwrap(); // shifted window — exact-hash saw "new content" here
        let (s1, s2) = (tail_shingle_set(look1), tail_shingle_set(look2));
        assert!(
            tails_recur(&s1, &s2),
            "a shifted repetition window must RECUR"
        );
        // Healthy advancing reasoning must NOT recur: two disjoint passages.
        let h1 = tail_shingle_set(
            &"the sync module pages the vendor with cursors and applies rows by version "
                .repeat(30),
        );
        let h2 = tail_shingle_set(
            &"the webhook consumer verifies signatures over raw bytes then stages txn groups "
                .repeat(30),
        );
        assert!(!tails_recur(&h1, &h2), "distinct content must not recur");
    }

    #[test]
    fn bind_first_hint_fires_only_on_a_crashless_tail() {
        // Alive-but-never-listens: the hint carries the bind-first diagnosis.
        assert!(
            bind_first_hint("poll: no port answered after 4.0s; tail: sync starting…")
                .contains("never started listening")
        );
        // A real crash: the traceback speaks for itself, no hint.
        assert_eq!(bind_first_hint("Traceback (most recent call last): …"), "");
        assert_eq!(bind_first_hint("ValueError: tokens file missing keys"), "");
        // And the AUTHOR hears the same rule at write time: a server-shaped task text pulls
        // pitfall 18 through the deterministic retrieval.
        let hits = relevant_pitfalls(
            "Implement ledgerd: binds 127.0.0.1, listening within 10 seconds; \
             on boot it starts its first sync unprompted",
        )
        .unwrap();
        assert!(
            hits.contains("BIND FIRST"),
            "server task text must retrieve the bind-first pitfall: {hits}"
        );
    }

    #[test]
    fn spec_json_stub_reproduces_the_documented_shape() {
        // The real sb-7 wording: the tokens-file shape is documented inline after the flag.
        let spec = "…- `--tokens-file` names a JSON file the harness writes before boot:\n  \
                    `{\"maker\": \"<32 hex>\", \"checker\": \"<32 hex>\", \"admin\": \"<32 hex>\"}` — the bearer tokens…";
        let stub = spec_json_stub(spec, "--tokens-file");
        let v: serde_json::Value = serde_json::from_str(&stub).unwrap();
        for k in ["maker", "checker", "admin"] {
            assert!(
                v.get(k)
                    .and_then(|x| x.as_str())
                    .is_some_and(|s| !s.is_empty() && !s.contains('<')),
                "documented key {k} must survive with a filled dummy value: {stub}"
            );
        }
        // No documented shape near the flag -> the old empty object, not an invention.
        assert_eq!(
            spec_json_stub("run `--tokens-file T` with your tokens", "--tokens-file"),
            "{}"
        );
        assert_eq!(spec_json_stub("no such flag at all", "--tokens-file"), "{}");
        // A shape that stays invalid JSON after placeholder fill is rejected, never shipped broken.
        assert_eq!(
            spec_json_stub("--tokens-file {not json here", "--tokens-file"),
            "{}"
        );
    }

