// ---------------------------------------------------------------------------------------------
// Structured observability — JSONL event log + per-run capture
// ---------------------------------------------------------------------------------------------

/// A tool is from an MCP extension (vs a goose builtin) if it is namespaced `{ext}__{tool}` and the
/// prefix is not a known builtin/platform namespace.
fn is_mcp_tool(name: &str) -> bool {
    name.contains("__")
        && !name.starts_with("developer__")
        && !name.starts_with("recipe__")
        && !name.starts_with("platform__")
}

/// PROGRESS WATCHDOG classifier: does this stream content represent PRODUCTIVE progress (advances the build),
/// as opposed to reasoning-only or a rejected/malformed emission? A real tool call (parsed OK — including
/// final_output), any tool RESULT, and non-empty non-thinking TEXT count. Thinking tokens and malformed tool
/// calls (the provider rejected them before any tool ran) do NOT — so a task that only reasons or only flails
/// lets the thinking_only_budget elapse and gets cut, while a genuinely-working task keeps resetting it.
fn message_content_is_productive(c: &MessageContent) -> bool {
    match c {
        MessageContent::Text(t) => !t.text.trim().is_empty(),
        MessageContent::ToolRequest(req) => req.tool_call.is_ok(),
        MessageContent::ToolResponse(_) => true,
        _ => false,
    }
}

fn compaction_trigger_kind(message: &str) -> Option<&'static str> {
    if message.starts_with("Exceeded auto-compact threshold") {
        Some("auto_threshold")
    } else if message == "Context limit reached. Compacting to continue conversation..." {
        Some("provider_context_limit")
    } else if message == "Context near the cap — compacting to stay lean..." {
        Some("proactive_turn")
    } else {
        None
    }
}

#[derive(Default)]
struct CompactionEventState {
    active: Option<u32>,
    awaiting_continuation: Option<u32>,
    sequence: u32,
}

struct CompactionStart {
    sequence: u32,
    superseded_active: Option<u32>,
    superseded_awaiting_continuation: Option<u32>,
}

impl CompactionEventState {
    fn start(&mut self) -> CompactionStart {
        let superseded_active = self.active.take();
        let superseded_awaiting_continuation = self.awaiting_continuation.take();
        self.sequence = self.sequence.saturating_add(1);
        self.active = Some(self.sequence);
        CompactionStart {
            sequence: self.sequence,
            superseded_active,
            superseded_awaiting_continuation,
        }
    }

    fn complete(&mut self) -> Option<u32> {
        let sequence = self.active.take()?;
        self.awaiting_continuation = Some(sequence);
        Some(sequence)
    }

    fn take_continuation(&mut self) -> Option<u32> {
        self.awaiting_continuation.take()
    }
}

#[cfg(test)]
mod compaction_event_tests {
    use super::{compaction_trigger_kind, CompactionEventState};

    #[test]
    fn classifies_only_real_agent_compaction_notices() {
        assert_eq!(
            compaction_trigger_kind(
                "Exceeded auto-compact threshold of 80%. Performing auto-compaction..."
            ),
            Some("auto_threshold")
        );
        assert_eq!(
            compaction_trigger_kind(
                "Context limit reached. Compacting to continue conversation..."
            ),
            Some("provider_context_limit")
        );
        assert_eq!(
            compaction_trigger_kind("Context near the cap — compacting to stay lean..."),
            Some("proactive_turn")
        );
        assert_eq!(compaction_trigger_kind("Compaction complete"), None);
    }

    #[test]
    fn supersedes_failed_attempt_and_uncontinued_completion_before_restart() {
        let mut state = CompactionEventState::default();
        let first = state.start();
        assert_eq!(first.sequence, 1);
        assert_eq!(first.superseded_active, None);

        let second = state.start();
        assert_eq!(second.sequence, 2);
        assert_eq!(second.superseded_active, Some(1));
        assert_eq!(state.complete(), Some(2));

        let third = state.start();
        assert_eq!(third.sequence, 3);
        assert_eq!(third.superseded_active, None);
        assert_eq!(third.superseded_awaiting_continuation, Some(2));
    }
}

/// A short, human-readable summary of a tool call's arguments for the desktop run panel: the shell
/// line, the edited path, the search query — whatever field carries the intent. Falls back to a
/// compact JSON dump. Single-lined and capped so the digest stays small.
fn summarize_tool_call(_name: &str, args: &serde_json::Value) -> String {
    let obj = args.as_object();
    let get = |k: &str| {
        obj.and_then(|o| o.get(k))
            .and_then(|v| v.as_str())
            .map(str::to_string)
    };
    let raw = if let Some(command) = get("command") {
        // developer__text_editor: command is a verb (view/write/str_replace) paired with a path;
        // developer__shell: command IS the shell line and there is no path.
        match get("path") {
            Some(path) => format!("{command} {path}"),
            None => command,
        }
    } else if let Some(path) = get("path") {
        path
    } else if let Some(q) = get("query")
        .or_else(|| get("pattern"))
        .or_else(|| get("uri"))
        .or_else(|| get("url"))
        .or_else(|| get("text"))
    {
        q
    } else {
        serde_json::to_string(args).unwrap_or_default()
    };
    let flat = raw.split_whitespace().collect::<Vec<_>>().join(" ");
    let n = flat.chars().count();
    if n > 200 {
        format!("{}…", flat.chars().take(199).collect::<String>())
    } else {
        flat
    }
}

/// Keep the last `max` chars of a snippet, with a leading ellipsis when clipped. Tail, not head, because
/// the informative part of tool output (the pass/fail line, the traceback, the printed value) is at the end.
fn clip_tail(s: &str, max: usize) -> String {
    let s = s.trim();
    let n = s.chars().count();
    if n > max {
        format!("…{}", s.chars().skip(n - max).collect::<String>())
    } else {
        s.to_string()
    }
}

fn tool_result_full_text<E>(result: &Result<rmcp::model::CallToolResult, E>) -> String {
    let Ok(r) = result else {
        return String::new();
    };
    r.content
        .iter()
        .filter_map(|c| match &c.raw {
            rmcp::model::RawContent::Text(t) => Some(t.text.as_str()),
            _ => None,
        })
        .collect::<Vec<_>>()
        .join("\n")
}

/// The worker's FULL narration — every substantive text chunk it produced, in order, joined. This is the
/// "read the reasoning in plain" the run panel shows on expand (distinct from `build_reasoning`, which is
/// the short last-few-chunks summary the judge reads). Tail-capped very generously.
fn build_full_reasoning(texts: &[String]) -> String {
    // Walk from the newest chunk backward, keeping only enough substantive tail to cover the 24000-char clip
    // below, then stop. This is O(kept) instead of O(all-texts) — the digest is rebuilt on a hot timer while
    // `texts` grows for the whole task. clip_tail still yields the EXACT same last 24000 chars: once the kept
    // suffix is itself >= 24000 chars, clipping it equals clipping the full join (the char count here ignores
    // the "\n\n" separators, which only makes the real suffix longer, so we never keep too little).
    let mut kept: Vec<&str> = Vec::new();
    let mut chars = 0usize;
    for t in texts.iter().rev() {
        let t = t.trim();
        if t.chars().count() >= 6 && t.contains(char::is_whitespace) {
            chars += t.chars().count();
            kept.push(t);
            if chars >= 24000 {
                break;
            }
        }
    }
    kept.reverse();
    let joined = kept.join("\n\n");
    clip_tail(&joined, 24000)
}

/// The user's answers are BINDING, and the framing says so imperatively.
///
/// MEASURED TWICE that a weak worker treats a soft-framed answer as advisory and substitutes its own
/// convention: asked for pipe-separated CSV it wrote comma-separated; asked for an exact list format it
/// invented a variant. The answers are the user's explicit choices, so the prompt says so in the
/// imperative rather than calling them "clarifications".
/// ONE constant, used for BOTH copies — the one appended to the spec (which reaches the replanner, judge
/// and pre-reviewer) and the one injected into every worker prompt. They cannot drift apart.
const USER_DECISIONS_HEADER: &str = "\n\n## USER DECISIONS — BINDING\n\
     The user was ASKED and chose the following. Implement each EXACTLY as written. Do NOT paraphrase it, \
     rename it, or substitute your own convention/format — if a decision names a separator, a format, a \
     default, or an order, use THAT one verbatim. These override any conflicting habit or default you \
     would otherwise pick:\n";

fn binding_spec_with_user_decisions(raw_user_spec: &str, user_decisions: &str) -> String {
    if user_decisions.trim().is_empty() {
        raw_user_spec.to_string()
    } else {
        format!("{}{}", raw_user_spec.trim_end(), user_decisions)
    }
}

fn canonical_plan_needs_binding_refresh(plan_json: &str, binding_spec: &str) -> Result<bool> {
    let plan: serde_json::Value = serde_json::from_str(plan_json)?;
    let authority_ids = canonical_plan_requirement_ids(&plan)?
        .ok_or_else(|| anyhow!("accepted plan has no canonical requirement authority"))?;
    let binding_ids = normalized_requirement_inventory(binding_spec)
        .into_iter()
        .map(|requirement| requirement.id)
        .collect::<Vec<_>>();
    Ok(authority_ids != binding_ids)
}

/// The last `max` characters of `s` (char-wise, never a byte slice — these are model tokens).
fn tail_chars(s: &str, max: usize) -> String {
    let n = s.chars().count();
    if n > max {
        s.chars().skip(n - max).collect()
    } else {
        s.to_string()
    }
}

/// Build the worker's live reasoning from its text chunks, dropping the trivial fragments (a lone ".",
/// "`", a stray word) these coder models emit between tool calls — so the run panel shows real narration
/// or nothing, never a box holding a single dot. Keeps the last few substantive chunks, tail-capped.
fn build_reasoning(texts: &[String]) -> String {
    // Keep the last few substantive chunks. Walk from the back and stop after 4: the digest is rebuilt on a hot
    // timer while `texts` grows for the whole task, so scanning from the end is O(kept), not O(all-texts). The
    // result is identical to filtering everything and taking the last 4 in order.
    let mut last: Vec<&str> = texts
        .iter()
        .rev()
        .map(|t| t.trim())
        .filter(|t| t.chars().count() >= 16 && t.contains(char::is_whitespace))
        .take(4)
        .collect();
    last.reverse();
    let joined = last.join("\n");
    clip_tail(&joined, 1200)
}

type PendingToolCall = (String, bool, bool, String, Vec<String>, String);

/// Build the `.swarm/activity/<key>.json` digest a worker/scout/planner call refreshes as it streams. The judge
/// reads only tool_calls/errors/recent/last_text; every other key is inert to it (unknown-key-tolerant reader) and
/// powers the desktop panel's live per-node view. Two dev-verbosity additions over the old inline block: (1) each
/// completed call carries `is_mcp` (an honest MCP pill), and (2) the IN-FLIGHT `pending` calls are appended as
/// provisional records with `ok: null` so the panel shows what a node is CALLING right now, not only what finished.
#[allow(clippy::too_many_arguments)]
fn build_worker_digest(
    tool_calls: &[ToolCallRecord],
    call_records: &[(String, String, Option<bool>, String)],
    pending: &HashMap<String, PendingToolCall>,
    texts: &[String],
    malformed: usize,
    thinking_chars: usize,
    last_thinking: &str,
    reasoning_recurrence: &ReasoningRecurrenceMeter,
    model_id: &str,
    provider_stream: ProviderStreamProgressSnapshot,
) -> serde_json::Value {
    let errors = tool_calls.iter().filter(|t| t.ok == Some(false)).count();
    let recent: Vec<String> = tool_calls
        .iter()
        .rev()
        .take(6)
        .rev()
        .map(|t| {
            format!(
                "{} {}",
                t.name,
                if t.ok == Some(false) { "ERR" } else { "ok" }
            )
        })
        .collect();
    // STREAM DELTAS, NOT MESSAGES. `texts` gets one entry per streamed Text chunk, so `.last()` was
    // whatever fragment the model emitted last — routinely a few words or a bare "." — and this field
    // is what the judge's prompt presents as the worker's own account of itself, and what the desktop
    // shows as the node's last line. The Thinking path hit exactly this and was fixed by accumulating
    // a rolling tail (see its comment at the stream site); text never was. Concatenate a bounded tail
    // of chunks so the field carries a readable run of what the worker actually said.
    let start = texts.len().saturating_sub(64);
    let lt: String = texts[start..].concat();
    let n = lt.chars().count();
    let last_text: String = if n > 400 {
        lt.chars().skip(n - 400).collect()
    } else {
        lt
    };
    let mut calls: Vec<serde_json::Value> = call_records
        .iter()
        .rev()
        .take(60)
        .rev()
        .map(|(name, summary, ok, result)| {
            serde_json::json!({ "name": name, "summary": summary, "ok": ok, "result": result, "is_mcp": is_mcp_tool(name) })
        })
        .collect();
    // In-flight calls (not yet resolved) as provisional records: ok:null → the desktop's classifyCall renders
    // them as "running…" so a node mid-call reads as CALLING, not idle.
    for (name, is_mcp, _fetched, summary, _receipts, _request_text) in pending.values() {
        calls.push(serde_json::json!({
            "name": name, "summary": summary, "ok": serde_json::Value::Null, "result": "", "is_mcp": is_mcp
        }));
    }
    serde_json::json!({
        "tool_calls": tool_calls.len(),
        "errors": errors,
        "malformed": malformed,
        "recent": recent,
        "last_text": last_text,
        "calls": calls,
        "reasoning": build_reasoning(texts),
        "full_reasoning": build_full_reasoning(texts),
        "thinking_chars": thinking_chars,
        // Carry a generous tail of the live reasoning so the desktop's expandable per-node box shows a real
        // run of thinking, not a sliver. The compact line still clamps it; the expand shows the whole thing.
        "last_thinking": tail_chars(last_thinking, 2000),
        // Recurrence is neutral telemetry only; provider-stream progress is separately validated by
        // the decoder and may disprove a stale observation without exposing structured payloads.
        "reasoning_recurrence": reasoning_recurrence.snapshot(),
        "provider_stream": provider_stream,
        "model": model_id,
    })
}

/// Per-run JSONL event sink. All writes go through one locked, line-flushed writer; a monotonic
/// `seq` gives a total order even though scheduler events and CLI-native events interleave.
struct JsonlSink {
    writer: Mutex<std::io::BufWriter<std::fs::File>>,
    run_id: String,
    seq: AtomicU64,
}

impl JsonlSink {
    fn new(path: &Path, run_id: String) -> Result<Self> {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        let file = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)?;
        Ok(Self {
            writer: Mutex::new(std::io::BufWriter::new(file)),
            run_id,
            seq: AtomicU64::new(0),
        })
    }

    fn write_line(&self, mut value: serde_json::Value) {
        let seq = self.seq.fetch_add(1, Ordering::SeqCst);
        if let Some(obj) = value.as_object_mut() {
            obj.insert(
                "ts".to_string(),
                serde_json::json!(chrono::Utc::now().to_rfc3339()),
            );
            obj.insert("run_id".to_string(), serde_json::json!(self.run_id));
            obj.insert("seq".to_string(), serde_json::json!(seq));
        }
        if let Ok(mut w) = self.writer.lock() {
            let _ = serde_json::to_writer(&mut *w, &value);
            let _ = w.write_all(b"\n");
            let _ = w.flush();
        }
    }
}

impl EventSink for JsonlSink {
    fn emit(&self, event: &SwarmEvent) {
        if let Ok(value) = serde_json::to_value(event) {
            self.write_line(value);
        }
    }
    fn write_value(&self, value: serde_json::Value) {
        self.write_line(value);
    }
}

