    #[tokio::test]
    async fn shared_host_scheduler_keeps_a_later_flexible_host_for_constrained_work() {
        let lanes = ["host-a", "host-b"]
            .into_iter()
            .enumerate()
            .map(|(index, host)| ResearchPhysicalLane {
                token: format!("lane-{index}"),
                model_id: format!("model-{index}"),
                physical_host_id: host.to_string(),
                verified_physical: true,
            })
            .collect::<Vec<_>>();
        let scheduler = ResearchHostScheduler::new(lanes);
        let held_a = scheduler
            .acquire(vec!["lane-0".to_string()], 1, 0, "held-a".to_string())
            .await
            .unwrap();
        let held_b = scheduler
            .acquire(vec!["lane-1".to_string()], 1, 0, "held-b".to_string())
            .await
            .unwrap();
        let flexible = tokio::spawn({
            let scheduler = scheduler.clone();
            async move {
                scheduler
                    .acquire(
                        vec!["lane-0".to_string(), "lane-1".to_string()],
                        100,
                        0,
                        "flexible".to_string(),
                    )
                    .await
                    .unwrap()
            }
        });
        let constrained = tokio::spawn({
            let scheduler = scheduler.clone();
            async move {
                scheduler
                    .acquire(vec!["lane-0".to_string()], 1, 0, "constrained".to_string())
                    .await
                    .unwrap()
            }
        });
        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            loop {
                if scheduler.inner.state.lock().unwrap().pending.len() == 2 {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("both constrained and flexible requests queued behind held hosts");
        drop(held_a);
        let constrained = tokio::time::timeout(std::time::Duration::from_secs(2), constrained)
            .await
            .expect("the constrained request received its only eligible host")
            .unwrap();
        assert_eq!(constrained.lane.token, "lane-0");
        assert!(
            !flexible.is_finished(),
            "the flexible request must not strand constrained work on the first release"
        );
        drop(held_b);
        let flexible = flexible.await.unwrap();
        assert_eq!(flexible.lane.token, "lane-1");
    }

    #[tokio::test]
    async fn shared_host_scheduler_admits_old_juror_before_two_newer_citations() {
        let scheduler = ResearchHostScheduler::new(vec![ResearchPhysicalLane {
            token: "lane-mac".to_string(),
            model_id: "model-mac".to_string(),
            physical_host_id: "host-mac".to_string(),
            verified_physical: true,
        }]);
        let held = scheduler
            .acquire(
                vec!["lane-mac".to_string()],
                1,
                0,
                "active-work".to_string(),
            )
            .await
            .unwrap();
        let old_juror = tokio::spawn({
            let scheduler = scheduler.clone();
            async move {
                scheduler
                    .acquire(
                        vec!["lane-mac".to_string()],
                        1_001,
                        1,
                        "old-jury-2".to_string(),
                    )
                    .await
                    .unwrap()
            }
        });
        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            while scheduler.inner.state.lock().unwrap().pending.len() != 1 {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("the old juror queued behind the active host");
        let first_citation = tokio::spawn({
            let scheduler = scheduler.clone();
            async move {
                scheduler
                    .acquire(
                        vec!["lane-mac".to_string()],
                        20_000,
                        3,
                        "newer-citation-1".to_string(),
                    )
                    .await
                    .unwrap()
            }
        });
        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            while scheduler.inner.state.lock().unwrap().pending.len() != 2 {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("the first newer citation queued behind the old juror");
        let second_citation = tokio::spawn({
            let scheduler = scheduler.clone();
            async move {
                scheduler
                    .acquire(
                        vec!["lane-mac".to_string()],
                        30_000,
                        3,
                        "newer-citation-2".to_string(),
                    )
                    .await
                    .unwrap()
            }
        });
        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            while scheduler.inner.state.lock().unwrap().pending.len() != 3 {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("both newer citations queued behind the old juror");

        drop(held);
        let old_juror = tokio::time::timeout(std::time::Duration::from_secs(2), old_juror)
            .await
            .expect("the old juror received the first released host")
            .unwrap();
        assert_eq!(old_juror.lane.token, "lane-mac");
        assert!(!first_citation.is_finished());
        assert!(!second_citation.is_finished());

        drop(old_juror);
        let first_citation =
            tokio::time::timeout(std::time::Duration::from_secs(2), first_citation)
                .await
                .expect("the older citation received the next release")
                .unwrap();
        assert!(!second_citation.is_finished());
        drop(first_citation);
        let second_citation =
            tokio::time::timeout(std::time::Duration::from_secs(2), second_citation)
                .await
                .expect("the final citation received the final release")
                .unwrap();
        drop(second_citation);
    }

    #[tokio::test]
    async fn shared_host_scheduler_batches_downstream_before_reassigning_a_released_host() {
        let lanes = ["host-a", "host-b", "host-c"]
            .into_iter()
            .enumerate()
            .map(|(index, host)| ResearchPhysicalLane {
                token: format!("lane-{index}"),
                model_id: format!("model-{index}"),
                physical_host_id: host.to_string(),
                verified_physical: true,
            })
            .collect::<Vec<_>>();
        let scheduler = ResearchHostScheduler::new(lanes);
        let held_a = scheduler
            .acquire(vec!["lane-0".to_string()], 1, 0, "held-a".to_string())
            .await
            .unwrap();
        let held_b = scheduler
            .acquire(vec!["lane-1".to_string()], 1, 0, "held-b".to_string())
            .await
            .unwrap();
        let held_c = scheduler
            .acquire(vec!["lane-2".to_string()], 1, 0, "held-c".to_string())
            .await
            .unwrap();
        let queued_juror = tokio::spawn({
            let scheduler = scheduler.clone();
            async move {
                scheduler
                    .acquire(
                        vec![
                            "lane-0".to_string(),
                            "lane-1".to_string(),
                            "lane-2".to_string(),
                        ],
                        100,
                        0,
                        "queued-flexible-juror".to_string(),
                    )
                    .await
                    .unwrap()
            }
        });
        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            loop {
                if scheduler.inner.state.lock().unwrap().pending.len() == 1 {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("the flexible juror queued behind the three occupied hosts");

        drop(held_a);
        let downstream = scheduler
            .acquire(
                vec!["lane-0".to_string()],
                1,
                3,
                "pair-dependent-proof".to_string(),
            )
            .await
            .unwrap();
        assert_eq!(downstream.lane.token, "lane-0");
        assert!(
            !queued_juror.is_finished(),
            "the already queued flexible juror must not consume the proof's only host"
        );

        drop(held_b);
        let queued_juror = queued_juror.await.unwrap();
        assert_eq!(queued_juror.lane.token, "lane-1");
        drop(held_c);
    }

