    #[tokio::test]
    async fn brokerless_one_lane_runs_one_real_low_confidence_retry() {
        const MODEL: &str = "single-logical-model";
        const FROZEN_SPEC: &str = include_str!("../../../../evals/swarm-bench/spec-build-sb7.md");
        let harness = pillar_logical_replay_harness(MODEL).await;
        let outcome = harness
            .dispatcher
            .research_by_pillars(
                FROZEN_SPEC,
                Arc::new(Vec::new()),
                vec![("single-device".to_string(), MODEL.to_string())],
                MODEL,
            )
            .await
            .unwrap();
        assert_eq!(outcome.opening.pillars.len(), 1);
        assert_eq!(outcome.reports.len(), 1);
        assert_eq!(outcome.retries, 1);
        assert_eq!(outcome.provider_calls, 3);
        assert_eq!(outcome.reports[0].effective_confidence, Confidence::Low);
        assert!(!outcome.reports[0].unresolved_uncertainties.is_empty());
        let calls = harness.provider.calls();
        let owner_calls = calls
            .iter()
            .filter(|call| call.phase == "owner")
            .collect::<Vec<_>>();
        assert_eq!(
            owner_calls.len(),
            2,
            "calls={calls:?}; events={:?}",
            harness.sink.values()
        );
        assert!(owner_calls.iter().all(|call| call.model == MODEL));
    }

    #[tokio::test]
    async fn frozen_v20_replay_selects_pillars_once_retries_only_low_confidence_and_dispatches_build(
    ) {
        const PLANNER_MODEL: &str = "v20-replay-planner";
        const WORKER_B: &str = "v20-replay-worker-b";
        const WORKER_C: &str = "v20-replay-worker-c";
        const HOST_A: &str = "v20-replay-host-a";
        const HOST_B: &str = "v20-replay-host-b";
        const HOST_C: &str = "v20-replay-host-c";
        const FROZEN_SPEC: &str = include_str!("../../../../evals/swarm-bench/spec-build-sb7.md");

        assert_eq!(
            content_sha256(FROZEN_SPEC),
            "56f66c21c3557e9cbf6bccc4d4d01059ad88e4ee610e71f4cf67a8a34c330129"
        );
        let requirement_inventory = normalized_requirement_inventory(FROZEN_SPEC);
        assert_eq!(requirement_inventory.len(), 197);
        assert!(pillar_prebuild_selected(true, true));
        assert!(pillar_prebuild_selected(false, true));
        assert!(!pillar_prebuild_selected(true, false));

        let lanes = [
            ("pillar-replay-lane-a", PLANNER_MODEL, HOST_A),
            ("pillar-replay-lane-b", WORKER_B, HOST_B),
            ("pillar-replay-lane-c", WORKER_C, HOST_C),
        ];
        let harness = pillar_replay_runtime_harness(&lanes).await;
        let worker_devices = vec![
            ("device-a".to_string(), PLANNER_MODEL.to_string()),
            ("device-b".to_string(), WORKER_B.to_string()),
            ("device-c".to_string(), WORKER_C.to_string()),
        ];
        let outcome = harness
            .dispatcher
            .research_by_pillars(
                FROZEN_SPEC,
                Arc::new(Vec::new()),
                worker_devices,
                PLANNER_MODEL,
            )
            .await
            .expect("frozen V20 fixture did not finish the production pillar research path");

        assert_eq!(outcome.opening.requirements.len(), 197);
        assert_eq!(outcome.opening.pillars.len(), 3);
        let exact_cover = outcome
            .opening
            .pillars
            .iter()
            .flat_map(|pillar| pillar.requirement_ids.iter().cloned())
            .collect::<Vec<_>>();
        assert_eq!(exact_cover.len(), 197);
        assert_eq!(
            exact_cover.iter().cloned().collect::<HashSet<_>>().len(),
            197,
            "the opener overlapped authored requirements between pillars"
        );
        assert_eq!(
            outcome.provider_calls, 5,
            "one opener plus four owner calls"
        );
        assert_eq!(outcome.retries, 1);
        assert!(outcome.synthesis.chars().count() <= 64_000);
        assert!(outcome.worker_context.contains(&outcome.synthesis));
        for requirement in &outcome.opening.requirements {
            assert!(
                outcome.synthesis.contains(&requirement.id),
                "synthesis starved {}",
                requirement.id
            );
        }

        let research_events = harness.sink.values();
        let owner_starts = research_events
            .iter()
            .filter(|event| event["event"] == "pillar_owner_attempt_started")
            .collect::<Vec<_>>();
        assert_eq!(
            owner_starts
                .iter()
                .filter(|event| event["attempt_ordinal"] == 1)
                .count(),
            3
        );
        let retries = owner_starts
            .iter()
            .filter(|event| event["attempt_ordinal"] == 2)
            .collect::<Vec<_>>();
        assert_eq!(retries.len(), 1);
        assert_eq!(retries[0]["pillar_id"], "pillar-03");
        let primary_host = owner_starts
            .iter()
            .find(|event| event["pillar_id"] == "pillar-03" && event["attempt_ordinal"] == 1)
            .and_then(|event| event["physical_host_id"].as_str())
            .expect("low-confidence primary attempt lost its physical host");
        assert_ne!(
            retries[0]["physical_host_id"].as_str(),
            Some(primary_host),
            "the focused retry reused the same physical host"
        );

        let (_plan_json, dag) = harness
            .dispatcher
            .plan_from_pillars(FROZEN_SPEC, &outcome, PLANNER_MODEL)
            .await
            .expect("frozen V20 fixture did not finish its one production synthesis call");
        let calls = harness.provider.calls();
        assert_eq!(
            calls.iter().filter(|call| call.phase == "opening").count(),
            1
        );
        assert_eq!(calls.iter().filter(|call| call.phase == "owner").count(), 4);
        assert_eq!(
            calls.iter().filter(|call| call.phase == "planner").count(),
            1
        );
        assert_eq!(
            calls
                .iter()
                .filter(|call| call.phase == "planner")
                .map(|call| call.model.as_str())
                .collect::<Vec<_>>(),
            [PLANNER_MODEL]
        );
        let planner_prompt = calls
            .iter()
            .find(|call| call.phase == "planner")
            .map(|call| call.user.as_str())
            .expect("the one planner call lost its exact input");
        assert!(planner_prompt.contains("pillar-01 exposes one stable capability interface"));
        assert!(planner_prompt.contains("Run the exclusive acceptance path for pillar-01"));
        assert!(
            calls.iter().all(|call| call.user_chars > 0),
            "a production model round lost its typed input"
        );

        let unresolved_requirement = outcome.opening.pillars[2].requirement_ids[0].clone();
        let routed_task = dag.tasks.get("build-pillar-03").unwrap_or_else(|| {
            let degraded = harness
                .sink
                .values()
                .into_iter()
                .find(|event| event["event"] == "pillar_synthesis_plan_degraded")
                .and_then(|event| event["reason"].as_str().map(str::to_string));
            panic!(
                "low-confidence capability task disappeared; tasks={:?}; degraded={degraded:?}",
                dag.tasks.keys().collect::<Vec<_>>(),
            )
        });
        assert!(routed_task
            .spec
            .description
            .contains("UNRESOLVED REQUIREMENT ROUTE"));
        assert!(routed_task
            .spec
            .description
            .contains(&unresolved_requirement));

        let events = harness.sink.values();
        assert!(
            !events
                .iter()
                .any(|event| event["event"] == "pillar_synthesis_plan_degraded"),
            "the recorded synthesis must compile directly, not enter the deterministic fallback"
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| event["event"] == "pillar_synthesis_plan_started")
                .count(),
            1
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| event["event"] == "pillar_synthesis_plan_completed")
                .count(),
            1
        );
        for forbidden in [
            "jury",
            "adjudication",
            "citation",
            "detail",
            "plan_review",
            "planning_audit",
            "prereview",
        ] {
            assert!(
                !events.iter().any(|event| event["event"]
                    .as_str()
                    .is_some_and(|name| name.contains(forbidden))),
                "legacy `{forbidden}` round leaked into the pillar replay"
            );
        }

        let build_dispatcher = Arc::new(RuntimeBuildDispatchProbe {
            starts: AtomicUsize::new(0),
        });
        let report = Scheduler::new(
            vec![
                DeviceCfg {
                    id: "v20-build-a".to_string(),
                    model_id: PLANNER_MODEL.to_string(),
                    weight: 1,
                    enabled: true,
                    speed_weight: 1,
                    supervision: false,
                },
                DeviceCfg {
                    id: "v20-build-b".to_string(),
                    model_id: WORKER_B.to_string(),
                    weight: 1,
                    enabled: true,
                    speed_weight: 1,
                    supervision: false,
                },
                DeviceCfg {
                    id: "v20-build-c".to_string(),
                    model_id: WORKER_C.to_string(),
                    weight: 1,
                    enabled: true,
                    speed_weight: 1,
                    supervision: false,
                },
            ],
            1,
        )
        .run(
            dag,
            build_dispatcher.clone() as Arc<dyn TaskDispatcher>,
            FROZEN_SPEC.to_string(),
        )
        .await
        .expect("frozen V20 pillar replay never reached real Scheduler build dispatch");
        assert_eq!(build_dispatcher.starts.load(AtomicOrdering::SeqCst), 4);
        assert_eq!(report.done.len(), 4);
        assert!(report.failed.is_empty());
        tokio::time::timeout(Duration::from_secs(5), harness.control.wait_until_drained())
            .await
            .expect("frozen V20 replay did not drain provider lifecycle")
            .unwrap();
        assert_eq!(harness.control.occupancy().await, (0, 0));
    }

    fn synthesis_authority_runtime_fixture(
        planner_model: &str,
        healthy_model: &str,
        lanes: Vec<ResearchPhysicalLane>,
    ) -> (String, PillarResearchOutcome, serde_json::Value) {
        let binding_spec = "Implement the isolated core behavior in src/core.rs.".to_string();
        let opening = ResearchPillarOpening {
            requirements: vec![AuthoredRequirement {
                id: "REQ-core".to_string(),
                text: binding_spec.clone(),
                critical: true,
            }],
            pillars: vec![ResearchPillar {
                id: "core".to_string(),
                title: "Core behavior".to_string(),
                objective: "Implement only the core behavior".to_string(),
                requirement_ids: vec!["REQ-core".to_string()],
                dependencies: Vec::new(),
                research_questions: vec!["Which module owns core behavior?".to_string()],
                acceptance_criteria: vec!["The core contract test passes".to_string()],
                exclusions: vec!["Do not add sibling behavior".to_string()],
            }],
            integration_contract: IntegrationContract {
                owner: planner_model.to_string(),
                integration_required: false,
                objective: "No cross-pillar integration is required".to_string(),
                interface_invariants: vec!["Keep the core interface stable".to_string()],
                acceptance_criteria: vec!["Run the isolated core test".to_string()],
            },
        };
        let reports = vec![CompiledPillarReport {
            pillar_id: "core".to_string(),
            reported_confidence: Confidence::High,
            effective_confidence: Confidence::High,
            claims: vec![goose_swarm::CompiledResearchClaim {
                requirement_id: "REQ-core".to_string(),
                statement: "src/core.rs owns the complete isolated core behavior".to_string(),
                reported_class: EvidenceClass::Supported,
                effective_class: EvidenceClass::Supported,
                provenance: goose_swarm::ProvenanceMatch::NotClaimed,
            }],
            missing_requirement_ids: Vec::new(),
            unresolved_uncertainties: Vec::new(),
            acceptance_tests: vec!["cargo test core_contract".to_string()],
            interfaces: vec!["run_core(input) -> output".to_string()],
            exclusions: vec!["Application composition".to_string()],
        }];
        let synthesis = render_synthesis_input(&reports, 64_000);
        let worker_context = synthesis.clone();
        let outcome = PillarResearchOutcome {
            opening,
            reports,
            lanes,
            synthesis,
            verified_facts: String::new(),
            worker_context,
            provider_calls: 0,
            retries: 0,
        };
        let plan = serde_json::json!({
            "task_coverage": [{
                "task_id": "build-core",
                "owns_requirement_ids": ["REQ-core"],
                "applies_requirement_ids": [],
                "verifies_requirement_ids": [],
                "evidence_ids": []
            }],
            "task_specs": [{
                "task_id": "build-core",
                "objective": "Implement the complete isolated core behavior",
                "module_boundary": "Own only src/core.rs",
                "concrete_steps": ["Implement run_core in src/core.rs"],
                "interfaces": [],
                "edge_cases": ["Reject empty input deterministically"],
                "acceptance_evidence": ["cargo test core_contract passes"],
                "exclusions": ["Do not edit application composition"]
            }],
            "uncertainty_routes": [],
            "canonical_plan": {
                "subtasks": [{
                    "id": "build-core",
                    "description": "Semantic model plan for the isolated core",
                    "difficulty": "hard",
                    "model": healthy_model,
                    "depends_on": [],
                    "files": ["src/core.rs"]
                }],
                "integration": "Run cargo test core_contract"
            }
        });
        (binding_spec, outcome, plan)
    }

    #[tokio::test]
    async fn r5_410_byte_unproven_planner_reroutes_without_fallback_or_early_build_dispatch() {
        const MODEL_A: &str = "r5-synthesis-model-a";
        const MODEL_B: &str = "r5-synthesis-model-b";
        const HOST_A: &str = "r5-synthesis-host-a";
        const HOST_B: &str = "r5-synthesis-host-b";
        let lanes = [
            ("r5-synthesis-lane-a", MODEL_A, HOST_A),
            ("r5-synthesis-lane-b", MODEL_B, HOST_B),
        ];
        let fixture_lanes = lanes
            .iter()
            .map(|(token, model, host)| ResearchPhysicalLane {
                token: (*token).to_string(),
                model_id: (*model).to_string(),
                physical_host_id: (*host).to_string(),
                verified_physical: true,
            })
            .collect::<Vec<_>>();
        let (binding_spec, outcome, valid_plan) =
            synthesis_authority_runtime_fixture(MODEL_A, MODEL_B, fixture_lanes);
        compile_pillar_plan(
            &valid_plan.to_string(),
            &outcome.opening,
            &outcome.reports,
            &[MODEL_A.to_string(), MODEL_B.to_string()],
            &binding_spec,
        )
        .expect("the healthy-lane fixture must be an accepted typed plan");
        let harness = research_correction_runtime_harness(
            &lanes,
            HashMap::from([
                (MODEL_A.to_string(), Vec::new()),
                (MODEL_B.to_string(), vec![valid_plan]),
            ]),
        )
        .await;
        harness.provider.drop_next_stream_unproven(MODEL_A);
        harness.provider.block_next_call(MODEL_B);
        let build_dispatcher = Arc::new(RuntimeBuildDispatchProbe {
            starts: AtomicUsize::new(0),
        });

        let run = tokio::spawn({
            let dispatcher = harness.dispatcher.clone();
            let build_dispatcher = build_dispatcher.clone();
            let binding_spec = binding_spec.clone();
            async move {
                let (_, dag) = dispatcher
                    .plan_from_pillars(&binding_spec, &outcome, MODEL_A)
                    .await?;
                assert_eq!(
                    build_dispatcher.starts.load(AtomicOrdering::SeqCst),
                    0,
                    "a typed plan had not yet entered Scheduler dispatch"
                );
                Scheduler::new(
                    vec![DeviceCfg {
                        id: "r5-synthesis-build-node".to_string(),
                        model_id: MODEL_B.to_string(),
                        weight: 1,
                        enabled: true,
                        speed_weight: 1,
                        supervision: false,
                    }],
                    1,
                )
                .run(
                    dag,
                    build_dispatcher as Arc<dyn TaskDispatcher>,
                    binding_spec,
                )
                .await
            }
        });
        tokio::time::timeout(
            Duration::from_secs(5),
            harness.provider.wait_for_blocked_call(),
        )
        .await
        .expect("the healthy planner lane was not admitted after the unproven drop");
        assert_eq!(
            build_dispatcher.starts.load(AtomicOrdering::SeqCst),
            0,
            "build dispatch began before a typed plan was accepted"
        );
        assert!(!harness.sink.has("pillar_synthesis_plan_completed"));
        harness.provider.release_blocked_call();
        let report = tokio::time::timeout(Duration::from_secs(8), run)
            .await
            .expect("the rerouted planner did not finish")
            .unwrap()
            .expect("the rerouted typed plan did not reach build dispatch");
        assert_eq!(build_dispatcher.starts.load(AtomicOrdering::SeqCst), 1);
        assert_eq!(report.done, vec!["build-core"]);
        assert_eq!(harness.provider.call_count(MODEL_A), 1);
        assert_eq!(harness.provider.call_count(MODEL_B), 1);
        assert_eq!(
            harness
                .provider
                .late_unproven_chunks_polled
                .load(AtomicOrdering::SeqCst),
            0,
            "the 410-byte unproven stream was polled after its network drop"
        );
        let correction_input = harness.provider.user_inputs(MODEL_B);
        assert_eq!(correction_input.len(), 1);
        assert!(correction_input[0].contains("planner_correction"));
        assert!(correction_input[0].contains("provider attempt unavailable"));

        let events = harness.sink.values();
        let rejected = events
            .iter()
            .find(|event| event["event"] == "pillar_synthesis_plan_attempt_rejected")
            .expect("the unproven planner attempt was not retained as a rejection");
        assert_eq!(rejected["physical_host_id"], HOST_A);
        assert_eq!(rejected["stage"], "provider");
        assert_eq!(rejected["semantic_attempt_preserved"], false);
        assert_eq!(rejected["unproven_partial_output_quarantined"], true);
        assert_eq!(rejected["next_distinct_lane"], HOST_B);
        let completed = events
            .iter()
            .find(|event| event["event"] == "pillar_synthesis_plan_completed")
            .expect("the accepted typed plan did not terminalize the sole authority");
        assert_eq!(completed["logical_planner_authorities"], 1);
        assert_eq!(completed["planner_lane_invocations"], 2);
        assert_eq!(completed["fallback_authority"], false);
        let serialized_events = serde_json::to_string(&events).unwrap();
        assert!(!serialized_events.contains("deterministic-disjoint-pillar-build-plan"));
        assert!(!serialized_events.contains("pillar_synthesis_plan_degraded"));
        assert!(!serialized_events.contains("pillar-build-01"));
        assert!(events.iter().any(|event| {
            event["event"] == "provider_stream_progress" && event["structured_output_bytes"] == 410
        }));
        tokio::time::timeout(Duration::from_secs(5), harness.control.wait_until_drained())
            .await
            .expect("the planner failover lifecycle did not drain")
            .unwrap();
        assert_eq!(harness.control.occupancy().await, (0, 1));
    }

    #[tokio::test]
    async fn repeated_planner_diagnostic_changes_semantic_repair_strategy_without_fallback() {
        const MODEL_A: &str = "semantic-continuation-model-a";
        const MODEL_B: &str = "semantic-continuation-model-b";
        const HOST_A: &str = "semantic-continuation-host-a";
        const HOST_B: &str = "semantic-continuation-host-b";
        let lanes = [
            ("semantic-continuation-lane-a", MODEL_A, HOST_A),
            ("semantic-continuation-lane-b", MODEL_B, HOST_B),
        ];
        let fixture_lanes = lanes
            .iter()
            .map(|(token, model, host)| ResearchPhysicalLane {
                token: (*token).to_string(),
                model_id: (*model).to_string(),
                physical_host_id: (*host).to_string(),
                verified_physical: true,
            })
            .collect::<Vec<_>>();
        let (binding_spec, outcome, valid_plan) =
            synthesis_authority_runtime_fixture(MODEL_A, MODEL_B, fixture_lanes);
        let rejected_semantic_plan = serde_json::json!({
            "semantic_note": "preserve this model-authored module responsibility",
            "canonical_plan": {
                "subtasks": [{
                    "id": "build-core",
                    "description": "Keep this model-authored responsibility unchanged"
                }]
            }
        });
        let harness = research_correction_runtime_harness(
            &lanes,
            HashMap::from([
                (
                    MODEL_A.to_string(),
                    vec![
                        rejected_semantic_plan.clone(),
                        rejected_semantic_plan.clone(),
                        valid_plan,
                    ],
                ),
                (
                    MODEL_B.to_string(),
                    vec![rejected_semantic_plan.clone(), rejected_semantic_plan],
                ),
            ]),
        )
        .await;

        let (_, dag) = tokio::time::timeout(
            Duration::from_secs(8),
            harness
                .dispatcher
                .plan_from_pillars(&binding_spec, &outcome, MODEL_A),
        )
        .await
        .expect("the focused semantic continuation did not converge")
        .expect("ordinary compiler diagnostics stopped the run");
        assert_eq!(
            dag.tasks.keys().cloned().collect::<Vec<_>>(),
            ["build-core"]
        );
        assert_eq!(harness.provider.call_count(MODEL_A), 3);
        assert_eq!(harness.provider.call_count(MODEL_B), 2);
        let model_b_inputs = harness.provider.user_inputs(MODEL_B);
        assert!(model_b_inputs[0].contains("preserved_semantic_attempt"));
        assert!(model_b_inputs[0].contains("preserve this model-authored module responsibility"));

        let events = harness.sink.values();
        let continuations = events
            .iter()
            .filter(|event| event["event"] == "pillar_synthesis_plan_semantic_continuation")
            .collect::<Vec<_>>();
        assert_eq!(continuations.len(), 2);
        assert_eq!(continuations[0]["unchanged_diagnostic_recurrence"], 1);
        assert_eq!(continuations[1]["unchanged_diagnostic_recurrence"], 2);
        assert!(continuations[1]["strategy"]
            .as_str()
            .unwrap()
            .contains("rebuild the typed task_coverage and task_specs envelope"));
        let serialized_events = serde_json::to_string(&events).unwrap();
        assert!(!serialized_events.contains("pillar_synthesis_plan_authority_exhausted"));
        assert!(!serialized_events.contains("pillar_synthesis_plan_degraded"));
        assert!(!serialized_events.contains("deterministic-disjoint-pillar-build-plan"));
        assert_eq!(harness.control.occupancy().await, (0, 0));
    }

    #[tokio::test]
    async fn empty_or_malformed_json_does_not_replace_the_last_substantive_semantic_plan() {
        const MODEL_A: &str = "semantic-preservation-model-a";
        const MODEL_B: &str = "semantic-preservation-model-b";
        const MODEL_C: &str = "semantic-preservation-model-c";
        const HOST_A: &str = "semantic-preservation-host-a";
        const HOST_B: &str = "semantic-preservation-host-b";
        const HOST_C: &str = "semantic-preservation-host-c";
        let lanes = [
            ("semantic-preservation-lane-a", MODEL_A, HOST_A),
            ("semantic-preservation-lane-b", MODEL_B, HOST_B),
            ("semantic-preservation-lane-c", MODEL_C, HOST_C),
        ];
        let fixture_lanes = lanes
            .iter()
            .map(|(token, model, host)| ResearchPhysicalLane {
                token: (*token).to_string(),
                model_id: (*model).to_string(),
                physical_host_id: (*host).to_string(),
                verified_physical: true,
            })
            .collect::<Vec<_>>();
        let (binding_spec, outcome, valid_plan) =
            synthesis_authority_runtime_fixture(MODEL_A, MODEL_B, fixture_lanes);
        let mut compiler_rejected = valid_plan.clone();
        compiler_rejected["task_specs"][0]["task_id"] = serde_json::json!("mismatched-task-id");
        compiler_rejected["canonical_plan"]["subtasks"][0]["description"] =
            serde_json::json!("preserve this exact model-authored semantic responsibility");
        let harness = research_correction_runtime_harness(
            &lanes,
            HashMap::from([
                (MODEL_A.to_string(), vec![compiler_rejected]),
                (MODEL_B.to_string(), vec![serde_json::json!({}), valid_plan]),
                (MODEL_C.to_string(), Vec::new()),
            ]),
        )
        .await;
        harness
            .provider
            .queue_finished_text(MODEL_C, "{malformed planner output");

        let (_, dag) = tokio::time::timeout(
            Duration::from_secs(8),
            harness
                .dispatcher
                .plan_from_pillars(&binding_spec, &outcome, MODEL_A),
        )
        .await
        .expect("semantic continuation did not recover after malformed JSON")
        .expect("malformed JSON stopped the sole logical planner authority");
        assert_eq!(
            dag.tasks.keys().cloned().collect::<Vec<_>>(),
            ["build-core"]
        );
        assert_eq!(harness.provider.call_count(MODEL_A), 1);
        assert_eq!(harness.provider.call_count(MODEL_B), 2);
        assert_eq!(harness.provider.call_count(MODEL_C), 1);
        let model_b_inputs = harness.provider.user_inputs(MODEL_B);
        assert_eq!(model_b_inputs.len(), 2);
        for input in &model_b_inputs {
            assert!(input.contains("preserve this exact model-authored semantic responsibility"));
        }
        assert!(model_b_inputs[1].contains("malformed planner output"));
        let model_c_inputs = harness.provider.user_inputs(MODEL_C);
        assert_eq!(model_c_inputs.len(), 1);
        assert!(model_c_inputs[0]
            .contains("preserve this exact model-authored semantic responsibility"));
        let schema_empty_rejection = harness
            .sink
            .values()
            .into_iter()
            .find(|event| {
                event["event"] == "pillar_synthesis_plan_attempt_rejected"
                    && event["stage"] == "compiler"
                    && event["candidate_semantic_score"] == 0
            })
            .expect("schema-empty JSON was not retained as a focused rejection");
        assert!(schema_empty_rejection["preserved_semantic_score"]
            .as_u64()
            .is_some_and(|score| score > 0));
        assert_eq!(schema_empty_rejection["semantic_attempt_preserved"], true);
        let json_rejection = harness
            .sink
            .values()
            .into_iter()
            .find(|event| {
                event["event"] == "pillar_synthesis_plan_attempt_rejected"
                    && event["stage"] == "json"
            })
            .expect("malformed JSON was not retained as a focused rejection");
        assert_eq!(json_rejection["semantic_attempt_preserved"], true);
        assert_eq!(json_rejection["malformed_terminal_output_preserved"], true);
        assert_eq!(harness.control.occupancy().await, (0, 0));
    }

    #[tokio::test]
    async fn all_unavailable_planner_lanes_park_for_route_recovery_instead_of_stopping() {
        const MODEL_A: &str = "route-recovery-model-a";
        const MODEL_B: &str = "route-recovery-model-b";
        const HOST_A: &str = "route-recovery-host-a";
        const HOST_B: &str = "route-recovery-host-b";
        let lanes = [
            ("route-recovery-lane-a", MODEL_A, HOST_A),
            ("route-recovery-lane-b", MODEL_B, HOST_B),
        ];
        let fixture_lanes = lanes
            .iter()
            .map(|(token, model, host)| ResearchPhysicalLane {
                token: (*token).to_string(),
                model_id: (*model).to_string(),
                physical_host_id: (*host).to_string(),
                verified_physical: true,
            })
            .collect::<Vec<_>>();
        let (binding_spec, outcome, _) =
            synthesis_authority_runtime_fixture(MODEL_A, MODEL_B, fixture_lanes);
        let harness = research_correction_runtime_harness(
            &lanes,
            HashMap::from([
                (MODEL_A.to_string(), Vec::new()),
                (MODEL_B.to_string(), Vec::new()),
            ]),
        )
        .await;
        harness.provider.drop_next_stream_unproven(MODEL_A);
        harness.provider.drop_next_stream_unproven(MODEL_B);
        let planner = tokio::spawn({
            let dispatcher = harness.dispatcher.clone();
            async move {
                dispatcher
                    .plan_from_pillars(&binding_spec, &outcome, MODEL_A)
                    .await
            }
        });
        let waiting = harness
            .sink
            .wait_for("pillar_synthesis_plan_route_recovery_waiting")
            .await;
        assert_eq!(waiting["logical_planner_authorities"], 1);
        assert_eq!(waiting["fallback_authority"], false);
        assert_eq!(waiting["next_phase"], "planner-route-recovery");
        assert!(
            !planner.is_finished(),
            "route recovery was reduced to a stop"
        );
        assert!(!harness.sink.has("pillar_synthesis_plan_completed"));
        assert!(!harness
            .sink
            .values()
            .iter()
            .any(|event| event["event"] == "pillar_synthesis_plan_authority_exhausted"));
        planner.abort();
        let _ = planner.await;
        tokio::time::timeout(Duration::from_secs(5), harness.control.wait_until_drained())
            .await
            .expect("the parked unavailable planner lanes did not drain into quarantine")
            .unwrap();
        assert_eq!(harness.control.occupancy().await, (0, 2));
    }

    fn requirement_binding_runtime_fixture(
        runtime_model: &str,
    ) -> (String, String, serde_json::Value, serde_json::Value) {
        let binding_spec =
            "Build a runnable application that prints READY when invoked.".to_string();
        let requirement = normalized_requirement_inventory(&binding_spec)
            .into_iter()
            .next()
            .expect("runtime binding fixture has one requirement");
        let requirement_id = requirement.id;
        let plan = serde_json::json!({
            "subtasks": [{
                "id": "build-app",
                "description": "Implement the runnable application and its exact READY output",
                "difficulty": "hard",
                "model": runtime_model,
                "depends_on": [],
                "files": ["main.py"]
            }],
            "integration": "Run the application and verify READY"
        });
        let binding = serde_json::json!({
            "bindings": [{
                "task_id": "build-app",
                "owns_requirement_ids": [requirement_id.clone()],
                "applies_requirement_ids": [],
                "verifies_requirement_ids": [],
                "depends_on": [],
                "owned_files": ["main.py"],
                "slices": [{
                    "id": "runnable-output",
                    "objective": "Implement the runnable application and exact READY output",
                    "requirement_ids": [requirement_id.clone()],
                    "evidence_ids": [],
                    "acceptance_evidence": ["Invoking the application prints READY"]
                }]
            }],
            "interfaces": [],
            "artifact_evidence": []
        });
        let detail = serde_json::json!({
            "requirement_citations": [{
                "requirement_id": requirement_id,
                "applies_as": "The application must be runnable and print READY."
            }],
            "implementation_steps": ["Create the executable entry point and print READY."],
            "edge_cases": ["Do not emit extra output."],
            "acceptance_checks": ["Run the entry point and compare stdout exactly with READY."]
        });
        (binding_spec, plan.to_string(), binding, detail)
    }

    #[tokio::test]
    async fn production_requirement_binding_agent_error_with_unproven_request_retries_distinct_host_and_starts_build(
    ) {
        const MODEL_A: &str = "runtime-binding-model-a";
        const MODEL_B: &str = "runtime-binding-model-b";
        const HOST_A: &str = "runtime-binding-host-a";
        const HOST_B: &str = "runtime-binding-host-b";
        let (binding_spec, plan, binding, detail) = requirement_binding_runtime_fixture(MODEL_B);
        let mut scripts = HashMap::new();
        scripts.insert(MODEL_A.to_string(), Vec::new());
        scripts.insert(MODEL_B.to_string(), vec![binding, detail]);
        let harness = research_correction_runtime_harness(
            &[
                ("binding-lane-a", MODEL_A, HOST_A),
                ("binding-lane-b", MODEL_B, HOST_B),
            ],
            scripts,
        )
        .await;
        harness.provider.drop_next_stream_unproven(MODEL_A);
        harness
            .provider
            .queue_finished_text(MODEL_B, "# main.py\ndef main(): ...");

        let inject_result_error = Arc::new(std::sync::atomic::AtomicBool::new(true));
        let (_compiled_plan, dag) = PRE_SCHEDULER_TEST_RESULT_ERROR
            .scope(
                inject_result_error.clone(),
                harness.dispatcher.detail_plan(
                    MODEL_A,
                    vec![MODEL_B.to_string()],
                    &binding_spec,
                    "",
                    &plan,
                ),
            )
            .await
            .expect("the frozen binding did not continue on the distinct healthy host");
        assert!(
            !inject_result_error.load(Ordering::SeqCst),
            "the first ambiguous provider outcome did not exercise the agent-error path"
        );

        assert_eq!(harness.provider.call_count(MODEL_A), 1);
        assert!(harness.provider.call_count(MODEL_B) >= 2);
        let first_digest = harness.provider.request_digests(MODEL_A);
        let second_digest = harness.provider.request_digests(MODEL_B);
        assert_eq!(first_digest.len(), 1);
        assert_eq!(first_digest[0], second_digest[0]);
        assert_eq!(
            harness
                .provider
                .late_unproven_chunks_polled
                .load(AtomicOrdering::SeqCst),
            0,
            "a stale final output after the ambiguous drop was polled"
        );
        let events = harness.sink.values();
        let rescheduled = events
            .iter()
            .find(|event| event["event"] == "requirement_binding_rescheduled")
            .expect("the requirement binding retry was not recorded");
        assert_eq!(rescheduled["failed_physical_host_id"], HOST_A);
        assert_eq!(rescheduled["next_physical_host_id"], HOST_B);
        assert_eq!(rescheduled["provider_terminal_proven"], false);
        let attempts = events
            .iter()
            .filter(|event| event["event"] == "requirement_binding_attempt_started")
            .collect::<Vec<_>>();
        assert_eq!(attempts.len(), 2);
        assert_eq!(
            attempts
                .iter()
                .map(|event| event["authority_input_digest"].as_str().unwrap())
                .collect::<HashSet<_>>()
                .len(),
            1
        );
        assert!(!events.iter().any(|event| {
            event["event"] == "broker_provider_terminal_observed"
                && event["admission"]["physical_host_id"] == HOST_A
        }));
        assert!(!events.iter().any(|event| {
            event["event"] == "broker_admission_released"
                && event["receipt"]["admission"]["physical_host_id"] == HOST_A
        }));

        let build_dispatcher = Arc::new(RuntimeBuildDispatchProbe {
            starts: AtomicUsize::new(0),
        });
        let report = Scheduler::new(
            vec![DeviceCfg {
                id: "runtime-binding-build-node".to_string(),
                model_id: MODEL_B.to_string(),
                weight: 1,
                enabled: true,
                speed_weight: 1,
                supervision: false,
            }],
            1,
        )
        .run(
            dag,
            build_dispatcher.clone() as Arc<dyn TaskDispatcher>,
            binding_spec,
        )
        .await
        .expect("the resolved requirement binding did not enter Scheduler build dispatch");
        assert_eq!(build_dispatcher.starts.load(AtomicOrdering::SeqCst), 1);
        assert_eq!(report.done.len(), 1);
        tokio::time::timeout(Duration::from_secs(5), harness.control.wait_until_drained())
            .await
            .expect("the quarantined authority attempt blocked phase drain")
            .unwrap();
        assert_eq!(harness.control.occupancy().await, (0, 1));
    }

    #[tokio::test]
    async fn production_requirement_binding_all_distinct_hosts_ambiguous_is_typed_exhaustion() {
        const MODEL_A: &str = "runtime-binding-exhausted-model-a";
        const MODEL_B: &str = "runtime-binding-exhausted-model-b";
        const HOST_A: &str = "runtime-binding-exhausted-host-a";
        const HOST_B: &str = "runtime-binding-exhausted-host-b";
        let harness = research_correction_runtime_harness(
            &[
                ("binding-exhausted-lane-a", MODEL_A, HOST_A),
                ("binding-exhausted-lane-b", MODEL_B, HOST_B),
            ],
            HashMap::from([
                (MODEL_A.to_string(), Vec::new()),
                (MODEL_B.to_string(), Vec::new()),
            ]),
        )
        .await;
        harness.provider.drop_next_stream_unproven(MODEL_A);
        harness.provider.drop_next_stream_unproven(MODEL_B);

        let error = match harness
            .dispatcher
            .run_requirement_binding_authority(
                MODEL_A,
                &[MODEL_B.to_string()],
                "frozen requirement binding system",
                "frozen requirement binding input",
                &serde_json::json!({"type": "object"}),
                "frozen-authority-digest",
            )
            .await
        {
            Ok(_) => panic!("all ambiguous physical hosts unexpectedly produced authority"),
            Err(error) => error,
        };
        let exhausted = error
            .downcast_ref::<RequirementBindingAuthorityExhausted>()
            .expect("authority exhaustion was reduced to an untyped string");
        assert_eq!(exhausted.attempts.len(), 2);
        assert_eq!(
            exhausted
                .attempts
                .iter()
                .map(|attempt| attempt.physical_host_id.as_str())
                .collect::<Vec<_>>(),
            [HOST_A, HOST_B]
        );
        assert_eq!(
            harness.provider.request_digests(MODEL_A),
            harness.provider.request_digests(MODEL_B)
        );
        assert_eq!(
            harness
                .provider
                .late_unproven_chunks_polled
                .load(AtomicOrdering::SeqCst),
            0
        );
        let events = harness.sink.values();
        let exhausted_event = events
            .iter()
            .find(|event| event["event"] == "requirement_binding_authority_exhausted")
            .expect("typed authority exhaustion event was not emitted");
        assert_eq!(exhausted_event["provider_terminal_fabricated"], false);
        assert_eq!(
            exhausted_event["typed_failure"],
            "authority_transport_exhausted"
        );
        assert!(!events
            .iter()
            .any(|event| event["event"] == "broker_provider_terminal_observed"));
        tokio::time::timeout(Duration::from_secs(5), harness.control.wait_until_drained())
            .await
            .expect("fully quarantined authority attempts blocked phase drain")
            .unwrap();
        assert_eq!(harness.control.occupancy().await, (0, 2));
    }

